// Türkçe/OCR para formatı dönüştürücü
// Desteklenen: 3.000,00 | 3,000,00 (OCR) | 500,00 | 3.000 | 3000
function parseTrNumber(str) {
  if (!str) return 0;
  let s = str.trim().replace(/[*+]/g, "").trim();
  if (!s) return 0;

  const dotCount   = (s.match(/\./g) || []).length;
  const commaCount = (s.match(/,/g)  || []).length;

  // 3.000,00 → nokta=binlik, virgül=ondalık
  if (dotCount >= 1 && commaCount === 1) {
    return parseFloat(s.replace(/\./g, "").replace(",", ".")) || 0;
  }

  // 3,000,00 → OCR nokta yerine virgül koymuş: virgül(ler)=binlik, son virgül=ondalık
  if (commaCount >= 2) {
    const parts    = s.split(",");
    const lastPart = parts[parts.length - 1];  // ondalık kısım
    const whole    = parts.slice(0, -1).join(""); // binlik virgülleri sil
    return parseFloat(whole + "." + lastPart) || 0;
  }

  // 500,00 → tek virgül, 2 basamak → ondalık
  if (commaCount === 1) {
    const dec = s.split(",")[1] || "";
    if (dec.length <= 2) return parseFloat(s.replace(",", ".")) || 0;
    // 44,640 gibi → muhtemelen litre, ondalık say
    return parseFloat(s.replace(",", ".")) || 0;
  }

  // 3.000 → tek nokta, 3 basamak sonra → binlik
  if (dotCount === 1) {
    const dec = s.split(".")[1] || "";
    if (dec.length === 3) return parseFloat(s.replace(".", "")) || 0;
    return parseFloat(s) || 0;
  }

  // Birden fazla nokta: 1.000.000 → binlik
  if (dotCount >= 2) {
    return parseFloat(s.replace(/\./g, "")) || 0;
  }

  return parseFloat(s) || 0;
}

// Türkçe/OCR para sayısı regex: 3.000,00 | 3,000,00 | 500,00 | 3.000 | 3000
const TR_NUM_RE = /[*+]?\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{2})?(?!\d)/g;

function formatAd(ad) {
  const parts = (ad || "").trim().split(/\s+/);
  if (parts.length < 2) return (ad || "").toUpperCase();
  return parts.slice(0, -1).join(" ") + " " + parts[parts.length - 1].toUpperCase();
}

// DB'deki plakayı OCR okunmuş plakaya fuzzy eşleştir (1 karakter tolerans)
function plakaEsles(ocrRaw, dbPlakalar) {
  const normalize = (s) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");
  const ocr = normalize(ocrRaw);
  // Tam eşleşme önce
  const exact = dbPlakalar.find(p => normalize(p) === ocr);
  if (exact) return exact;
  // 1 karakter farkı tolerans (OCR hataları için)
  return dbPlakalar.find(p => {
    const db = normalize(p);
    if (Math.abs(db.length - ocr.length) > 1) return false;
    let diff = 0;
    const maxLen = Math.max(db.length, ocr.length);
    for (let i = 0; i < maxLen; i++) {
      if (db[i] !== ocr[i]) diff++;
      if (diff > 1) return false;
    }
    return true;
  }) || null;
}

function parseOcrText(text) {
  const lines = text.split("\n");
  let amount = null;
  const KEY_RE = /(GENEL\s*TOPLAM|TOPLAM|KRED[İI]|NAK[İI]T|TUTAR|TOTAL)/i;
  // Kimlik/no satırları: MERSİS, REF, ONAY, terminal vb. — tutar DEĞİLDİR,
  // fallback'te bunlardan sayı alınmaz (879 hatası: MERSİS 0879'dan geliyordu)
  const ID_RE = /(MERS[İI]S|REF|ONAY|TERM[İI]NAL|S[İI]C[İI]L|EK[ÜU]|Z\s*NO|F[İI][ŞS]\s*NO|[ÇC]EK\s*NO|MASA|K\.?\s*N\.?|VERG[İI]|V\.?D\.?|TAR[İI]H|SAAT|TEL|NO\s*[:.]|\bAID\b|BANKA|https?|WWW)/i;
  const numsOf = (s) => (s.match(TR_NUM_RE) || []).map(parseTrNumber).filter(n => n >= 1 && n <= 999999);
  // Para birimi (21.09.2026): $ / USD / € / EUR geçen belge TL değildir — panel TL ile kıyaslamaz
  const currency = /(\$|\bUSD\b)/.test(text) ? "USD" : /(€|\bEUR\b)/.test(text) ? "EUR" : "TRY";
  // Ara toplam / vergi hariç / KDV satırları TOPLAM sayılmaz (21.09.2026: "Total excluding tax" 100 okunuyordu)
  const ARA_RE = /(EXCLUDING|EXCL\.|SUBTOTAL|SUB\s*TOTAL|ARA\s*TOPLAM|HAR[İI][ÇC]|MATRAH|\bKDV\b|\bVAT\b|\bTAX\b|[İI]SKONTO|DISCOUNT)/i;
  // 0) En güçlü anahtarlar: AMOUNT DUE / GENEL TOPLAM / ÖDENECEK — ya da "$120.00 USD due …" biçimi
  for (let i = 0; i < lines.length && !amount; i++) {
    const ln = lines[i];
    if (/(AMOUNT\s*DUE|GENEL\s*TOPLAM|[ÖO]DENECEK\s*TUTAR|TOPLAM\s*TUTAR|GRAND\s*TOTAL)/i.test(ln) && !ARA_RE.test(ln)) {
      let nums = numsOf(ln);
      if (!nums.length && lines[i + 1] && !ID_RE.test(lines[i + 1])) nums = numsOf(lines[i + 1]);
      if (nums.length) { amount = Math.max(...nums); break; }
    }
    const m = ln.match(/^\s*[$€₺]?\s*(\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{2})?)\s*(USD|EUR|TRY|TL)\b/i);
    if (m && /\bdue\b/i.test(ln)) { const n = parseTrNumber(m[1]); if (n >= 1) { amount = n; break; } }
  }
  // 0b) Tek başına "tutar + para birimi" satırı (ör. "$120.00 USD") — belgedeki en büyüğü
  if (!amount) {
    const adaylar = [];
    for (const ln of lines) {
      const m = ln.match(/^\s*[$€₺]?\s*(\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{2})?)\s*(USD|EUR|TRY|TL)\s*$/i);
      if (m) { const n = parseTrNumber(m[1]); if (n >= 1) adaylar.push(n); }
    }
    if (adaylar.length) amount = Math.max(...adaylar);
  }
  // 1) Satır başında anahtar kelime; tutar aynı satırda yoksa (sütunlu fiş)
  //    bir sonraki satıra da bak
  for (let i = 0; i < lines.length && !amount; i++) {
    if (/^[\s*]*(GENEL\s*TOPLAM|TOPLAM|KRED[İI]|NAK[İI]T|TUTAR|TOTAL)/i.test(lines[i]) && !ARA_RE.test(lines[i])) {
      let nums = numsOf(lines[i]);
      if (!nums.length && lines[i + 1] && !KEY_RE.test(lines[i + 1]) && !ID_RE.test(lines[i + 1]) && !ARA_RE.test(lines[i + 1])) {
        nums = numsOf(lines[i + 1]);
      }
      if (nums.length) { amount = Math.max(...nums); break; }
    }
  }
  // 2) Anahtar kelime satır içinde (kimlik ve ara toplam satırları hariç)
  if (!amount) {
    for (const line of lines) {
      if (KEY_RE.test(line) && !ID_RE.test(line) && !ARA_RE.test(line)) {
        const nums = numsOf(line);
        if (nums.length) { amount = Math.max(...nums); break; }
      }
    }
  }
  // 3) Akaryakıt fişi: "19,64 LT X 101,83" → litre × birim fiyat (TOPLAM satırı okunamadıysa)
  if (!amount) {
    for (const line of lines) {
      const m = line.match(/(\d{1,4}[.,]\d{1,3})\s*L(?:T|İT|IT)?\.?\s*[X×*]\s*(\d{1,4}[.,]\d{2})/i);
      if (m) {
        const t = Math.round(parseFloat(m[1].replace(",", ".")) * parseFloat(m[2].replace(",", ".")) * 100) / 100;
        if (t >= 1 && t <= 999999) { amount = t; break; }
      }
    }
  }
  // 4) Son çare: kimlik/no satırları HARİÇ; YALNIZ ondalıklı (,00) ya da "*" ile
  //    başlayan sayılar. Kod parçaları (BAY/454-726/0, ADA NO: 5-28) tutar sayılmaz.
  //    Güvenilir sayı yoksa boş döner — yanlış tutar yazmaktansa elle girilsin
  //    (17.09.2026: 2.000 TL fişte 726 okunuyordu).
  if (!amount) {
    const aday = [];
    for (const line of lines) {
      if (ID_RE.test(line) || /EPDK|L[İI]SANS|ADA\s*NO|BAY\s*\/|KDV\s*%|%\s*\d/i.test(line)) continue;
      const re = new RegExp(TR_NUM_RE.source, "g");
      let m;
      while ((m = re.exec(line))) {
        const once = line[m.index - 1] || "", sonra = line[m.index + m[0].length] || "";
        if (/[\/\-\dA-Za-z]/.test(once) || /[\/\-A-Za-z]/.test(sonra)) continue;
        const n = parseTrNumber(m[0]);
        if (n < 1 || n > 999999) continue;
        if (/[.,]\d{2}$/.test(m[0]) || (/^\*/.test(m[0]) && n >= 100)) aday.push(n);
      }
    }
    if (aday.length) amount = Math.max(...aday);
  }
  // Türk plaka formatı: 2 rakam + 1-3 HARF (rakam değil) + 2-4 rakam
  // Örn: 16GB307, 34ABC1234, 06A1234
  const plateRe = /\b(\d{2})\s*([A-ZÇŞĞÜÖİ]{1,3})\s*(\d{2,4})\b/g;
  const rawPlates = [...text.matchAll(plateRe)]
    .map(m => (m[1] + m[2] + m[3]).toUpperCase().replace(/[^A-Z0-9]/g, ""))
    .filter(p => p.length >= 5 && p.length <= 8);
  // En uzun eşleşmeyi önce al (gerçek plakalar genelde daha uzun)
  rawPlates.sort((a, b) => b.length - a.length);
  return { amount: amount || null, plaka: rawPlates[0] || null, rawPlates, currency };
}

async function ocrFis(fileBuffer) {
  try {
    const apiKey = process.env.OCR_SPACE_KEY || "helloworld";
    const base64 = fileBuffer.toString("base64");
    const body = new URLSearchParams({
      base64Image: `data:image/jpeg;base64,${base64}`,
      language: "tur",
      isOverlayRequired: "false",
      detectOrientation: "true",
      scale: "true",
      OCREngine: "2",
    });
    const resp = await fetch("https://api.ocr.space/parse/image", {
      method: "POST",
      headers: { apikey: apiKey, "Content-Type": "application/x-www-form-urlencoded" },
      body: body.toString(),
    });
    const json = await resp.json();
    const text = json?.ParsedResults?.[0]?.ParsedText || "";
    console.log("[OCR.space] text snippet:", text.slice(0, 200));
    return parseOcrText(text);
  } catch (e) {
    console.error("[OCR error]", e.message);
    return { amount: null, plaka: null, rawPlates: [], currency: null };
  }
}

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: "Token yok" });
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    req.user = req._tazeOturum || decoded; // oturum tazeleme katmanı DB'den güncel rol/marka yazdı

    next();
  } catch {
    return res.status(401).json({ error: "Geçersiz token" });
  }
}

// Taşeron adını kanonik forma indirir: 'AHY ELEKTRİK' ve 'AHY' aynı firmadır
function canonSub(name) {
  const n = String(name || "").toLowerCase();
  if (n.includes("federal")) return "federal";
  if (n.includes("ubs")) return "ubs";
  if (n.includes("ahy")) return "ahy";
  // Teknocenter (13.10.2026): "TEKNOCENTER", "Tekno_FERRUMX" → tekno; "…TEKNOLOJİ…" eşleşmez
  if (/^tekno(center)?([_\s-]|$)/.test(n)) return "tekno";
  if (n.includes("2kx")) return "2kx";
  if (n.includes("ferrum")) return "ferrumx";
  return n.trim();
}

// ── ALT MARKA PROFİLLERİ (13.10.2026, Teknocenter devri) ─────────────────────
// Tenant içi alt markalar (hw_yukleme=false): AHY 15.07.2026–30.09.2026 arası
// çalıştı; TEKNO (Teknocenter) 01.10.2026'dan itibaren kadroyu, araçları ve
// depoları AHY'den devraldı (devralinan='AHY' → bordro kapsamı iki markayı kapsar).
// Kaynak markalar tablosudur (taseron_onek, devir_baslangic, devir_bitis,
// devralinan, kirilim_yuzde); açılışta ve her 5 dk'da yenilenir. Tablo
// okunamazsa buradaki varsayılanlar geçerlidir.
const ALT_MARKA_VARSAYILAN = [
  { kod: "AHY",   ad: "AHY Elektrik", onek: "AHY",   devir: "2026-07-15", bitis: "2026-09-30", pay: 0.90, devralinan: null },
  // 14.10.2026 anlaşması: AHY 30.09'a kadar; 01–13.10 arası Şimşek; TEKNO 14.10'dan itibaren (Orhan 15.10 kararı)
  { kod: "TEKNO", ad: "Teknocenter",  onek: "TEKNO", devir: "2026-10-14", bitis: null,         pay: 0.90, devralinan: "AHY" },
];
let ALT_MARKALAR = ALT_MARKA_VARSAYILAN.map((x) => ({ ...x }));
const _ertesiGun = (d) => { const t = new Date(d + "T00:00:00Z"); t.setUTCDate(t.getUTCDate() + 1); return t.toISOString().slice(0, 10); };
function altMarka(kod) {
  const k = String(kod || "").trim().toUpperCase();
  return ALT_MARKALAR.find((m) => m.kod === k) || null;
}
// Bir markanın tam profili: devir penceresi [devir, son) + bordro kapsamı (kendisi + devraldığı)
function markaProfil(kod) {
  const k = String(kod || "AHY").trim().toUpperCase();
  const m = altMarka(k) || { kod: k, ad: k, onek: k, devir: "2026-07-15", bitis: null, pay: 0.9, devralinan: null };
  const bordro = [m.kod];
  let d = m.devralinan, guard = 0;
  while (d && guard++ < 5) { if (!bordro.includes(d)) bordro.push(d); d = altMarka(d)?.devralinan || null; }
  return { ...m, son: m.bitis ? _ertesiGun(m.bitis) : "9999-12-31", devirAy: m.devir.slice(0, 7), devirGun: Number(m.devir.slice(8, 10)), bordro };
}
const altMarkaKodlari = () => ALT_MARKALAR.map((m) => m.kod);
const altMarkaMi = (kod) => !!altMarka(kod);
// SQL literal listesi: 'AHY','TEKNO' (kodlar koddan gelir, kullanıcı girdisi değildir)
const altMarkaInSql = () => ALT_MARKALAR.map((m) => `'${m.kod}'`).join(",");
// Markanın Şimşek'e kestiği fatura / yaptığı tahsilat kaydı: tedarikçi (firma) adının ilk kelimesi (22.10.2026, Orhan)
//   - taşeron öneki tek başına bir kelime (ör. "TEKNO CENTER …", "AHY-ELEKTRİK") ya da
//   - marka adının ilk kelimesiyle başlıyor (ör. "TEKNOCENTER …", "AHY ELEKTRİK …"); alt çizgili ekip kodu (AHY_VEDAT) hariç.
// Önekle başlayan başka bir firma ("TEKNOSA …") markanın kaydı sayılmaz. AHY için kural eskisiyle aynıdır (önek = ad kelimesi).
function markaTedarikciRe(P) {
  const kelime = (x) => String(x || "").trim().split(/\s+/)[0].toUpperCase().replace(/[^A-Z0-9ÇĞİÖŞÜ]/g, "");
  const onek = kelime(P.onek), ad = kelime(P.ad) || onek;
  return `^(${onek}([^A-Z0-9_ÇĞİÖŞÜ]|$)|${ad}([^_]|$))`;
}
// Ödeyen/firma boş eski kayıtlar için tarih kuralı: tarih hangi markanın devir
// penceresine düşüyorsa (bitiş varsa dahil) o marka; hiçbirine düşmüyorsa Şimşek
// (ör. 01–14.10.2026 arası AHY bitmiş, TEKNO başlamamış → SIMSEK).
const _pencereSql = (m, col) => m.bitis
  ? `${col} >= DATE '${m.devir}' AND ${col} <= DATE '${m.bitis}'`
  : `${col} >= DATE '${m.devir}'`;
function odeyenTarihSql(tarihCol) {
  const sirali = [...ALT_MARKALAR].sort((a, b) => b.devir.localeCompare(a.devir));
  return `CASE ${sirali.map((m) => `WHEN ${_pencereSql(m, tarihCol)} THEN '${m.kod}'`).join(" ")} ELSE 'SIMSEK' END`;
}
// Tarih herhangi bir alt markanın aktif penceresinde mi (Şimşek tarafı hariç tutmalarında)
const altMarkaAktifSql = (tarihCol) => "(" + ALT_MARKALAR.map((m) => `(${_pencereSql(m, tarihCol)})`).join(" OR ") + ")";
// Maaş avansı hangi markanın? (19.10.2026, Orhan): ödeme tarihi değil MAAŞ DÖNEMİ (avans.donem) belirler —
// Eylül dönemi avansı 17.10'da ödense de AHY'nin (AHY 30.09'da bitti, TEKNO 14.10'da başladı; Ekim dönemi TEKNO).
// Dönemin son günü hangi markanın penceresine düşüyorsa o marka. Hiçbir pencereye düşmüyorsa (ör. 2026-06,
// devir öncesi dönem) ya da dönem boşsa eski kural: ödeme tarihi penceresi → geçmiş kayıtlar değişmez.
const _donemSonSql = (donemCol) => `(to_date(${donemCol} || '-01','YYYY-MM-DD') + INTERVAL '1 month - 1 day')::date`;
function avansOdeyenSql(a = "a", tarihExpr = null) {
  const d = `NULLIF(${a}.donem,'')`;
  const ds = _donemSonSql(d);
  const t = tarihExpr || `${a}.tarih`;
  return `(CASE WHEN ${d} ~ '^\\d{4}-\\d{2}$' AND ${altMarkaAktifSql(ds)} THEN ${odeyenTarihSql(ds)} ELSE ${odeyenTarihSql(t)} END)`;
}
function odeyenVarsayilan(tarih) {
  const t = String(tarih || "").slice(0, 10);
  const sirali = [...ALT_MARKALAR].sort((a, b) => b.devir.localeCompare(a.devir));
  for (const m of sirali) if (t >= m.devir && (!m.bitis || t <= m.bitis)) return m.kod;
  return "SIMSEK";
}
const ilkDevirTarihi = () => [...ALT_MARKALAR].map((m) => m.devir).sort()[0] || "2026-07-15";
// Taşeron ekip adı alt marka önekli mi (AHY_FERRUMX, TEKNO_FERRUMX) → marka kodu
function altMarkaOnekiOf(name) {
  const n = String(name || "").trim().toUpperCase();
  for (const m of ALT_MARKALAR) if (n.startsWith(m.onek + "_")) return m.kod;
  return null;
}
// Taşeron adı (ekip ya da ünvan) hangi alt markaya ait → kod ya da null
function altMarkaOf(name) {
  const n = String(name || "").trim().toUpperCase();
  if (!n) return null;
  if (altMarka(n)) return n;
  const onek = altMarkaOnekiOf(n);
  if (onek) return onek;
  for (const m of ALT_MARKALAR) if (n.startsWith(m.onek) && !/^[A-Z]/.test(n.slice(m.onek.length))) return m.kod;
  return null;
}
// subcon_name alt marka sahası mı: (LIKE 'AHY%' OR LIKE 'TEKNO%')
const altOnekLikeSql = (col) => "(" + ALT_MARKALAR.map((m) => `UPPER(COALESCE(${col},'')) LIKE '${m.onek}%'`).join(" OR ") + ")";
// Altçizgili alt ekipler: (LIKE 'AHY\_%' OR LIKE 'TEKNO\_%')
const altOnekAltEkipLikeSql = (col) => "(" + ALT_MARKALAR.map((m) => `UPPER(TRIM(COALESCE(${col},''))) LIKE '${m.onek}\\_%'`).join(" OR ") + ")";
// Saha kaleminin alt marka payı (0.9 vb.; alt marka değilse 0)
const altOnekOranSql = (col) => `CASE ${ALT_MARKALAR.map((m) => `WHEN UPPER(COALESCE(${col},'')) LIKE '${m.onek}%' THEN ${m.pay}`).join(" ")} ELSE 0 END`;
// Taşeron adı (küçük harf) için pay oranı — Bölge Analizi / export ile aynı kural
function altMarkaPayOf(nameLower) {
  const c = canonSub(nameLower);
  const m = ALT_MARKALAR.find((x) => canonSub(x.kod) === c);
  return m ? m.pay : null;
}
// Bitmiş markanın (AHY) yerine geçen güncel marka: AHY → TEKNO (devralan)
// Tarih bir markanın penceresine düşmüyorsa (ör. 01–14.10.2026) null döner → çağıran Şimşek'e düşer
function guncelMarka(kod, tarih) {
  let k = String(kod || "").toUpperCase(), guard = 0;
  const t = String(tarih || new Date().toISOString()).slice(0, 10);
  while (guard++ < 5) {
    const m = altMarka(k);
    if (!m) return k;
    if (t < m.devir) return null;
    if (!m.bitis || t <= m.bitis) return k;
    const sonraki = ALT_MARKALAR.find((x) => x.devralinan === k);
    if (!sonraki) return null;
    k = sonraki.kod;
  }
  return k;
}
// Gelen firma etiketi: alt marka kodu ise o, değilse null
const altMarkaKoduNormalize = (v) => { const k = String(v || "").trim().toUpperCase(); return altMarka(k) ? k : null; };
// Yeni girişlerde (avans, masraf, personel ödemesi, nakit, yemek, taşeron ödemesi) bitmiş marka
// seçilirse (eski mobil sürümü hâlâ "AHY" gönderir) devralan güncel markaya (TEKNO) çevrilir;
// hiçbir marka aktif değilse null → çağıran Şimşek'e düşer. (14.10.2026, Orhan: "ya Şimşek ya TEKNO")
function aktifAltMarkaKodu(v, tarih) {
  const k = altMarkaKoduNormalize(v);
  if (!k) return null;
  const m = altMarka(k);
  const t = String(tarih || new Date().toISOString()).slice(0, 10);
  if (m.bitis && t > m.bitis) return guncelMarka(k, t);
  return k;
}

// Veri kapsamı: subcon rolü VEYA alt marka (hw_yukleme=false, ör. AHY yönetimi)
// VEYA yönetici olmayan taşeron-adlı kullanıcı (ör. 2KX Serdar gmail) yalnız
// kendi taşeron satırlarını görür. Dönen değer kapsam adı ya da null.
// Multer, dosya adını latin1 olarak çözer — Türkçe karakterli adlar
// "Ä°zmir SÃ¶zleÅŸme" gibi bozulur. UTF-8'e geri çevir (ASCII adlarda no-op).
function utf8Name(name) {
  const s = String(name || "");
  try {
    const fixed = Buffer.from(s, "latin1").toString("utf8");
    return fixed.includes("�") ? s : fixed;
  } catch { return s; }
}

function subconScope(req) {
  const role = String(req.user?.role || "").toLowerCase();
  let name = String(req.user?.subcon_name || "").trim();
  // 28.10.2026 (Orhan): alt marka yönetim hesabı (ör. TEKNO direktörü) firma adı boş açılırsa
  // kapsamsız kalıp tüm şirket verisini görüyordu — firma adı yoksa marka adına kilitlenir.
  if (!name && req.user?.hw_yukleme === false && role !== "platform_admin" && role !== "user" && altMarkaMi(req.user?.marka)) {
    name = markaProfil(req.user.marka).ad;
  }
  if (!name) return null;
  if (role === "subcon") return name;
  if (req.user?.hw_yukleme === false) return name; // alt marka tam paneli (info@ahyelektrik.com)
  if (!["admin", "platform_admin", "direktor", "muhasebe", "genel_mudur"].includes(role)) return name;
  return null;
}

// FERRUMX istisnası (07.08.2026): firma hem Şimşek'e direkt ("FERRUMX")
// hem AHY üzerinden ("AHY_FERRUMX") iş yapıyor. FERRUMX yöneticisi ikisini
// birlikte görür; AHY tarafı da AHY_FERRUMX'i görmeye devam eder (canon 'ahy').
function subconRowMatches(scopeName, rowSubcon) {
  const c = canonSub(scopeName);
  if (c === "ferrumx") return String(rowSubcon || "").toLowerCase().includes("ferrum");
  return canonSub(rowSubcon) === c;
}

function applySubconFilter(req, rows) {
  const scopeName = subconScope(req);
  if (!scopeName) return rows || [];
  return (rows || []).filter((row) => subconRowMatches(scopeName, row.subcon_name));
}

// Taşeron okuma kapsamı (21.10.2026, Orhan): taşeron / alt marka kullanıcısında sorgu
// parametresi (?taseron=, ?subcon=) yok sayılır, kapsam kendi adına kilitlenir — aksi halde
// parametreyi değiştiren taşeron başka taşeronun hakediş/mutabakat verisini görüyordu.
// Varsayılan-red kapısı req.user'ı doldurmadığı için token optionalAuth ile okunur.
// role=subcon olup subcon_name'i boş hesap "kapsamsız" sayılmaz, reddedilir.
// Dönüş: { kapsam: ad | null }  veya  { status, hata }
function taseronOkumaKapsami(req) {
  const u = optionalAuth(req);
  if (!u) return { status: 401, hata: "Oturum gerekli" };
  const kapsam = subconScope(req);
  if (kapsam) return { kapsam };
  if (taseronMu(u)) return { status: 403, hata: "Taşeron hesabına firma adı tanımlı değil" };
  return { kapsam: null };
}

const pool = require("./db");

// Alt marka profillerini markalar tablosundan yenile (açılış + 5 dk)
async function altMarkalariYenile() {
  try {
    // Tarihler metin olarak okunur — DATE → JS Date dönüşümü saat dilimiyle bir gün kayıyordu
    await pool.query(`ALTER TABLE markalar ADD COLUMN IF NOT EXISTS fon_modeli TEXT`).catch(() => {});
    const r = await pool.query(`SELECT kod, ad, kirilim_yuzde, taseron_onek,
        to_char(devir_baslangic,'YYYY-MM-DD') AS devir_baslangic,
        to_char(devir_bitis,'YYYY-MM-DD') AS devir_bitis, devralinan, fon_modeli
      FROM markalar WHERE aktif = true AND hw_yukleme = false ORDER BY id`);
    if (!r.rows.length) return;
    ALT_MARKALAR = r.rows.map((x) => {
      const v = ALT_MARKA_VARSAYILAN.find((d) => d.kod === x.kod) || {};
      return {
        kod: String(x.kod).toUpperCase(), ad: x.ad || x.kod,
        onek: String(x.taseron_onek || v.onek || x.kod).toUpperCase(),
        devir: x.devir_baslangic || v.devir || "2026-07-15",
        bitis: x.devir_bitis || v.bitis || null,
        pay: (100 - Number(x.kirilim_yuzde ?? 10)) / 100,
        devralinan: x.devralinan ? String(x.devralinan).toUpperCase() : (v.devralinan ?? null),
        // 19.10.2026 (Orhan): fon modeli — PROJE: projeye gelen para tek kasa, ödeme yöntemi ne olursa
        // olsun (nakit/banka/firma hesabı) tüm gerçek ödemeler bu kasadan düşer; yalnız açıkça
        // "fon dışı" işaretlenen ödeme hariç. FIRMA (AHY eski kurgu): kasadan_dus=false = firma kendi ödedi.
        fonModeli: String(x.fon_modeli || v.fonModeli || "FIRMA").toUpperCase() === "PROJE" ? "PROJE" : "FIRMA",
      };
    });
  } catch (e) { console.error("[alt marka] profil yenileme:", e.message); }
}
setInterval(altMarkalariYenile, 5 * 60 * 1000).unref();

// ── DEVİR KALEMİ GERİ ALMA KURALI (13.10.2026, Orhan) ─────────────────────────
// AHY'den Teknocenter'a devredilen kalemler (yedek_tekno_devir_20261013'te
// kaynak='master_works', eski_deger AHY/AHY_xxx olanlar) HW ödemesi geldiği anda
// eski taşeronuna (AHY dönemine) geri döner — para AHY dönemi işine aittir.
// Teknocenter'ın kendi yeni işleri bu tabloda olmadığı için hiç etkilenmez.
// HW Payment yüklemesinden sonra ve her açılışta çalışır; idempotenttir.
async function devirOdenenKalemleriGeriAl(kaynak = "açılış") {
  try {
    const r = await pool.query(`
      WITH py AS (
        SELECT regexp_replace(regexp_replace(TRIM(invoice_no),'-.*$',''),'^(SIM\\d{4})0+','\\1') n, MAX(payment_date) pd
        FROM hw_payment_rows GROUP BY 1),
      odenen AS (
        SELECT DISTINCT UPPER(TRIM(i.site_id)) sc, TRIM(COALESCE(i.item_code,'')) ic
        FROM hw_invoice_items i
        JOIN py ON py.n = regexp_replace(regexp_replace(TRIM(i.invoice_no),'-.*$',''),'^(SIM\\d{4})0+','\\1')
        WHERE TRIM(COALESCE(i.invoice_no,'')) <> '' AND py.pd IS NOT NULL)
      UPDATE master_works m SET subcon_name = y.eski_deger
      FROM yedek_tekno_devir_20261013 y, odenen o
      WHERE y.kaynak = 'master_works' AND y.id = m.id
        AND UPPER(COALESCE(y.eski_deger,'')) LIKE 'AHY%'
        AND UPPER(COALESCE(m.subcon_name,'')) LIKE 'TEKNO%'
        AND o.sc = UPPER(TRIM(m.site_code)) AND o.ic = TRIM(COALESCE(m.item_code,''))
      RETURNING m.site_code, m.item_code, m.subcon_name`);
    if (r.rowCount) console.log(`[devir geri alma · ${kaynak}] HW ödemesi gelen ${r.rowCount} kalem AHY dönemine döndü:`,
      r.rows.slice(0, 20).map((x) => `${x.site_code}/${x.item_code}→${x.subcon_name}`).join(", "));
    return r.rowCount;
  } catch (e) { console.error("[devir geri alma] hata:", e.message); return 0; }
}

