// GET /platform/overview — platform sahibi konsolu: tüm firmalar + bekleyen
// kayıt sayısı + kullanıcı sayıları. Yalnızca platform_admin erişebilir.
// İzole firmayı platformdan kaldır: registry kaydı silinir + allow-list'ten
// çıkarılır + kullanıcıları pasife alınır. ŞEMA/VERİ SİLİNMEZ (geri dönülebilir).
app.delete("/platform/firms/:tenant", authMiddleware, requirePlatformAdmin, async (req, res) => {
  try {
    const tenant = String(req.params.tenant || "").toLowerCase().trim();
    if (!tenant || tenant === "erc" || tenant === "2kx") {
      return res.status(400).json({ ok: false, error: "Yerleşik firmalar kaldırılamaz" });
    }
    const r = await pool.query("DELETE FROM tenant_registry WHERE tenant=$1 RETURNING tenant, name", [tenant]);
    if (!r.rows.length) return res.status(404).json({ ok: false, error: "Firma bulunamadı" });
    removeIsolatedTenant(tenant);
    const u = await pool.query("UPDATE users SET is_active=false WHERE tenant=$1", [tenant]);
    res.json({ ok: true, removed: r.rows[0], deactivated_users: u.rowCount });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

app.get("/platform/overview", authMiddleware, requirePlatformAdmin, async (req, res) => {
  try {
    // Kayıtlı izole firmalar
    let registry = [];
    try {
      const r = await pool.query(
        `SELECT tenant, name, owner_email, schema_name, isolated, created_at
         FROM tenant_registry ORDER BY created_at DESC`
      );
      registry = r.rows || [];
    } catch { registry = []; }

    // Tenant başına kullanıcı sayısı (users tablosu paylaşımlı/public)
    let counts = {};
    try {
      const c = await pool.query(
        `SELECT COALESCE(tenant,'erc') AS tenant, COUNT(*)::int AS n
         FROM users WHERE COALESCE(is_active,false)=true GROUP BY COALESCE(tenant,'erc')`
      );
      for (const row of c.rows) counts[row.tenant] = row.n;
    } catch { counts = {}; }

    // Bekleyen kayıt sayısı
    let pending = 0;
    try {
      const p = await pool.query(`SELECT COUNT(*)::int AS n FROM users WHERE status='pending'`);
      pending = p.rows[0]?.n || 0;
    } catch { pending = 0; }

    // ERC + legacy 2KX her zaman listede (built-in firmalar)
    const builtins = [
      { tenant: "erc", name: "ERC Mühendislik", owner_email: "duzgun.simsek@simsektel.com", isolated: false, builtin: true },
      { tenant: "2kx", name: "2KX (Şimşek taşeronu)", owner_email: "serdar.altinova@simsektel.com", isolated: false, builtin: true },
    ];
    const firms = [
      ...builtins.map(b => ({ ...b, users: counts[b.tenant] || 0 })),
      ...registry.map(r => ({
        tenant: r.tenant, name: r.name, owner_email: r.owner_email,
        isolated: r.isolated, schema_name: r.schema_name, created_at: r.created_at,
        builtin: false, users: counts[r.tenant] || 0,
      })),
    ];

    // Tüm kullanıcılar (kimler kullanıyor) — platform sahibi hepsini görür/yönetir.
    let users = [];
    try {
      const u = await pool.query(
        `SELECT id, name, email, role, is_active, status, COALESCE(tenant,'erc') AS tenant, created_at
         FROM users ORDER BY COALESCE(is_active,false) DESC, id DESC`
      );
      // Firma adını eşle
      const nameByTenant = {};
      for (const f of firms) nameByTenant[f.tenant] = f.name;
      users = (u.rows || []).map(r => ({ ...r, firm: nameByTenant[r.tenant] || r.tenant }));
    } catch (e) { users = []; }

    // ERC tenant'ı içindeki markalar (white-label: ERC Mühendislik / AHY Elektrik)
    // + marka başına aktif kullanıcı sayısı — konsolda alt satır olarak gösterilir.
    let markalar = [];
    try {
      const m = await pool.query(`
        SELECT m.kod, m.ad, m.kirilim_yuzde,
          (SELECT COUNT(*)::int FROM users x
            WHERE COALESCE(x.tenant,'erc')='erc' AND COALESCE(x.marka,'ERC')=m.kod
              AND COALESCE(x.is_active,false)=true) AS users
        FROM markalar m WHERE m.tenant='erc' AND m.aktif=true ORDER BY m.id`);
      markalar = m.rows || [];
    } catch { markalar = []; }

    // ERC'nin alt taşeronları (2KX, Federal, UBS...) — kullanıcı kayıtlarından
    // otomatik: subcon_name + payment_rate (0.75 = %75 pay). Elle liste tutulmaz.
    let taseronlar = [];
    try {
      const t = await pool.query(`
        SELECT TRIM(subcon_name) AS ad,
          ROUND(MAX(COALESCE(payment_rate,0.8))*100)::int AS pay_yuzde,
          COUNT(*)::int AS users
        FROM users
        WHERE COALESCE(TRIM(subcon_name),'')<>'' AND COALESCE(is_active,false)=true
        GROUP BY TRIM(subcon_name) ORDER BY 1`);
      taseronlar = t.rows || [];
    } catch { taseronlar = []; }

    res.json({ ok: true, firms, pending_count: pending, users, markalar, taseronlar });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

app.get("/rollout/mismatch-check", async (req, res) => {
  try {
    const masterResult = await pool.query(buildMasterJoinedQuery());
    const rolloutResult = await pool.query(`SELECT * FROM rollout_progress`);

    const rolloutSites = new Set(
      (rolloutResult.rows || []).map((r) =>
        String(r.site_code || "")
          .trim()
          .toUpperCase(),
      ),
    );

    const masterSitesMap = new Map();

    (masterResult.rows || []).forEach((row) => {
      const siteCode = String(row.site_code || "")
        .trim()
        .toUpperCase();
      const doneQty = Number(row.done_qty || 0);

      if (!siteCode || doneQty <= 0) return;

      if (!masterSitesMap.has(siteCode)) {
        masterSitesMap.set(siteCode, {
          site_code: row.site_code,
          project_code: row.project_code,
          site_type: row.site_type,
          subcon_name: row.subcon_name,
          done_qty: doneQty,
          onair_date: row.onair_date,
          status: row.status,
        });
      }
    });

    const masterSites = new Set(masterSitesMap.keys());

    const missingInRollout = [...masterSitesMap.values()].filter((row) => {
      const code = String(row.site_code || "")
        .trim()
        .toUpperCase();
      return !rolloutSites.has(code);
    });

    const rolloutWithoutWork = (rolloutResult.rows || []).filter((row) => {
      const code = String(row.site_code || "")
        .trim()
        .toUpperCase();
      return code && !masterSites.has(code);
    });

    res.json({
      ok: true,
      missingInRollout,
      rolloutWithoutWork,
      counts: {
        missingInRollout: missingInRollout.length,
        rolloutWithoutWork: rolloutWithoutWork.length,
      },
    });
  } catch (err) {
    console.error("AUTH LOGIN ERROR:", err.message);
    return res.status(500).json({
      ok: false,
      error: err.message,
    });
  }
});

// /create-admin kaldırıldı (20.10.2026): kimlik doğrulamasız, sabit şifreli admin ekliyordu.
// PO'su açık olup iş girişi yapılmamış kalemler — Günlük İş Girişi'ndeki
// "Eksik Kalem" kartını besler. Varsayılan olarak 01.07.2026 sonrası açılan
// PO'lara bakar; eski PO'lar için aksiyon alınmadığından kapsam dışıdır (15.08.2026).
app.get("/po/eksik-girisler", authMiddleware, async (req, res) => {
  try {
    const since = /^\d{4}-\d{2}-\d{2}$/.test(String(req.query.since || ""))
      ? String(req.query.since)
      : "2026-07-01";
    const r = await pool.query(
      `
      SELECT
        UPPER(TRIM(p.site_code))            AS site_code,
        TRIM(COALESCE(p.item_code, ''))     AS item_code,
        COALESCE(p.item_description, '')    AS item_description,
        COALESCE(p.po_no, '')               AS po_no,
        COALESCE(p.requested_qty, 0)        AS requested_qty,
        COALESCE(p.billed_qty, 0)           AS billed_qty,
        COALESCE(p.unit_price, 0)           AS unit_price,
        COALESCE(p.currency, 'TRY')         AS currency,
        to_char(p.acceptance_date, 'YYYY-MM-DD') AS acceptance_date,
        COALESCE(mw.site_type, '')          AS site_type,
        COALESCE(mw.project_code, p.project_code, '') AS project_code
      FROM po_rows p
      LEFT JOIN LATERAL (
        SELECT m.site_type, m.project_code FROM master_works m
        WHERE UPPER(TRIM(m.site_code)) = UPPER(TRIM(p.site_code))
        ORDER BY m.id DESC LIMIT 1
      ) mw ON true
      WHERE p.acceptance_date >= $1::date
        AND UPPER(COALESCE(p.po_status, 'OPEN')) = 'OPEN'
        AND COALESCE(p.requested_qty, 0) > 0
        AND NOT EXISTS (
          SELECT 1 FROM master_works m
          WHERE UPPER(TRIM(m.site_code)) = UPPER(TRIM(p.site_code))
            AND TRIM(COALESCE(m.item_code, '')) = TRIM(COALESCE(p.item_code, ''))
            AND COALESCE(m.done_qty, 0) > 0
        )
      ORDER BY 1, 2
      `,
      [since],
    );

    // Saha bazında grupla — kart listesi saha kırılımıyla gösterilir
    const bySite = new Map();
    let toplamTutar = 0, faturaliKalem = 0;
    for (const row of r.rows) {
      const tutar = Number(row.requested_qty || 0) * Number(row.unit_price || 0);
      toplamTutar += tutar;
      if (Number(row.billed_qty || 0) > 0) faturaliKalem++;
      if (!bySite.has(row.site_code)) {
        bySite.set(row.site_code, {
          site_code: row.site_code, site_type: row.site_type,
          project_code: row.project_code, tutar: 0, items: [],
        });
      }
      const g = bySite.get(row.site_code);
      g.tutar += tutar;
      g.items.push({ ...row, tutar });
    }
    const sites = Array.from(bySite.values()).sort((a, b) => b.tutar - a.tutar);

    res.json({
      ok: true, since,
      toplam_kalem: r.rows.length,
      toplam_saha: sites.length,
      toplam_tutar: Math.round(toplamTutar),
      faturali_kalem: faturaliKalem,
      sites,
    });
  } catch (e) {
    console.error("PO EKSIK GIRISLER ERROR:", e.message);
    res.status(500).json({ ok: false, error: e.message });
  }
});

/* ═══ SÜRÜMLÜ BoQ + MALZEME GELİŞ TARİHİ + TSSR AI KONTROLÜ (27.10.2026, Orhan — Teknocenter) ═══════════════════
   Tablolar boqKatalog.tabloHazirla ile açılışta hazırlanır (boq_katalog, boq_secim_log, master_works.boq_* anlık görüntü
   kolonları, rollout_progress.malzeme_gelis_tarihi / enh_malzeme_gelis_tarihi). Katalog içe alma yalnız admin; önizleme
   zorunlu (onizleme_anahtari). PR uçları (/master/add, PUT /master/:id, /master/saha-kalemler/kaydet) boq_surum geldiğinde
   kalemi o sürümde doğrular ve fiyat/açıklama/birim anlık görüntüsünü satıra yazar; tarihe aykırı seçimde gerekçe ister
   ve boq_secim_log'a (seçim, gerekçe, kullanıcı, zaman) yazar. boq_surum gelmeyen eski istemciler eskisi gibi çalışır. */
(async () => {
  // master_works / rollout_progress ana migrasyonda açılır — hazır olana kadar bekle (en çok ~2 dk), sonra kolonları ekle
  for (let deneme = 0; deneme < 60; deneme++) {
    try {
      const r = await pool.query(`SELECT to_regclass('public.master_works') AS a, to_regclass('public.rollout_progress') AS b`);
      if (r.rows[0]?.a && r.rows[0]?.b) break;
    } catch {}
    await new Promise((res) => setTimeout(res, 2000));
  }
  try { await boqKatalog.tabloHazirla(pool); await tssrOkuma.tabloHazirla(pool); await sahaKonum.tabloHazirla(pool);
    await pool.query(`CREATE TABLE IF NOT EXISTS pr_kontrol_karar (id SERIAL PRIMARY KEY, site_code TEXT, anahtar TEXT, karar TEXT, gerekce TEXT, kullanici TEXT, zaman TIMESTAMPTZ DEFAULT NOW())`);
    console.log("✅ BoQ katalog / TSSR analiz tabloları hazır");
  } catch (e) { console.error("BoQ katalog tablo hatası:", e.message); }
})();
const BOQ_ICE_ALMA_ROLLER = ["admin", "platform_admin"];
// Alt marka (Teknocenter) için saha kapsam kontrolü: MARKA ROLLOUT KAPSAMI katmanıyla aynı kural; ERC/Şimşek hesapları etkilenmez
async function sahaKapsamKontrol(req, site) {
  const K = await rolloutKapsam(req);
  if (!K) return { ok: true, K: null };
  if (!K.goruntule) return { ok: false, http: 403, error: "Rollout görüntüleme yetkiniz yok" };
  const sahalar = await markaRolloutSahalar(K);
  if (!sahalar.has(site)) return { ok: false, http: 403, error: "Bu saha firma kapsamınızda değil" };
  return { ok: true, K };
}
// PR satırı için BoQ seçimi: sürüm doğrulama + anlık görüntü + aykırı seçimde gerekçe zorunluluğu
async function boqSecimHazirla(req, { surum, kod, site, gerekce, kapsam, surumDegisimOnayi }) {
  if (!surum) return { ok: true, snapshot: null, log: null };
  const S = boqKatalog.surumBul(surum);
  if (!S) return { ok: false, http: 400, hata: `Geçersiz BoQ sürümü: ${surum}` };
  const bolge = getRegionFromSiteCode(site);
  const snap = await boqKatalog.prSnapshot(pool, { surum: S.kod, kod, bolge, kapsam });
  if (!snap.ok) return { ok: false, http: 400, hata: snap.hata };
  const oneri = await boqKatalog.surumOner(pool, site);
  const aykiri = !!(oneri.onerilen && oneri.onerilen !== S.kod);
  const kullanici = String(req.user?.email || optionalAuth(req)?.email || "").toLowerCase();
  if (aykiri && !String(gerekce || "").trim()) {
    return { ok: false, http: 400, hata: `Malzeme geliş tarihine göre önerilen sürüm ${boqKatalog.surumBul(oneri.onerilen).kisa}; ${S.kisa} seçimi için gerekçe zorunlu.`, oneri };
  }
  if (aykiri && !BOQ_ICE_ALMA_ROLLER.concat(["direktor", "genel_mudur", "rollout_mudur", "pm", "bolge_mudur", "muhasebe"]).includes(String(req.user?.role || "").toLowerCase()))
    return { ok: false, http: 403, hata: "Tarihe aykırı BoQ sürümü seçme yetkiniz yok — yönetici seçebilir." };
  const snapshot = snap.snapshot ? { ...snap.snapshot, boq_secim_gerekce: String(gerekce || "").trim() || null, boq_secim_kullanici: kullanici || null, boq_secim_zaman: new Date() }
    : { boq_surum: S.kod, boq_bolge: null, boq_birim: null, boq_para_birimi: null, boq_birim_fiyat: null, boq_aciklama: null, boq_secim_gerekce: String(gerekce || "").trim() || null, boq_secim_kullanici: kullanici || null, boq_secim_zaman: new Date() };
  return { ok: true, snapshot, uyari: snap.uyari || (snap.fiyat_yok ? `${kod} için ${S.kisa} kataloğunda fiyat yazmıyor` : ""), aykiri, oneri,
    log: async (masterId) => { try { await pool.query(`INSERT INTO boq_secim_log (site_code, item_code, master_id, surum, onerilen_surum, oneri_gerekce, aykiri, gerekce, kullanici) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
      [site, kod, masterId || null, S.kod, oneri.onerilen, oneri.gerekce, aykiri, String(gerekce || "").trim() || null, kullanici || null]); } catch (e) { console.error("boq_secim_log:", e.message); } } };
}
const BOQ_SNAP_KOLON = ["boq_surum", "boq_bolge", "boq_birim", "boq_para_birimi", "boq_birim_fiyat", "boq_aciklama", "boq_secim_gerekce", "boq_secim_kullanici", "boq_secim_zaman"];
const boqSnapDegerler = (snap) => BOQ_SNAP_KOLON.map((k) => (snap ? snap[k] ?? null : null));

