/* ================== FIX SITE TYPES ================== */
// Web her açılışta çağırıyor (App.jsx loadData) — 20.10.2026'dan beri kimlik kapısının arkasında.
app.get("/rollout/fix-site-types", async (req, res) => {
  try {
    // Tüm "DİĞER" veya boş site_type kayıtlarını site_code'dan yeniden türet
    const rows = await pool.query(
      `SELECT id, site_code FROM rollout_progress WHERE UPPER(COALESCE(site_type,'')) IN ('DİĞER','DIGER','OTHER','')`
    );
    let fixed = 0, skipped = 0;
    for (const row of rows.rows) {
      const code = String(row.site_code || "").toUpperCase().trim();
      let newType = "";
      if (code.includes("_DSS_") || code.includes("_GPS_")) newType = "DSS";
      else if (code.includes("_L1800_") || code.includes("_L2600_") || code.includes("_L800_") ||
               code.includes("_LC1800_") || code.includes("_L2100_") || code.includes("_L900_") ||
               code.includes("_LTE_") || code.includes("_W2100_") || code.includes("_W900_") ||
               code.includes("_W1900_")) newType = "LTE";
      else if (code.includes("_NR3500_") || code.includes("_NR700_") || code.includes("_TRP_") ||
               code.includes("5GEXP") || code.includes("5GREADINESS")) newType = "5G";
      else if (code.includes("_NS_")) newType = "STANDALONE";

      if (newType) {
        await pool.query("UPDATE rollout_progress SET site_type=$1 WHERE id=$2", [newType, row.id]);
        fixed++;
      } else {
        skipped++;
      }
    }
    // 27.10.2026 (Orhan): bölge / il boş kayıtlar Site ID önekinden doldurulur (BI → Bartın, DU → Düzce …); dolu değer ezilmez
    let bolgeDuzeltilen = 0, ilDuzeltilen = 0;
    const bos = await pool.query(`SELECT id, site_code, bolge, il FROM rollout_progress WHERE COALESCE(TRIM(bolge),'') = '' OR COALESCE(TRIM(il),'') = ''`);
    for (const row of bos.rows) {
      const b = getRegionFromSiteCode(row.site_code), c = getCityFromSiteCode(row.site_code);
      if (b && !String(row.bolge || "").trim()) { await pool.query("UPDATE rollout_progress SET bolge=$1 WHERE id=$2 AND COALESCE(TRIM(bolge),'') = ''", [b, row.id]); bolgeDuzeltilen++; }
      if (c && !String(row.il || "").trim()) { await pool.query("UPDATE rollout_progress SET il=$1 WHERE id=$2 AND COALESCE(TRIM(il),'') = ''", [c, row.id]); ilDuzeltilen++; }
    }
    res.json({ ok: true, fixed, skipped, total: rows.rows.length, bolge_duzeltilen: bolgeDuzeltilen, il_duzeltilen: ilDuzeltilen });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

