/* ================== NAKİT AKIŞI MANUEL ÖDEMELER ==================
   Araç kirası / ticket-yemek / diğer ödemeler ödendikçe buradan girilir.
   Maaş ödemeleri İK'daki maas_odeme tablosundan otomatik gelir. */
async function ensureCashflowOdemeTable() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS cashflow_odeme (
      id SERIAL PRIMARY KEY,
      kategori TEXT NOT NULL,
      tarih DATE NOT NULL,
      tutar NUMERIC NOT NULL,
      donem TEXT,
      aciklama TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )`);
  // Firma ayrımı (16.07.2026): ERC (Şimşek) girişlerini AHY görmez. Eski
  // kayıtların tümü (bugünküler dahil) ERC sayılır.
  await pool.query(`ALTER TABLE cashflow_odeme ADD COLUMN IF NOT EXISTS marka TEXT DEFAULT 'ERC'`);
  // 16.10.2026 (Orhan): araç kirası / depozito manuel girişleri araç kimliğine bağlanır (plaka zorunlu)
  await pool.query(`ALTER TABLE cashflow_odeme ADD COLUMN IF NOT EXISTS arac_id INTEGER`).catch(() => {});
}

app.get("/finance/cashflow-odeme", requireFinanceAuth, async (req, res) => {
  try {
    await ensureCashflowOdemeTable();
    const { yil, ay } = req.query;
    if (!yil || !ay) return res.status(400).json({ ok: false, error: "yil ve ay gerekli" });
    // ERC Nakit Akışı YALNIZ ERC'yi gösterir: AHY işaretli manuel girişler
    // AHY panelinde; AHY personelinin devir (15.07.2026) sonrası maaş/avans
    // ödemeleri de AHY sorumluluğundadır, buraya yansımaz.
    const r = await pool.query(
      `SELECT c.id, c.kategori, TO_CHAR(c.tarih,'YYYY-MM-DD') AS tarih, c.tutar, c.donem, c.aciklama,
              UPPER(COALESCE(c.marka,'ERC')) AS marka, c.arac_id, ar.plaka
       FROM cashflow_odeme c LEFT JOIN araclar ar ON ar.id = c.arac_id
       WHERE EXTRACT(YEAR FROM c.tarih)=$1 AND EXTRACT(MONTH FROM c.tarih)=$2
         AND UPPER(COALESCE(c.marka,'ERC'))='ERC'
       ORDER BY c.tarih, c.id`, [yil, ay]);
    // Maaş ödemeleri: İK'daki maas_odeme kayıtları (bu ay yapılan ödemeler)
    const m = await pool.query(
      `SELECT m.id, TO_CHAR(m.tarih,'YYYY-MM-DD') AS tarih,
              (COALESCE(m.bankadan,0)+COALESCE(m.elden,0)) AS tutar,
              m.donem, p.ad_soyad
       FROM maas_odeme m JOIN personel p ON p.id = m.personel_id
       WHERE EXTRACT(YEAR FROM m.tarih)=$1 AND EXTRACT(MONTH FROM m.tarih)=$2
         AND COALESCE(NULLIF(m.odeyen,''),
           CASE WHEN UPPER(COALESCE(p.marka,'ERC')) NOT IN (${altMarkaInSql()})
                THEN 'SIMSEK' ELSE ${odeyenTarihSql("m.tarih")} END) = 'SIMSEK'`,
      [yil, ay]).catch(() => ({ rows: [] }));
    // Maaş avansları: avans tablosu (turu MAAS) — nakit çıkışı ÖDENDİĞİ GÜN
    // gerçekleşir (dönem hangi ayın maaşı olursa olsun), maaş satırına eklenir
    const mav = await pool.query(
      `SELECT ('MA' || a.id) AS id, TO_CHAR(a.tarih,'YYYY-MM-DD') AS tarih,
              a.tutar, COALESCE(a.donem, TO_CHAR(a.tarih,'YYYY-MM')) AS donem,
              (p.ad_soyad || ' · maaş avansı') AS ad_soyad
       FROM avans a JOIN personel p ON p.id = a.personel_id
       WHERE UPPER(COALESCE(a.avans_turu,'MAAS'))='MAAS'
         AND EXTRACT(YEAR FROM a.tarih)=$1 AND EXTRACT(MONTH FROM a.tarih)=$2
         AND (UPPER(COALESCE(p.marka,'ERC')) NOT IN (${altMarkaInSql()}) OR ${avansOdeyenSql("a")} = 'SIMSEK')`,
      [yil, ay]).catch(() => ({ rows: [] }));
    // İş avansları: PD (Direktör) onayından geçenler — otomatik gider
    // Tarih: ödeme tarihi varsa o, yoksa direktör onay tarihi
    const av = await pool.query(
      `SELECT t.id,
              TO_CHAR(COALESCE(t.odeme_tarihi, t.direktor_onay_tarihi),'YYYY-MM-DD') AS tarih,
              t.tutar, t.talep_eden_ad, t.gider_turu, t.aciklama, t.durum,
              ${pmAvansSahibiSql("t", "p")} AS pm_kisisel
       FROM is_avans_talep t LEFT JOIN personel p ON p.id = t.personel_id
       WHERE t.durum IN ('DIREKTOR_ONAY','TAMAMLANDI')
         AND UPPER(COALESCE(t.firma,'ERC')) = 'ERC'
         AND COALESCE(t.odeme_tarihi, t.direktor_onay_tarihi) IS NOT NULL
         AND EXTRACT(YEAR FROM COALESCE(t.odeme_tarihi, t.direktor_onay_tarihi))=$1
         AND EXTRACT(MONTH FROM COALESCE(t.odeme_tarihi, t.direktor_onay_tarihi))=$2`,
      [yil, ay]).catch(() => ({ rows: [] }));
    // Orhan'ın avansı: tutar giderde kalır, kimlik yalnız yetkililere (Nurcan/Serdar finans görür ama bunu görmez)
    const _pmGorF = pmKisiselEmailGorur(req.financeUser?.email, req.financeUser?.role);
    const avRows = av.rows.map(({ pm_kisisel, ...x }) =>
      pm_kisisel && !_pmGorF ? { ...x, talep_eden_ad: "Yönetim (gizli)", aciklama: "", gider_turu: x.gider_turu } : x);
    res.json({ ok: true, odemeler: r.rows, maaslar: [...m.rows, ...mav.rows], avanslar: avRows });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// Manuel (gerçekleşen) ödeme kaydı — Şimşek Nakit Akışı "Ödeme Ekle" ve marka paneli "Ödeme Ekle" aynı kuralı kullanır
// (26.10.2026, Orhan). Dönüş: { http, json }. aracKapsam verilirse seçilen araç o kapsamda olmalı.
async function cashflowOdemeKaydet(body, markaVal, aracKapsam) {
  await ensureCashflowOdemeTable();
  const { kategori, tarih, tutar, donem, aciklama, arac_id, zorla } = body || {};
  if (!kategori || !tarih || !tutar)
    return { http: 400, json: { ok: false, error: "kategori, tarih, tutar zorunlu" } };
  const tutarN = parseFinanceNumber(tutar);
    // 16.10.2026: araç kirası / depozito → araç seçimi zorunlu; aynı ödeme Kira Öde'den de girilmişse iki kez sayılmasın
    let aracId = null, acik = aciklama || null;
    if (["ARAC", "ARAC_DEPOZITO"].includes(String(kategori).toUpperCase())) {
      const ar = arac_id ? await pool.query(`SELECT id, plaka, firma, depozito_tutar, to_char(depozito_tarihi,'YYYY-MM-DD') AS depozito_tarihi FROM araclar WHERE id=$1`, [arac_id]) : { rows: [] };
      if (!ar.rows[0]) return { http: 400, json: { ok: false, error: "Araç kirası / depozito girişinde araç (plaka) seçimi zorunlu" } };
      if (aracKapsam && !aracKapsamda(aracKapsam, ar.rows[0].firma)) return { http: 403, json: { ok: false, error: "Bu araç firmanızın kapsamında değil" } };
      aracId = ar.rows[0].id;
      if (!zorla) {
        if (String(kategori).toUpperCase() === "ARAC" && donem) {
          const k = await pool.query(`SELECT id, tutar, to_char(tarih,'YYYY-MM-DD') AS tarih FROM arac_kira_odemeler WHERE arac_id=$1 AND donem=$2`, [aracId, donem]);
          if (k.rows[0]) return { http: 409, json: { ok: false, cakisma: true, error: `${ar.rows[0].plaka} · ${donem} kirası "Kira Öde" ile zaten kayıtlı (₺${Number(k.rows[0].tutar).toLocaleString("tr-TR")}, ${k.rows[0].tarih}). Aynı ödeme ise tekrar girmeyin; farklı bir ödemeyse onaylayarak kaydedin.` } };
        }
        if (String(kategori).toUpperCase() === "ARAC_DEPOZITO" && Number(ar.rows[0].depozito_tutar || 0) > 0) {
          return { http: 409, json: { ok: false, cakisma: true, error: `${ar.rows[0].plaka} için araç kartında ₺${Number(ar.rows[0].depozito_tutar).toLocaleString("tr-TR")} depozito (${ar.rows[0].depozito_tarihi || "tarihsiz"}) zaten kayıtlı ve nakit akışına düşüyor. Aynı depozitoysa tekrar girmeyin; farklıysa onaylayarak kaydedin.` } };
        }
      }
    }
    const r = await pool.query(
      `INSERT INTO cashflow_odeme (kategori,tarih,tutar,donem,aciklama,marka,arac_id)
       VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING *`,
      [kategori, tarih, tutarN, donem || null, acik, markaVal, aracId]);
  return { http: 200, json: { ok: true, row: r.rows[0] } };
}
app.post("/finance/cashflow-odeme", requireFinanceAuth, async (req, res) => {
  try {
    const sonuc = await cashflowOdemeKaydet(req.body, aktifAltMarkaKodu(req.body?.marka, req.body?.tarih) || "ERC", null);
    res.status(sonuc.http).json(sonuc.json);
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// ═══ MARKA PANELİ — MANUEL ÖDEME (26.10.2026, Orhan) ════════════════════════════════════════════
// Alt marka (ör. Teknocenter) kendi Nakit Akışı panelinden Şimşek'teki "Ödeme Ekle" ile aynı kurala göre gerçekleşen
// ödeme (araç kirası, depozito, ticket, diğer) girer. Marka, MARKA PANELİ FİRMA KAPSAMI katmanında oturumdan zorlanır;
// kayıt cashflow_odeme'ye marka etiketiyle yazılır → marka nakit akışı ve proje kasası (çıkış) aynı kaynaktan görür.
// Şimşek (ERC) girişleri bu uçlardan görülmez/eklenmez/silinmez. Başka modüllerin otomatik yazdığı satırlar
// (çek/senet, yemek kartı hareketi) buradan silinemez.
const MARKA_ODEME_KATEGORI = ["ARAC", "ARAC_DEPOZITO", "TICKET", "DIGER"];
const markaOdemeBagliSql = `(EXISTS (SELECT 1 FROM cek_senet cs WHERE cs.cashflow_id = c.id)
  OR EXISTS (SELECT 1 FROM yemek_odeme_hareket yh WHERE yh.cashflow_id = c.id))`;
// Panelin markası olduğu gibi kullanılır (devir eşlemesi YOK: devredilmiş AHY paneli TEKNO kayıtlarını görmez/yazmaz)
function markaOdemeMarkasi(req) {
  return altMarkaKoduNormalize(req.body?.marka ?? req.query?.marka);
}
// Araç seçimi markanın bordro kümesiyle sınırlı (alt marka oturumu da Şimşek yöneticisi de aynı listeyi görür)
const markaOdemeAracKapsam = (req, marka) => altMarkaKapsam(req) || { bordro: markaProfil(marka).bordro };
app.get("/finance/marka-odeme", authMiddleware, async (req, res) => {
  try {
    if (!MARKA_KASA_ROLLER.includes(String(req.user?.role || "").toLowerCase())) return res.status(403).json({ ok: false, error: "Yetkiniz yok" });
    await ensureCashflowOdemeTable();
    const marka = markaOdemeMarkasi(req);
    if (!marka) return res.status(400).json({ ok: false, error: "Geçerli bir alt marka belirtilmeli" });
    const yil = Number(req.query.yil), ay = Number(req.query.ay);
    if (!yil || !ay) return res.status(400).json({ ok: false, error: "yil ve ay gerekli" });
    const r = await pool.query(
      `SELECT c.id, c.kategori, TO_CHAR(c.tarih,'YYYY-MM-DD') AS tarih, c.tutar, c.donem, c.aciklama, c.arac_id, ar.plaka,
              NOT ${markaOdemeBagliSql} AS silinebilir
         FROM cashflow_odeme c LEFT JOIN araclar ar ON ar.id = c.arac_id
        WHERE UPPER(COALESCE(c.marka,'ERC')) = $1 AND UPPER(c.kategori) = ANY($2::text[])
          AND EXTRACT(YEAR FROM c.tarih) = $3 AND EXTRACT(MONTH FROM c.tarih) = $4
        ORDER BY c.tarih, c.id`, [marka, MARKA_ODEME_KATEGORI, yil, ay]);
    const kap = markaOdemeAracKapsam(req, marka);
    const ar = await pool.query(`SELECT id, plaka, marka, model, surucu, durum, aylik_kira, firma FROM araclar ORDER BY plaka`).catch(() => ({ rows: [] }));
    const araclar = ar.rows.filter((a) => aracKapsamda(kap, a.firma)).map(({ firma, ...a }) => a)
      .sort((x, y) => (x.durum === "AKTİF" ? 0 : 1) - (y.durum === "AKTİF" ? 0 : 1) || String(x.plaka).localeCompare(String(y.plaka)));
    res.json({ ok: true, marka, odemeler: r.rows, araclar });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post("/finance/marka-odeme", authMiddleware, async (req, res) => {
  try {
    if (!MARKA_KASA_ROLLER.includes(String(req.user?.role || "").toLowerCase())) return res.status(403).json({ ok: false, error: "Yetkiniz yok" });
    const marka = markaOdemeMarkasi(req);
    if (!marka) return res.status(400).json({ ok: false, error: "Geçerli bir alt marka belirtilmeli (Şimşek ödemeleri Nakit Akışı panelinden girilir)" });
    if (req.body?.tarih && aktifAltMarkaKodu(marka, req.body.tarih) !== marka)
      return res.status(400).json({ ok: false, error: `${marka} bu tarihte aktif değil — ödeme devralan firmanın panelinden girilmeli` });
    if (!MARKA_ODEME_KATEGORI.includes(String(req.body?.kategori || "").toUpperCase()))
      return res.status(400).json({ ok: false, error: "Kategori araç kirası, araç depozitosu, ticket ya da diğer olmalı" });
    if (!(parseFinanceNumber(req.body?.tutar) > 0)) return res.status(400).json({ ok: false, error: "Tutar sıfırdan büyük olmalı" });
    // 27.10.2026: tekrarlanan kaydetme (çift tıklama / yeniden deneme / iki ekrandan aynı anda) — aynı firma, kategori, tarih,
    // tutar, dönem ve açıklamalı kayıt son 10 dakikada girildiyse çakışma; gerçekten ayrı bir ödemeyse onaylı (zorla) kaydedilir
    if (!req.body?.zorla) {
      const t = parseFinanceNumber(req.body.tutar);
      const ayni = await pool.query(`SELECT id FROM cashflow_odeme WHERE UPPER(COALESCE(marka,'ERC')) = $1 AND UPPER(kategori) = $2 AND tarih = $3::date
          AND ROUND(tutar::numeric, 2) = ROUND($4::numeric, 2) AND COALESCE(donem,'') = COALESCE($5,'') AND COALESCE(TRIM(aciklama),'') = COALESCE(TRIM($6),'')
          AND created_at > NOW() - INTERVAL '10 minutes' LIMIT 1`,
        [marka, String(req.body.kategori).toUpperCase(), req.body.tarih, t, req.body.donem || null, req.body.aciklama || null]).catch(() => ({ rows: [] }));
      if (ayni.rows[0]) return res.status(409).json({ ok: false, cakisma: true, error: `Aynı ödeme birkaç dakika önce kaydedildi (#${ayni.rows[0].id}). Tekrar girmeyin; farklı bir ödemeyse onaylayarak kaydedin.` });
    }
    const sonuc = await cashflowOdemeKaydet({ ...req.body, kategori: String(req.body.kategori).toUpperCase() }, marka, markaOdemeAracKapsam(req, marka));
    res.status(sonuc.http).json(sonuc.json);
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.delete("/finance/marka-odeme/:id", authMiddleware, async (req, res) => {
  try {
    if (!MARKA_KASA_ROLLER.includes(String(req.user?.role || "").toLowerCase())) return res.status(403).json({ ok: false, error: "Yetkiniz yok" });
    const k = await pool.query(
      `SELECT c.id, UPPER(COALESCE(c.marka,'ERC')) AS marka, UPPER(c.kategori) AS kategori, ${markaOdemeBagliSql} AS bagli
         FROM cashflow_odeme c WHERE c.id = $1`, [req.params.id]);
    const o = k.rows[0];
    if (!o || o.marka === "ERC" || !altMarkaMi(o.marka)) return res.status(404).json({ ok: false, error: "Kayıt bulunamadı" });
    if (!MARKA_ODEME_KATEGORI.includes(o.kategori) || o.bagli)
      return res.status(400).json({ ok: false, error: "Bu ödeme başka bir modülden otomatik oluştu — buradan silinemez" });
    await pool.query(`DELETE FROM cashflow_odeme WHERE id = $1`, [o.id]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

app.delete("/finance/cashflow-odeme/:id", requireFinanceAuth, async (req, res) => {
  try {
    // Çek/senet ödemeleri otomatik kayıttır — buradan silinemez; Çek & Senet
    // panelinden "Geri Al" ile kaldırılır (aynı anda belge de BEKLIYOR'a döner).
    const k = await pool.query(`SELECT kategori FROM cashflow_odeme WHERE id=$1`, [req.params.id]);
    if (k.rows[0]?.kategori === "CEKSENET")
      return res.status(400).json({ ok: false, error: "Çek/Senet ödemesi buradan silinemez — Çek & Senet panelinden Geri Al kullanın" });
    await pool.query(`DELETE FROM cashflow_odeme WHERE id=$1`, [req.params.id]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

/* ================== FINANCE CASHFLOW MONTHLY ================== */
app.get("/finance/cashflow-monthly", requireFinanceAuth, async (req, res) => {
  try {
    const { yil, ay } = req.query;
    if (!yil || !ay) return res.status(400).json({ ok: false, error: "yil ve ay gerekli" });

    const monthStr = `${yil}-${String(ay).padStart(2,"0")}`;

    // USD kayıtları TL'ye çevir (TCMB satış kuru) — Gelecek Ödemeler paneli ile tutarlı
    let usdRate = 0;
    try { usdRate = Number(await getTcmbUsdTrySellingRate()) || 0; } catch { usdRate = 0; }
    const AMT = (col, idx = 2) =>
      `CASE WHEN UPPER(COALESCE(currency,'TRY'))='USD' THEN COALESCE(${col},0) * $${idx} ELSE COALESCE(${col},0) END`;

    // 25.08.2026 (Orhan): 15.07 (T0) sonrası tahsilatlarda AHY sahalarına ait
    // pay (AHY etiketli kalem tutarı × %90) Şimşek kasasına yazılmaz — o para
    // AHY panelinde takip edilir. Fatura bazında AHY oranı kalemlerden bulunur,
    // ödeme/vade tutarı (1 − oran) ile çarpılır. T0 öncesi kayıtlar aynen kalır.
    // 25.08.2026 akşam: kalem başına correlated subquery havuzu kilitliyordu
    // (100+ sn, "timeout exceeded when trying to connect") — DISTINCT ON +
    // hash join sürümü ~80 ms, sonuç birebir aynı.
    const AHY_ORAN_CTE = `
      ahy_mw AS (
        SELECT DISTINCT ON (UPPER(TRIM(site_code)), TRIM(COALESCE(item_code,'')))
               UPPER(TRIM(site_code)) sc, TRIM(COALESCE(item_code,'')) ic,
               (${altOnekOranSql("subcon_name")}) AS alt_oran
        FROM master_works
        ORDER BY UPPER(TRIM(site_code)), TRIM(COALESCE(item_code,'')), done_qty DESC NULLS LAST
      ),
      ahyor AS (
        SELECT regexp_replace(regexp_replace(TRIM(i.invoice_no),'-.*$',''),'^(SIM\\d{4})0+','\\1') n,
               CASE WHEN SUM(COALESCE(i.invoiced_amount_excl,0)) > 0
                 THEN SUM(COALESCE(m.alt_oran,0) * COALESCE(i.invoiced_amount_excl,0))
                      / SUM(COALESCE(i.invoiced_amount_excl,0))
                 ELSE 0 END AS oran
        FROM hw_invoice_items i
        LEFT JOIN ahy_mw m ON m.sc = UPPER(TRIM(COALESCE(i.site_id,'')))
                          AND m.ic = TRIM(COALESCE(i.item_code,''))
        WHERE TRIM(COALESCE(i.invoice_no,'')) <> ''
        GROUP BY 1)`;
    const AHY_JOIN = `LEFT JOIN ahyor ao ON ao.n =
      regexp_replace(regexp_replace(TRIM(hw_payment_rows.invoice_no),'-.*$',''),'^(SIM\\d{4})0+','\\1')`;
    const SIMSEK_CARPAN = (dateCol) =>
      `CASE WHEN ${dateCol} > DATE '2026-07-15' THEN (1 - COALESCE(ao.oran,0)) ELSE 1 END`;

    // 1) Gerçekleşen ödemeler — payment_date bu ayda, payment_amount > 0
    const received = await pool.query(`
      WITH ${AHY_ORAN_CTE}
      SELECT
        EXTRACT(DAY FROM payment_date)::int AS gun,
        SUM((${AMT("payment_amount")}) * ${SIMSEK_CARPAN("payment_date")}) AS tutar
      FROM hw_payment_rows ${AHY_JOIN}
      WHERE to_char(payment_date, 'YYYY-MM') = $1
        AND COALESCE(payment_amount, 0) > 0
      GROUP BY gun
      ORDER BY gun
    `, [monthStr, usdRate]);

    // Türkiye saati ile bugünün tarihi
    const todayTR = new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Istanbul" }));
    const todayStr = `${todayTR.getFullYear()}-${String(todayTR.getMonth()+1).padStart(2,'0')}-${String(todayTR.getDate()).padStart(2,'0')}`;

    // 2a) Gelecek bekleyen tahsilat — due_date bu ayda, DUE_DATE > BUGÜN, remaining_amount > 0
    const pending = await pool.query(`
      WITH ${AHY_ORAN_CTE}
      SELECT
        EXTRACT(DAY FROM due_date)::int AS gun,
        SUM((${AMT("remaining_amount", 3)}) * ${SIMSEK_CARPAN("due_date")}) AS tutar
      FROM hw_payment_rows ${AHY_JOIN}
      WHERE to_char(due_date, 'YYYY-MM') = $1
        AND COALESCE(remaining_amount, 0) > 0
        AND due_date > $2::date
      GROUP BY gun
      ORDER BY gun
    `, [monthStr, todayStr, usdRate]);

    // 2b) Geciken/bugün vadeli ödenmemiş — due_date bu ayda, DUE_DATE <= BUGÜN, remaining_amount > 0
    const overdueHw = await pool.query(`
      WITH ${AHY_ORAN_CTE}
      SELECT
        EXTRACT(DAY FROM due_date)::int AS gun,
        SUM((${AMT("remaining_amount", 3)}) * ${SIMSEK_CARPAN("due_date")}) AS tutar
      FROM hw_payment_rows ${AHY_JOIN}
      WHERE to_char(due_date, 'YYYY-MM') = $1
        AND COALESCE(remaining_amount, 0) > 0
        AND due_date <= $2::date
      GROUP BY gun
      ORDER BY gun
    `, [monthStr, todayStr, usdRate]);

    // 3) Kesintiler — iki kaynak:
    //   a) Mahsup edilmiş: payment_amount < 0 VE remaining = 0 → payment_date bazlı
    //   b) Bekleyen: remaining_amount < 0 → due_date bazlı
    //   İki set birbirini dışladığı için toplama güvenlidir.
    const deductions = await pool.query(`
      SELECT gun, SUM(tutar)::numeric AS tutar FROM (
        SELECT
          EXTRACT(DAY FROM payment_date)::int AS gun,
          SUM(${AMT("payment_amount")}) AS tutar
        FROM hw_payment_rows
        WHERE to_char(payment_date, 'YYYY-MM') = $1
          AND COALESCE(payment_amount, 0) < 0
          AND COALESCE(remaining_amount, 0) = 0
        GROUP BY gun

        UNION ALL

        SELECT
          EXTRACT(DAY FROM due_date)::int AS gun,
          SUM(${AMT("remaining_amount")}) AS tutar
        FROM hw_payment_rows
        WHERE to_char(due_date, 'YYYY-MM') = $1
          AND COALESCE(remaining_amount, 0) < 0
        GROUP BY gun
      ) t
      GROUP BY gun
      ORDER BY gun
    `, [monthStr, usdRate]);

    res.json({
      ok: true,
      received:     received.rows,    // payment_date bazlı alınan
      pending:      pending.rows,     // due_date > bugün
      overdue_hw:   overdueHw.rows,   // due_date <= bugün, henüz tahsil edilmemiş
      deductions:   deductions.rows,  // negatif remaining (iade/kesinti)
    });
  } catch(e) {
    console.error("CASHFLOW MONTHLY ERROR:", e.message);
    res.status(500).json({ ok: false, error: e.message });
  }
});

/* ================== FINANCE UPCOMING COLLECTIONS ================== */
app.get("/finance/upcoming-payments", finansOkuma, async (req, res) => {
  try {
    const upcomingData = await buildUpcomingCollectionsData();
    const overdueData = await buildOverdueInvoicesData();

    // Bugün tahsil edilenler satır bazında: fatura → 2KX/AHY payı dağıtılır
    const todayReceivedResult = await pool.query(`
      SELECT invoice_no,
             COALESCE(payment_amount, 0) AS amt,
             UPPER(COALESCE(currency, 'TRY')) AS currency
      FROM hw_payment_rows
      WHERE payment_date IS NOT NULL
        AND payment_date::date = (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Istanbul')::date
        AND COALESCE(payment_amount, 0) <> 0
    `);
    let todayReceived = 0, todayR2kx = 0, todayRAhy = 0, todayRTekno = 0;
    for (const r of todayReceivedResult.rows) {
      const amt = r.currency === "USD"
        ? Number(r.amt) * Number(upcomingData.usdRate || 0)
        : Number(r.amt);
      todayReceived += amt;
      const ia = upcomingData.invAgg?.get?.(normInvNo(r.invoice_no));
      if (ia && ia.total > 0) {
        todayR2kx += amt * (ia.k2kx / ia.total);
        todayRAhy += amt * (ia.kahy / ia.total);
        todayRTekno += amt * ((ia.ktekno || 0) / ia.total);
      }
    }

    res.json({
      ok: true,
      rows: upcomingData.rows,
      overdue_payment_rows: upcomingData.overdue_payment_rows,  // hw_payment_rows geciken
      overdue_rows: overdueData.rows,                           // hw_invoice_rows geciken
      summary: {
        today_total: upcomingData.summary.today_total,
        week_total: upcomingData.summary.week_total,
        overdue_payment_total: upcomingData.summary.overdue_payment_total,
        today_received_total: todayReceived,
        today_received_2kx: todayR2kx,
        today_received_ahy: todayRAhy,
        today_received_tekno: todayRTekno,
        overdue_total: overdueData.total,
      },
    });
  } catch (err) {
    console.error("UPCOMING PAYMENTS ERROR:", err);
    res.status(500).json({
      ok: false,
      error: "Gelecek tahsilat planı alınırken hata oluştu",
      detail: err.message,
    });
  }
});

