// ─── FATURA PARSE HELPERs ────────────────────────────────────────────────────
function parseTurkishInvoice(rawText) {
  // ── Yardımcı: TR para sayısı → JS float ──────────────────────────────────
  const parseTRNum = (s) => {
    if (!s) return "";
    s = s.replace(/\s|TL|₺/g, "").trim();
    if (!s) return "";
    // 66.666,67 → nokta=binlik, virgül=ondalık
    if (/\d\.\d{3},\d/.test(s)) s = s.replace(/\./g, "").replace(",", ".");
    // 66,666.67 → virgül=binlik, nokta=ondalık (OCR bazen ters çevirir)
    else if (/\d,\d{3}\.\d/.test(s)) s = s.replace(/,/g, "");
    // 66.666 → son 3 basamak → binlik nokta
    else if (/^\d+\.\d{3}$/.test(s)) s = s.replace(".", "");
    // 66,67 tek virgül → ondalık
    else s = s.replace(/\./g, "").replace(",", ".");
    const n = parseFloat(s);
    return isNaN(n) ? "" : String(Math.round(n * 100) / 100);
  };

  // ── E-fatura PDF'leri iki sütun içerir: etiketler bir sütunda, değerler
  //    diğer sütunda → pdfminer bunları ayrı satırlar olarak verir.
  //    findAfterLabel: etiketi bul, ardından gelen satırlarda değeri ara ──────
  const lines = rawText.split(/\n/).map(l => l.trim()).filter(Boolean);
  const flat  = rawText.replace(/\r/g, " ").replace(/\n/g, " ").replace(/\s{2,}/g, " ");

  // Etiketten sonra ilk geçerli satırı döndür
  const findAfterLabel = (labelRe, valueRe) => {
    for (let i = 0; i < lines.length; i++) {
      if (labelRe.test(lines[i])) {
        // Aynı satırda değer var mı? (tek-satır format)
        const inLine = lines[i].match(valueRe);
        if (inLine) return inLine[1] || inLine[0];
        // Sonraki satırlarda ara (en fazla 5 satır)
        for (let j = i + 1; j < Math.min(i + 6, lines.length); j++) {
          const m = lines[j].match(valueRe);
          if (m) return m[1] || m[0];
        }
      }
    }
    return "";
  };

  // flat içinde tek-satır formatı için arama
  const findFlat = (patterns) => {
    for (const p of patterns) {
      const m = flat.match(p);
      if (m) for (let i = 1; i < m.length; i++) if (m[i]?.trim()) return m[i].trim();
    }
    return "";
  };

  // ── E-FATURA TABLOSU: Konum tabanlı eşleme ──────────────────────────────────
  // pdfminer e-fatura'yı sütun-önce okur:
  //   Özelleştirme No: / Senaryo: / Fatura Tipi: / Fatura No: / Fatura Tarihi: / Fatura Saati:
  //   ...ardından değerler:
  //   TR1.2 / TICARIFATURA / SATIS / ERS2026000000115 / 18-05-2026 / 20:43:54
  // Çözüm: etiketi bul, kaçıncı sırada olduğunu say, aynı sıradaki değeri al.
  const EF_LABEL_ORDER = [
    "Özelleştirme No:", "Senaryo:", "Fatura Tipi:",
    "Fatura No:", "Fatura Tarihi:", "Fatura Saati:",
  ];
  const efIdx = {}; // label → satır indeksi
  for (let i = 0; i < lines.length; i++) {
    const norm = lines[i].replace(/\s+/g, " ").trim();
    for (const lbl of EF_LABEL_ORDER) {
      if (norm.toLowerCase() === lbl.toLowerCase()) { efIdx[lbl] = i; break; }
    }
  }
  let efFaturaNo = "", efTarihi = "";
  const efFound = EF_LABEL_ORDER.filter(l => l in efIdx);
  if (efFound.length >= 3 && "Fatura No:" in efIdx) {
    const lastLabelLine = Math.max(...efFound.map(l => efIdx[l]));
    // Son etiketten sonraki satırlardaki değerleri topla
    const vals = [];
    for (let i = lastLabelLine + 1; i < lines.length && vals.length < efFound.length; i++) {
      if (lines[i].trim()) vals.push(lines[i].trim());
    }
    // Satır sırasına göre etiket → değer eşleme
    const sortedEfLabels = efFound.slice().sort((a, b) => efIdx[a] - efIdx[b]);
    sortedEfLabels.forEach((lbl, i) => {
      const val = vals[i] || "";
      if (lbl === "Fatura No:") efFaturaNo = val;
      if (lbl === "Fatura Tarihi:") {
        // Konum kaymasında (örn. araya "Düzenleme Tarihi:" girince) değer tarih
        // olmayabilir — tarih DEĞİLSE boş bırak ki alttaki genel arama çalışsın
        const dm = val.match(/(\d{2}[-./]\d{2}[-./]\d{4})/);
        efTarihi = dm ? dm[1] : "";
      }
    });
    // Konum eşleşmesi tarih bulamadıysa değer sütunundaki İLK tarihi al
    // (saat değil: GG-AA-YYYY deseni yalnız tarihe uyar)
    if (!efTarihi) {
      for (const v of vals) {
        const dm = String(v).match(/(\d{2}[-./]\d{2}[-./]\d{4})/);
        if (dm) { efTarihi = dm[1]; break; }
      }
    }
  }

  // ── FATURA NO ──────────────────────────────────────────────────────────────
  // EF_LABEL_ORDER bazen bilinen sahte değerler verebilir (SATIS, TICARIFATURA vb.)
  // Önce geçersiz değerleri temizle, SONRA fallback ara — aksi halde fallback hiç çalışmaz.
  let fatura_no = efFaturaNo;
  if (/^[0-9a-f\-]{30,}$/i.test(fatura_no)) fatura_no = "";       // ETTN UUID
  if (/^(TICARIFATURA|EARSIVFATURA|SATIS|ALIS|TR\d\.\d)$/i.test(fatura_no)) fatura_no = "";
  if (fatura_no && !/\d/.test(fatura_no)) fatura_no = "";          // salt harfse temizle

  // EFA/EFT/ERS/GIB stili e-fatura numarası — öncelikli arama (en spesifik)
  if (!fatura_no) {
    const m = flat.match(/\b((?:EFA|EFT|ERS|EAR|EAK|GIB|INV)\d{8,})\b/i);
    if (m) fatura_no = m[1].toUpperCase();
  }
  // "Fatura No:" etiketinden sonraki satırı ara
  if (!fatura_no) fatura_no = findAfterLabel(
    /fatura\s*no\s*:?\s*$/i,
    /^(?=.*\d)([A-Z0-9][A-Z0-9\/\-]{4,39})$/i
  );
  // findFlat fallback: yıl bazlı fatura no formatı (ERS2026xxx, ETS2026xxx vb.)
  if (!fatura_no) fatura_no = findFlat([
    /FATURA\s*NO\s*[:\|]?\s*([A-Z]{1,8}(?:20|19)\d{2}\d{4,})/i,
  ]);
  // Son çare: metinde herhangi bir yıl bazlı fatura no ara
  if (!fatura_no) {
    const m = flat.match(/\b([A-Z]{2,8}(?:20|19)\d{2}\d{4,})\b/);
    if (m) fatura_no = m[1];
  }

  // ── FATURA TARİHİ ──────────────────────────────────────────────────────────
  // Önce e-fatura konum tabanlı sonuç, yoksa genel arama
  let dateRaw = efTarihi;
  // Etiket-yakınlık araması: "Fatura Tarihi" geçen satırda ya da sonraki birkaç
  // satırda ilk tarihi al. PDF metin çıkarımı sütunları ayrı satırlara dökebilir
  // ve metin sırası görsel sırayla eşleşmez — genel "ilk tarih" yedeği bu yüzden
  // faturanın alt notlarındaki tarihleri (C-IN/C-OUT vb.) yakalayabiliyordu.
  const DATE_RX = /(\d{1,2}[-./]\d{1,2}[-./]\d{4})/;
  if (!dateRaw) {
    for (const lblRx of [/fatura\s*tar[iİıI]h/i, /d[üuÜU]zenleme\s*tar[iİıI]h/i]) {
      const li = lines.findIndex(l => lblRx.test(l));
      if (li === -1) continue;
      for (let j = li; j < Math.min(lines.length, li + 8); j++) {
        const dm = lines[j].match(DATE_RX);
        if (dm) { dateRaw = dm[1]; break; }
      }
      if (dateRaw) break;
    }
  }
  if (!dateRaw) dateRaw = findAfterLabel(
    /^fatura\s*tar[iİ]h[iİ]\s*:?\s*$/i,
    /(\d{2}[-./]\d{2}[-./]\d{4})/
  );
  if (!dateRaw) dateRaw = findFlat([
    /FATURA\s*TAR[İI]H[İI]\s*[:\|]?\s*(\d{2}[-./]\d{2}[-./]\d{4})/i,
    /D[ÜÜ]ZENLEME\s*TAR[İI]H[İI]\s*[:\|]?\s*(\d{2}[-./]\d{2}[-./]\d{4})/i,
    /(\d{2}[-./]\d{2}[-./]\d{4})/,
  ]);
  let fatura_tarihi = "";
  if (dateRaw) {
    const p = dateRaw.split(/[-./]/);
    if (p[2]?.length === 4) fatura_tarihi = `${p[2]}-${p[1].padStart(2,"0")}-${p[0].padStart(2,"0")}`;
  }

  // ── TEDARİKÇİ (satıcı/kesici) ──────────────────────────────────────────────
  // E-fatura'da "SAYIN" → alıcı, ondan önce gelen ilk ad → satıcı
  // Satıcı genellikle metnin en başında, TCKN/VKN bilgileriyle birlikte gelir
  let tedarikci = "";
  // 1) SATICI etiketi ile başlayan satır
  tedarikci = findFlat([
    /(?:SATICI\s*[Üü]NVAN[Iiİ]|SATICI\s*AD[Iİ]|SATICI)[^:]*:\s*([^\|]{5,80}?)(?:\s{3,}|VKN|V\.K|$)/i,
    /UNVANI\s*:\s*([^\|]{5,60})/i,
  ]);
  // 2) e-fatura PDF: TCKN/VKN/Vergi Dairesi bloğundan önceki ilk isim satırı
  if (!tedarikci) {
    // Metni satırlara böl, SAYIN'dan önceki kısmı al
    const sayinIdx = lines.findIndex(l => /^SAYIN$/i.test(l));
    const sellerLines = sayinIdx > 0 ? lines.slice(0, sayinIdx) : lines;
    // İlk gerçek isim satırı (sadece harf ve boşluk, en az 3 kelime veya en az 10 karakter)
    for (const l of sellerLines) {
      if (/^[A-ZÇŞĞÜÖİa-zçşğüöı\s\.]{8,70}$/.test(l) && !/^(SUBENO|MERSISNO|HIZMETNO|TICARETSICILNO|e-FATURA|e-ARŞİV|SAYIN)$/i.test(l)) {
        tedarikci = l.toUpperCase();
        break;
      }
    }
  }
  // 3) Firma adı satırlarını birleştir (Limited Şirketi vs.)
  if (tedarikci && !/LTD|A\.Ş|ANONİM|LİMİTED/i.test(tedarikci)) {
    // Tedarikçi satırından sonraki satır unvan eki olabilir
    const tIdx = lines.findIndex(l => l.toUpperCase().includes(tedarikci.split(" ")[0]));
    if (tIdx >= 0 && tIdx + 1 < lines.length) {
      const next = lines[tIdx + 1].trim();
      if (/LTD|A\.Ş|ANONİM|LİMİTED|TİCARET|SANAYİ|ŞİRKETİ/i.test(next)) {
        tedarikci = (tedarikci + " " + next.toUpperCase()).trim();
      }
    }
  }

  // ── TUTARLAR ───────────────────────────────────────────────────────────────
  // e-fatura'da etiket ve tutar ayrı satırlarda olabilir.
  // Özel durum: "Hesaplanan GERÇEK USULDE KATMA" + "DEĞER VERGİSİ(%20)" gibi
  // iki satıra bölünmüş etiketler için bitişik satırları da kontrol et.
  // 26.08.2026: pdfminer bazı e-arşiv PDF'lerini TEK dev satır olarak verir —
  // etiket satırında sayı ararken satırın başından değil, ETİKETTEN SONRAKİ
  // kısımdan aranmalı (yoksa "%0,00" iskonto oranı yakalanıyordu, GIB...147
  // tevkifat vakası). (?<!%) — "%20,00" gibi oran sayıları tutar sanılmasın.
  const NUM_RE = /(?<!%)([\d.]+,\d{2})/;
  const findAmount = (labelRe) => {
    for (let i = 0; i < lines.length; i++) {
      const matchSingle   = labelRe.test(lines[i]);
      // İki satır birleşik eşleme (etiket iki satıra bölünmüşse)
      const matchCombined = !matchSingle && i + 1 < lines.length
                            && labelRe.test(lines[i] + " " + lines[i + 1]);
      if (matchSingle || matchCombined) {
        // Aynı satırda sayı: etiketin geçtiği konumdan SONRASINI ara.
        if (matchSingle) {
          const at = lines[i].search(labelRe);
          const m = lines[i].slice(at).match(NUM_RE);
          if (m) return m[1];
        }
        // matchCombined: etiket lines[i+1] içinde olabilir, değer de aynı satırda olabilir.
        // Önce lines[i+1]'i kontrol et, sonra i+2'den ileriye bak.
        if (matchCombined) {
          const mNext = lines[i + 1].match(NUM_RE);
          if (mNext) return mNext[1];
        }
        // Sayıyı sonraki 1-3 satırda ara
        const searchFrom = matchCombined ? i + 2 : i + 1;
        for (let j = searchFrom; j < Math.min(searchFrom + 3, lines.length); j++) {
          const m2 = lines[j].match(NUM_RE);
          if (m2) return m2[1];
        }
      }
    }
    // flat metin araması (alternation'ı (?:...) ile grupla)
    const flatM = flat.match(new RegExp("(?:" + labelRe.source + ")[^\\d]{0,50}(\\d[\\d.,]+)", "i"));
    if (flatM) for (let k = 1; k < flatM.length; k++) if (flatM[k]?.trim()) return flatM[k].trim();
    return "";
  };

  // toplam — 26.08.2026 (tevkifat vakası): KDV tevkifatlı faturalarda
  // "Vergiler Dahil Toplam" ile "Ödenecek Tutar" FARKLIDIR — tevkif edilen
  // KDV satıcıya değil, alıcı tarafından sorumlu sıfatıyla (2 no.lu KDV
  // beyannamesi) vergi dairesine ödenir. Firmaya ödenecek gerçek borç
  // "Ödenecek Tutar"dır; bu yüzden önce o aranır, bulunamazsa Vergiler
  // Dahil / Genel Toplam kullanılır.
  const odenecek_raw = findAmount(/[ÖO0]DENECEK\s*TUTAR/i);
  const vergili_raw  = findAmount(/VERGiLER\s*DAHiL\s*TOPLAM|VERGİLER\s*DAHİL\s*TOPLAM|GENEL\s*TOPLAM/i);
  const toplam_raw   = odenecek_raw || vergili_raw;
  // KDV tevkifatı (kısmi tevkifat: nakliye 2/10, işgücü 9/10 vb.) — önce
  // özet bloktaki "Hesaplanan KDV Tevkifat" etiketi (tablo hücresindeki
  // "KDV TEVKİFAT (%20,00)=..." biçiminden daha güvenilir)
  const tevkifat_raw = findAmount(/HESAPLANAN\s*KDV\s*TEVK[İIi]FAT/i) || findAmount(/KDV\s*TEVK[İIi]FAT/i);
  // kdv: önce en spesifik "Hesaplanan KDV" etiketini ara (tablo başlığı olan
  // "KDV Tutarı" veya "KDV %20" daha önce yanlış eşleşmesin diye).
  // (?!\s*Tevk) — "Hesaplanan KDV Tevkifat" satırı KDV sanılmasın.
  let kdv_raw = findAmount(/HESAPLANAN\s*KDV(?!\s*TEVK)|KATMA\s*DE[ĞG]ER\s*VERG|DEĞER\s*VERGİSİ|DEGER\s*VERGISI/i);
  if (!kdv_raw) kdv_raw = findAmount(/KDV\s*TUTARI|KDV\s*%\d/i);
  // matrah: "Mal Hizmet Toplam Tutarı" + genel TOPLAM\s*TUTAR
  const matrah_raw  = findAmount(/MAL\s*H[İI]ZMET\s*TOPLAM|MATRAH|KDV\s*HAR[İI][ÇC]|ARA\s*TOPLAM|TOPLAM\s*TUTAR/i);

  console.log("[parseTurkishInvoice]", { fatura_no, fatura_tarihi, tedarikci, toplam_raw, kdv_raw, matrah_raw, tevkifat_raw });

  let tutar  = parseTRNum(matrah_raw);
  let kdv    = parseTRNum(kdv_raw);
  let toplam = parseTRNum(toplam_raw);
  const tevkifat = parseTRNum(tevkifat_raw);
  const vergiliToplam = parseTRNum(vergili_raw);
  // Ödenecek Tutar okunamadıysa tevkifat düşülerek türetilir
  if (tevkifat && vergiliToplam && (!toplam || Number(toplam) === Number(vergiliToplam))) {
    toplam = String(Math.round((Number(vergiliToplam) - Number(tevkifat)) * 100) / 100);
  }
  // OCR bazı etiketleri okuyamayabilir — "Not: CARI_BAKIYE:13.200,00 TL"
  // dipnotu KDV dahil toplamı verir, boş kalan toplam buradan doldurulur
  if (!toplam) {
    const mB = flat.match(/CARI[_\s]*BAKIYE[:\s]*([\d.]+,\d{2})/i);
    if (mB) toplam = parseTRNum(mB[1]);
  }
  // Üç değerden ikisi belliyse eksik olan türetilir (tutar+kdv=toplam).
  // Tevkifatlı faturada KDV, vergiler dahil toplamdan türetilir (ödenecekten değil).
  if (!toplam && tutar && kdv) {
    toplam = Math.round((tutar + kdv) * 100) / 100;
    if (tevkifat) toplam = Math.round((toplam - Number(tevkifat)) * 100) / 100;
  }
  if (!kdv && toplam && tutar) {
    const kdvTaban = Number(vergiliToplam || 0) || (Number(toplam) + Number(tevkifat || 0));
    if (kdvTaban >= tutar) kdv = Math.round((kdvTaban - tutar) * 100) / 100;
  }
  if (!tutar && toplam && kdv && toplam >= kdv) tutar = Math.round((toplam - kdv) * 100) / 100;
  // 26.08.2026: OCR bazen KDV hücresine toplam tutarı yazıyor (%0 KDV'li
  // faturalar) — kdv=tutar=toplam tutarsızsa KDV farktan yeniden hesaplanır
  if (kdv && tutar && toplam && Number(kdv) === Number(toplam) && Number(tutar) === Number(toplam)) {
    kdv = Math.round((Number(toplam) - Number(tutar)) * 100) / 100;
  }

  return {
    fatura_no,
    fatura_tarihi,
    tedarikci,
    tutar,
    kdv,
    toplam_tutar: toplam,
    tevkifat: tevkifat || "",
  };
}

// PDF metin çıkarma — önce Python pdfminer (dijital PDF), yoksa OCR.space
// pdf2json ile metin çıkarma: text-run'lar satır (y) bazında gruplanır,
// x sırasına dizilir; karakterler ayrı run gelebildiği için boşluk x-aralığına
// göre eklenir. Çıktıda etiket+tutar aynı satırda birleşir ("Ödenecek Tutar13.200,00 TL").
function extractPdfTextPdf2json(buf) {
  return new Promise((resolve, reject) => {
    let PDFParser;
    try { PDFParser = require("pdf2json"); } catch (e) { return reject(e); }
    const pp = new PDFParser();
    const dec = (t) => { try { return decodeURIComponent(t); } catch { return t; } };
    pp.on("pdfParser_dataError", (e) => reject(new Error(e?.parserError?.message || e?.parserError || "pdf2json parse hatası")));
    pp.on("pdfParser_dataReady", (data) => {
      try {
        const rows = new Map();
        (data.Pages || []).forEach((pg, pi) => {
          (pg.Texts || []).forEach((t) => {
            const y = Math.round(t.y * 2) / 2 + pi * 1000;
            if (!rows.has(y)) rows.set(y, []);
            rows.get(y).push({ x: t.x, w: t.w || 0, s: (t.R || []).map((r) => dec(r.T)).join("") });
          });
        });
        const lines = [...rows.entries()].sort((a, b) => a[0] - b[0]).map(([, arr]) => {
          arr.sort((a, b) => a.x - b.x);
          let out = "", prevEnd = null;
          for (const t of arr) {
            if (prevEnd !== null && t.x - prevEnd > 0.45) out += " ";
            out += t.s.trim() === "" ? " " : t.s;
            prevEnd = t.x + (t.w || 0.4);
          }
          return out.replace(/\s+/g, " ").trim();
        });
        resolve(lines.join("\n"));
      } catch (err) { reject(err); }
    });
    pp.parseBuffer(buf);
  });
}

async function extractPdfText(pdfBuffer, isPDF, { ocr = true } = {}) {
  // ── 1. Python pdfminer (dijital/e-fatura PDF'leri için en iyi) ────────────
  if (isPDF) {
    try {
      const { execFile } = require("child_process");
      const os = require("os");
      const tmpFile = path.join(os.tmpdir(), `invoice_${Date.now()}.pdf`);
      require("fs").writeFileSync(tmpFile, pdfBuffer);
      const text = await new Promise((resolve, reject) => {
        execFile("python3", [
          "-c",
          // sys.stdout.reconfigure: UTF-8 zorla (Render gibi ortamlarda LANG=C olabilir)
          `import sys; sys.stdout.reconfigure(encoding='utf-8'); from pdfminer.high_level import extract_text; print(extract_text(sys.argv[1]))`,
          tmpFile,
        ], {
          timeout: 15000,
          maxBuffer: 5 * 1024 * 1024,
          encoding: "utf8",
          env: { ...process.env, PYTHONIOENCODING: "utf-8", PYTHONUTF8: "1" },
        }, (err, stdout, stderr) => {
          try { require("fs").unlinkSync(tmpFile); } catch (_) {}
          if (err) return reject(err);
          resolve(stdout);
        });
      });
      if (text && text.trim().length > 50) {
        console.log("[invoice-parse] pdfminer snippet:", text.slice(0, 300));
        return text;
      }
    } catch (e) {
      console.warn("[invoice-parse] pdfminer failed, falling back to OCR:", e.message);
    }
  }

  // ── 1.5 pdf2json (saf JS): Render'da python/pdfminer yoksa dijital
  // e-fatura PDF'lerinin metni buradan çıkar — OCR'a yalnız taramalılar düşer.
  // OCR bazı etiket hücrelerini ("Hesaplanan KDV", "Ödenecek Tutar") hiç
  // okuyamıyordu ve tutarlar boş kalıyordu (ASY vakası, 11.08.2026).
  // 26.08.2026 (faturamyolda vakası): Type3/custom-glyph fontlu PDF'lerde
  // pdf2json harfleri çözemeyip "G G Ş İ D..." çöpü üretiyor; metin "dolu"
  // göründüğünden OCR'a düşülmüyordu. Çöp tespiti: 3+ harfli kelime yoksa
  // metin geçersiz sayılır ve OCR'a düşülür.
  const pdfTextCop = (text) => {
    const kelime = (text.match(/[A-Za-zÇĞİÖŞÜçğıöşü]{3,}/g) || []).length;
    const karakter = text.replace(/\s/g, "").length;
    return karakter > 100 && kelime < karakter / 20;
  };
  if (isPDF) {
    try {
      const text = await extractPdfTextPdf2json(pdfBuffer);
      if (text && text.trim().length > 50 && !pdfTextCop(text)) {
        console.log("[invoice-parse] pdf2json snippet:", text.slice(0, 300));
        return text;
      }
      if (text && pdfTextCop(text)) {
        console.warn("[invoice-parse] pdf2json cop metin (Type3 font?), OCR'a dusuluyor");
      }
    } catch (e) {
      console.warn("[invoice-parse] pdf2json failed, falling back to OCR:", e.message);
    }
  }

  // ── 2. OCR.space (taramalı PDF veya resim için fallback) ──────────────────
  // Yapay zekâ okumasının yedeğinde kapalı (ocr:false): belge herkese açık deneme anahtarıyla dış servise gönderilmez
  if (!ocr) return "";
  try {
    const apiKey = process.env.OCR_SPACE_KEY || "helloworld";
    const base64 = pdfBuffer.toString("base64");
    const mimeType = isPDF ? "application/pdf" : "image/jpeg";
    const body = new URLSearchParams({
      base64Image: `data:${mimeType};base64,${base64}`,
      language: "tur",
      isOverlayRequired: "false",
      detectOrientation: "true",
      scale: "true",
      OCREngine: "2",
    });
    const ocrResp = await fetch("https://api.ocr.space/parse/image", {
      method: "POST",
      headers: { apikey: apiKey, "Content-Type": "application/x-www-form-urlencoded" },
      body: body.toString(),
      signal: AbortSignal.timeout(20000),
    });
    const ocrJson = await ocrResp.json();
    const text = (ocrJson?.ParsedResults || []).map(r => r.ParsedText || "").join("\n");
    console.log("[invoice-parse] OCR snippet:", text.slice(0, 300));
    return text;
  } catch (e) {
    console.error("[invoice-parse] OCR error:", e.message);
    return "";
  }
}

// POST /invoice-parse — fatura PDF'i / fotoğrafı: geçici belge + YAPAY ZEKÂ ile okuma (24.10.2026, Orhan)
// Kök neden (24.10.2026): okuma yalnız metin katmanı + regex idi (tedarikçi, VKN, ETTN, satırlar çıkmıyordu; taranmış
// belgede OCR.space deneme anahtarına düşüyordu) ve web, doldurulan alanları React güncelleyicisi içinde saydığı için
// "0 alan" yazıp yine de yeşil gösteriyordu. Artık: faturaOkuma.js (Claude, tüm sayfalar, JSON şeması, sayısal doğrulama)
// → okuma {durum: HAZIR | KISMI | BASARISIZ, alanlar, satırlar, doğrulama}. Yapay zekâ kullanılamazsa (anahtar yok,
// sağlayıcı hatası, zaman aşımı) hata AŞAMASIYLA bildirilir; varsa kural tabanlı temel alanlar "KISMI" olarak eklenir —
// boş sonuç başarı gibi gösterilmez. Okuma hiçbir kaydı oluşturmaz/değiştirmez; kayıt kullanıcı Kaydet'e basınca olur.
const faturaAi = require("./faturaOkuma");
const uploadInvoiceParse = multer({ storage: multer.memoryStorage(), limits: { fileSize: 20 * 1024 * 1024 } });
function regexOkumaDonustur(p) {
  // Eski kural tabanlı ayrıştırıcı sonucu → okuma biçimi (yalnız bulunan alanlar; satır/VKN/ETTN yok)
  const sayi = (v) => (v === "" || v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Number(v));
  const f = {
    belge_fatura_mi: true, belge_turu: null, fatura_tipi: null, fatura_no: p.fatura_no || null, ettn: null,
    fatura_tarihi: p.fatura_tarihi || null, fatura_saati: null, para_birimi: null,
    tedarikci: { unvan: p.tedarikci || null, vkn_tckn: null, vergi_dairesi: null }, alici: { unvan: null, vkn_tckn: null, vergi_dairesi: null },
    toplamlar: { mal_hizmet_toplami: null, toplam_iskonto: null, vergi_haric_tutar: sayi(p.tutar), kdv_toplam: sayi(p.kdv),
      vergiler_dahil_toplam: sayi(p.tevkifat) ? null : sayi(p.toplam_tutar), tevkifat_tutari: sayi(p.tevkifat), odenecek_tutar: sayi(p.toplam_tutar) },
    kdv_dokumu: [], diger_vergiler: [], satirlar: [], sayfa_sayisi: null, okunan_sayfalar: [], alan_kaynaklari: [],
    belirsiz_alanlar: [{ alan: "tümü", neden: "Kural tabanlı yedek okuma — tedarikçi/alıcı VKN, ETTN ve satırlar okunmadı; belgeden kontrol edin" }],
  };
  const kontroller = faturaAi._test.dogrula(f, null);
  const sin = faturaAi._test.sinifla(f, kontroller);
  return { ...f, dogrulama: kontroller, ...sin, durum: sin.alan_sayisi ? "KISMI" : "BASARISIZ", model: null, kaynak: "kural" };
}
app.post("/invoice-parse", faturaYazma, uploadInvoiceParse.single("file"), async (req, res) => {
  if (!req.file) return res.status(400).json({ ok: false, asama: "yukleme", error: "Dosya gelmedi" });
  const ext = path.extname(utf8Name(req.file.originalname)).toLowerCase();
  const isPDF = ext === ".pdf" || req.file.mimetype === "application/pdf";
  const sharp = require("sharp");

  // Yapay zekâ girdisi: PDF olduğu gibi (tüm sayfalar); fotoğraf JPEG'e normalize (HEIC vb. dahil, uzun kenar ≤ 2400 px)
  let aiBuffer = req.file.buffer, aiMime = "application/pdf", gorselHata = null;
  if (!isPDF) {
    try { aiBuffer = await sharp(req.file.buffer).rotate().resize({ width: 2400, height: 2400, fit: "inside", withoutEnlargement: true }).jpeg({ quality: 88 }).toBuffer(); aiMime = "image/jpeg"; }
    catch (e) { gorselHata = e.message; }
  }
  if (gorselHata) return res.status(415).json({ ok: false, asama: "dosya_turu", error: "Görsel okunamadı — PDF, JPG, PNG veya WEBP yükleyin" });

  let pdfBuffer = req.file.buffer;
  if (!isPDF) {
    // Belge arşivi için resmi PDF'e dönüştür (fatura belgesi her zaman PDF saklanır)
    const PDFDocument = require("pdfkit");
    pdfBuffer = await new Promise((resolve, reject) => {
      const doc = new PDFDocument({ autoFirstPage: false, margin: 20 });
      const chunks = [];
      doc.on("data", c => chunks.push(c));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", reject);
      try {
        const img = doc.openImage(aiBuffer);
        const maxW = 555, maxH = 802;
        const ratio = Math.min(maxW / img.width, maxH / img.height);
        doc.addPage({ size: [img.width * ratio + 40, img.height * ratio + 40] });
        doc.image(aiBuffer, 20, 20, { width: img.width * ratio });
        doc.end();
      } catch (e) { reject(e); }
    });
  }

  // Supabase'e geçici yükle — temp_key olarak gerçek storage yolunu dön (kayıtta faturaya bağlanır)
  let tempUrl = null, tempKey = null;
  try {
    const { url, filePath } = await uploadToStorage("fatura-belgeler", `tmp-${Date.now()}.pdf`, pdfBuffer, "application/pdf");
    tempUrl = url;
    tempKey = filePath;
  } catch (e) {
    console.error("[invoice-parse] storage error:", e.message);
  }

  let okuma, hata = null;
  try {
    okuma = await faturaAi.faturaOku({ buffer: aiBuffer, mimeType: aiMime });
  } catch (e) {
    const asama = e.asama || "bilinmeyen";
    hata = { asama, mesaj: e.message };
    console.error("[invoice-parse] yapay zekâ okuma hatası —", asama + ":", e.message);
    // Yedek: kural tabanlı temel alanlar (yalnız PDF metin katmanı; OCR yok) — açıkça "kısmi" ve hata nedeniyle
    try { okuma = isPDF ? regexOkumaDonustur(parseTurkishInvoice(await extractPdfText(pdfBuffer, true, { ocr: false }))) : null; }
    catch (e2) { console.error("[invoice-parse] yedek okuma hatası:", e2.message); okuma = null; }
    if (!okuma || !okuma.alan_sayisi) return res.status(e.http || 502).json({ ok: false, asama, error: e.message, temp_key: tempKey, temp_url: tempUrl });
  }
  // Eski istemciler için düz alanlar (ödenen tutar YAZILMAZ — "ödenecek tutar" ödeme yapıldığını göstermez)
  const T = okuma.toplamlar || {};
  const parsed = {
    fatura_no: okuma.fatura_no || "", fatura_tarihi: okuma.fatura_tarihi || "", tedarikci: okuma.tedarikci?.unvan || "",
    tutar: T.vergi_haric_tutar ?? (T.mal_hizmet_toplami != null ? Math.round((T.mal_hizmet_toplami - (T.toplam_iskonto || 0)) * 100) / 100 : ""), kdv: T.kdv_toplam ?? "", toplam_tutar: (T.tevkifat_tutari ? T.odenecek_tutar : (T.vergiler_dahil_toplam ?? T.odenecek_tutar)) ?? "",
    tevkifat: T.tevkifat_tutari ?? "",
  };
  res.json({ ok: true, okuma, hata, parsed, temp_key: tempKey, temp_url: tempUrl });
});

app.post(
  "/invoice-entries/:id/belge",
  faturaYazma, // 23.10.2026: kapısızdı — finans yetkilisi ya da kendi firması kapsamında alt marka
  uploadFaturaBelge.single("belge"),
  async (req, res) => {
    const { id } = req.params;
    const file = req.file;
    if (!file) return res.status(400).json({ error: "Dosya gelmedi" });

    const PDFDocument = require("pdfkit");
    const ext = path.extname(file.originalname).toLowerCase();
    const pdfFilename = `fatura-${id}-${Date.now()}.pdf`;

    try {
      let pdfBuffer;
      if (ext === ".pdf") {
        pdfBuffer = file.buffer;
      } else {
        pdfBuffer = await new Promise((resolve, reject) => {
          const doc = new PDFDocument({ autoFirstPage: false, margin: 20 });
          const chunks = [];
          doc.on("data", c => chunks.push(c));
          doc.on("end", () => resolve(Buffer.concat(chunks)));
          doc.on("error", reject);

          const img = doc.openImage(file.buffer);
          const maxW = 555, maxH = 802;
          const ratio = Math.min(maxW / img.width, maxH / img.height);
          const w = img.width * ratio, h = img.height * ratio;

          doc.addPage({ size: [w + 40, h + 40] });
          doc.image(file.buffer, 20, 20, { width: w, height: h });
          doc.end();
        });
      }

      const { url } = await uploadToStorage("fatura-belgeler", pdfFilename, pdfBuffer, "application/pdf");
      await pool.query(
        "UPDATE invoice_entries SET belge_path = $1 WHERE id = $2",
        [url, id]
      );

      res.json({ ok: true, filename: pdfFilename, url });
    } catch (err) {
      console.error("Belge upload hatası:", err.message);
      res.status(500).json({ error: err.message });
    }
  }
);

app.delete("/invoice-entries/:id/belge", faturaYazma, async (req, res) => {
  const { id } = req.params;
  try {
    const r = await pool.query("SELECT belge_path FROM invoice_entries WHERE id=$1", [id]);
    const belge = r.rows[0]?.belge_path;
    if (belge) await deleteFromStorage(belge);
    await pool.query("UPDATE invoice_entries SET belge_path = NULL WHERE id=$1", [id]);
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

