app.get("/hr/puantaj", puantajOkuma, async (req, res) => {
  try {
    const { ay, yil } = req.query;
    const r = await pool.query(
      `SELECT p.*, per.ad_soyad, per.unvan, per.net_maas, per.bankadan_gosterilen, per.elden_verilen, per.aktif,
              COALESCE(per.marka,'ERC') AS personel_marka
       FROM puantaj p JOIN personel per ON p.personel_id = per.id
       WHERE EXTRACT(MONTH FROM p.tarih)=$1 AND EXTRACT(YEAR FROM p.tarih)=$2
       ORDER BY per.ad_soyad, p.tarih`,
      [ay, yil]
    );
    res.json(ikMaskele(req, r.rows, (x) => x.personel_marka));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post("/hr/puantaj", puantajYazma, async (req, res) => {
  try {
    const { personel_id, tarih, durum, created_by } = req.body;
    // 17.09.2026 (Orhan): işten ayrılma tarihinden SONRAYA ve bordro dışı (puantaj_haric)
    // personele puantaj yazılmaz — Adem Karhan vakası: ayrıldıktan sonra her güne "Gelmedi" girilmişti
    const per = await pool.query(
      `SELECT to_char(isten_ayrilma_tarihi,'YYYY-MM-DD') AS ayrilma, COALESCE(puantaj_haric,false) AS haric FROM personel WHERE id=$1`, [personel_id]);
    if (per.rows[0]?.haric) return res.status(400).json({ error: "Bu personel puantaj dışıdır (sabit maaş)" });
    const _t = String(tarih || "").slice(0, 10);
    if (per.rows[0]?.ayrilma && _t > per.rows[0].ayrilma)
      return res.status(400).json({ error: `İşten ayrılma tarihi (${per.rows[0].ayrilma}) sonrasına puantaj girilemez` });
    // Arşivlenmiş çıkış ile yeni giriş arasındaki günlere (çalışmadığı dönem) puantaj yazılmaz
    const _bos = await pool.query(
      `SELECT to_char(d.isten_ayrilma,'YYYY-MM-DD') AS ayrilma, to_char(p.ise_giris_tarihi,'YYYY-MM-DD') AS giris
         FROM personel_calisma_donemi d JOIN personel p ON p.id = d.personel_id
        WHERE d.personel_id = $1 AND d.isten_ayrilma < $2::date
          AND p.ise_giris_tarihi IS NOT NULL AND p.ise_giris_tarihi > $2::date
          AND NOT EXISTS (SELECT 1 FROM personel_calisma_donemi d2 WHERE d2.personel_id = d.personel_id
                          AND (d2.ise_giris IS NULL OR d2.ise_giris <= $2::date) AND d2.isten_ayrilma >= $2::date)
        LIMIT 1`, [personel_id, _t]).catch(() => ({ rows: [] }));
    if (_bos.rows[0])
      return res.status(400).json({ error: `Bu tarih iki çalışma dönemi arasında (çıkış ${_bos.rows[0].ayrilma}, yeniden giriş ${_bos.rows[0].giris}) — puantaj girilemez` });
    const r = await pool.query(
      `INSERT INTO puantaj (personel_id,tarih,durum,created_by)
       VALUES ($1,$2,$3,$4)
       ON CONFLICT (personel_id,tarih) DO UPDATE SET durum=$3, created_by=$4 RETURNING *`,
      [personel_id, tarih, durum||"CALISDI", created_by||""]
    );
    res.json(r.rows[0]);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

