// Ay özeti: her personel için hakediş hesabı
// ── MANUEL HAKEDİŞ (25.08.2026, Orhan) ──
// İK maaş tablosunda hakediş hücresine tıklanıp elle tutar girilebilir;
// girilen ay için sistem hesabını ezer, boş kaydedilince otomatiğe döner.
pool.query(`CREATE TABLE IF NOT EXISTS maas_hakedis_override (
  id SERIAL PRIMARY KEY,
  personel_id INTEGER NOT NULL,
  donem TEXT NOT NULL,
  tutar NUMERIC NOT NULL,
  created_by TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(personel_id, donem)
)`).then(() => Promise.all([
  pool.query(`ALTER TABLE maas_hakedis_override ENABLE ROW LEVEL SECURITY`).catch(() => {}),
  pool.query(`DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='maas_hakedis_override' AND policyname='service_role_all') THEN
      CREATE POLICY service_role_all ON maas_hakedis_override FOR ALL TO service_role USING (true) WITH CHECK (true);
    END IF; END $$`).catch(() => {}),
])).catch(() => {});

const HAKEDIS_OVERRIDE_ROLLER = ["admin", "platform_admin", "direktor", "muhasebe", "genel_mudur"];
app.put("/hr/hakedis-override", authMiddleware, async (req, res) => {
  try {
    if (!HAKEDIS_OVERRIDE_ROLLER.includes(String(req.user?.role || "").toLowerCase()))
      return res.status(403).json({ error: "Yetkiniz yok" });
    const { personel_id, donem, tutar } = req.body;
    if (!personel_id || !/^\d{4}-\d{2}$/.test(String(donem || "")))
      return res.status(400).json({ error: "personel_id ve donem (YYYY-AA) zorunlu" });
    if (tutar === null || tutar === undefined || tutar === "") {
      await pool.query(`DELETE FROM maas_hakedis_override WHERE personel_id=$1 AND donem=$2`, [personel_id, donem]);
      return res.json({ ok: true, silindi: true });
    }
    const t = Number(tutar);
    if (!Number.isFinite(t) || t < 0) return res.status(400).json({ error: "Geçersiz tutar" });
    await pool.query(
      `INSERT INTO maas_hakedis_override (personel_id, donem, tutar, created_by)
       VALUES ($1,$2,$3,$4)
       ON CONFLICT (personel_id, donem)
       DO UPDATE SET tutar=EXCLUDED.tutar, created_by=EXCLUDED.created_by, created_at=CURRENT_TIMESTAMP`,
      [personel_id, donem, t, req.user?.email || null]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.get("/hr/puantaj/ozet", puantajOkuma, async (req, res) => {
  try {
    const { ay, yil } = req.query;
    // O ayın geçerli maaşıyla hesapla (maaş geçmişi versiyonlaması)
    const _ozetDonem = `${yil}-${String(ay).padStart(2, "0")}`;
    const personelList = await pool.query(`
      SELECT p.*,
        COALESCE(g.net_maas, p.net_maas) AS net_maas,
        COALESCE(g.bankadan_gosterilen, p.bankadan_gosterilen) AS bankadan_gosterilen,
        COALESCE(g.elden_verilen, p.elden_verilen) AS elden_verilen
      FROM personel p
      LEFT JOIN LATERAL (
        SELECT net_maas, bankadan_gosterilen, elden_verilen
        FROM personel_maas_gecmisi
        WHERE personel_id = p.id AND donem <= $1
        ORDER BY donem DESC LIMIT 1
      ) g ON true
      WHERE p.aktif=true OR p.isten_ayrilma_tarihi IS NOT NULL
         OR EXISTS (SELECT 1 FROM personel_calisma_donemi d WHERE d.personel_id = p.id)
      ORDER BY p.ad_soyad`, [_ozetDonem]);
    // Çalışma dönemi: arşiv dönemi olan personelde o ayla kesişen dönemin giriş/çıkışı kullanılır
    {
      const dm = await ikDonemleriYukle(personelList.rows.map(x => x.id));
      const _ab = `${_ozetDonem}-01`;
      const _as = `${_ozetDonem}-${String(new Date(Number(yil), Number(ay), 0).getDate()).padStart(2, "0")}`;
      personelList.rows = personelList.rows.map(p => {
        const sec = ikDonemSec(p, dm.get(p.id), _ab, _as);
        if (!sec) return p;
        if (sec.disinda) return { ...p, _donemDisi: true };
        const _d = (s) => (s ? new Date(`${s}T00:00:00`) : null);
        const ek = sec.arsiv ? null : ikAyniAyEkDonem(p, dm.get(p.id), _ab, _as);
        return { ...p, ise_giris_tarihi: _d(sec.giris), isten_ayrilma_tarihi: _d(sec.ayrilma), aktif: sec.arsiv ? true : p.aktif, _ekDonem: ek };
      });
    }

    // Individual records to detect Sundays
    const puantajRows = await pool.query(
      `SELECT personel_id, durum, tarih FROM puantaj
       WHERE EXTRACT(MONTH FROM tarih)=$1 AND EXTRACT(YEAR FROM tarih)=$2`, [ay, yil]
    );

    // TR resmi tatiller (2024-2027)
    const TR_TATIL = ["2024-01-01","2024-04-23","2024-05-01","2024-05-19","2024-07-15","2024-08-30","2024-10-29","2024-03-29","2024-03-30","2024-03-31","2024-04-01","2024-04-02","2024-04-03","2024-06-16","2024-06-17","2024-06-18","2024-06-19","2025-01-01","2025-03-29","2025-03-30","2025-03-31","2025-04-01","2025-04-02","2025-04-23","2025-05-01","2025-05-19","2025-06-06","2025-06-07","2025-06-08","2025-06-09","2025-07-15","2025-08-30","2025-10-29","2026-01-01","2026-03-18","2026-03-19","2026-03-20","2026-03-21","2026-03-22","2026-04-23","2026-05-01","2026-05-19","2026-05-26","2026-05-27","2026-05-28","2026-05-29","2026-07-15","2026-08-30","2026-10-29","2027-01-01","2027-03-08","2027-03-09","2027-03-10","2027-03-11","2027-03-12","2027-04-23","2027-05-01","2027-05-19","2027-05-16","2027-05-17","2027-05-18","2027-05-19","2027-07-15","2027-08-30","2027-10-29"];

    // Cumulative all-time: total Sundays worked, resmi tatil worked, and total DINLENME days given
    const bakiyeRows = await pool.query(
      `SELECT personel_id,
        COUNT(*) FILTER (WHERE durum='CALISDI' AND EXTRACT(DOW FROM tarih)=0) AS pazar_calisdi_toplam,
        COUNT(*) FILTER (WHERE durum='DINLENME') AS dinlenme_toplam
       FROM puantaj GROUP BY personel_id`
    );

    // Cumulative resmi tatil çalışma (CALISDI on a known resmi tatil date)
    const tatilCalisdi = {};
    {
      const allCalisdi = await pool.query(`SELECT personel_id, tarih FROM puantaj WHERE durum='CALISDI'`);
      allCalisdi.rows.forEach(r => {
        const d = (r.tarih||"").toString().slice(0,10);
        if (TR_TATIL.includes(d)) {
          tatilCalisdi[r.personel_id] = (tatilCalisdi[r.personel_id]||0) + 1;
        }
      });
    }

    // 19.10.2026 (Orhan): maaş avansı, ödendiği ayın değil "maaştan kesilecek dönem"in (avans.donem)
    // hakedişinden düşer — 17.10'da verilen Eylül avansı Ekim'den değil Eylül'den kesilir, Ekim'e
    // ikinci kez yazılmaz. Dönemi boş eski kayıtlar ödeme ayına sayılır. (İK tablosuyla aynı kural.)
    const avansList = await pool.query(
      `SELECT personel_id, SUM(tutar) as toplam FROM avans
       WHERE COALESCE(NULLIF(donem,''), to_char(tarih,'YYYY-MM')) = $1 AND avans_turu='MAAS' GROUP BY personel_id`,
      [`${yil}-${String(ay).padStart(2, "0")}`]
    );

    // Manuel hakediş (25.08.2026): bu ay için elle girilmiş tutarlar sistem
    // hesabını ezer (İK tablosunda hakediş hücresine tıklanarak girilir).
    const donemStr = `${yil}-${String(ay).padStart(2, "0")}`;
    const overrideMap = {};
    try {
      const ov = await pool.query(`SELECT personel_id, tutar FROM maas_hakedis_override WHERE donem=$1`, [donemStr]);
      ov.rows.forEach(r => { overrideMap[r.personel_id] = Number(r.tutar); });
    } catch {}

    // Bordro esası (20.08.2026 — Orhan kararı): SGK/bordro pratiğinde ay 30 gün
    // sayılır. Hem işe giriş pro-rata'sı hem devamsızlık kesintisi AYNI tabandan
    // (net/30) hesaplanır — eskiden giriş oranı takvim günü (28/30/31), kesinti
    // 26 gün üzerindendi ve kazanılan gün ile kaybedilen gün eşit değildi.
    const REFERANS_GUN = 30;
    const totalDays = new Date(yil, ay, 0).getDate();

    const ozet = personelList.rows.map(p => {
      // Ayrılma sonrası kayıtlar yok sayılır; bordro dışı (puantaj_haric) personelde kesinti yok — sabit maaş
      const _ayrilma = p.isten_ayrilma_tarihi ? new Date(p.isten_ayrilma_tarihi).getTime() : null;
      const pRows = p.puantaj_haric ? [] : puantajRows.rows.filter(r => r.personel_id === p.id
        && (_ayrilma === null || new Date(r.tarih).getTime() <= _ayrilma));

      const calisilan = pRows.filter(r => r.durum === "CALISDI").length;
      // 17.09.2026 (Orhan): pazar tatildir — o gün ne yazılırsa yazılsın maaştan kesinti OLMAZ.
      // Pazar çalışılırsa (CALISDI) aşağıda pazarCalisdi olarak fazla çalışmaya yazılır.
      const gelmedi = pRows.filter(r => r.durum === "GELMEDI" && new Date(r.tarih).getDay() !== 0).length;
      const dinlenme = pRows.filter(r => r.durum === "DINLENME").length;

      // Count CALISDI entries that fall on a Sunday (DOW=0)
      const pazarCalisdi = pRows.filter(r => {
        if (r.durum !== "CALISDI") return false;
        return new Date(r.tarih).getDay() === 0;
      }).length;

      const netMaas = Number(p.net_maas) || 0;
      const dailyRate = netMaas / REFERANS_GUN;
      // İşe giriş bu ayın İÇİNDEYSE giriş öncesi günler hakedişe girmez:
      // taban maaş kalan takvim günü oranıyla kısılır (Ender/Selçuk vakası —
      // puantajda giriş öncesi gün kaydı olmadığından kesinti hiç oluşmuyordu)
      // Giriş ayında çalışılan gün sayısı (giriş günü dahil) / 30; tam ay
      // çalışanda 1'i aşmaz (31 günlük aylarda fazla ödeme oluşmasın).
      let girisFactor = 1;
      if (p.ise_giris_tarihi) {
        const g = new Date(p.ise_giris_tarihi);
        if (!Number.isNaN(g.getTime()) && g.getFullYear() === Number(yil) && (g.getMonth() + 1) === Number(ay)) {
          const calisilanTakvimGun = totalDays - g.getDate() + 1;
          girisFactor = Math.min(1, calisilanTakvimGun / REFERANS_GUN);
        }
      }
      // 17.09.2026 (Burak Ülker vakası): ay sonrası pasife alınan personel o ayın özetinden
      // düşüyordu (tablo tam maaşı gösteriyordu). Özete "o ay istihdamda olan" girer; ayrılma bu
      // ayın içindeyse ayrılma sonrası günler hakedişe girmez (giriş + ayrılma aynı aydaysa ikisi birden).
      let istihdamda = !!p.aktif;
      const _gd = p.ise_giris_tarihi ? new Date(p.ise_giris_tarihi) : null;
      const _ad = p.isten_ayrilma_tarihi ? new Date(p.isten_ayrilma_tarihi) : null;
      const _ayBas = new Date(Number(yil), Number(ay) - 1, 1).getTime();
      const _aySon = new Date(Number(yil), Number(ay), 0).getTime();
      if (_ad && !Number.isNaN(_ad.getTime())) {
        istihdamda = _ad.getTime() >= _ayBas;
        if (_ad.getTime() <= _aySon) {
          const basGun = (_gd && !Number.isNaN(_gd.getTime()) && _gd.getFullYear() === Number(yil) && (_gd.getMonth() + 1) === Number(ay)) ? _gd.getDate() : 1;
          girisFactor = Math.min(1, Math.max(0, _ad.getDate() - basGun + 1) / REFERANS_GUN);
        }
      }
      if (_gd && !Number.isNaN(_gd.getTime()) && _gd.getTime() > _aySon) istihdamda = false;
      if (p._donemDisi) istihdamda = false; // hiçbir çalışma dönemi bu ayla kesişmiyor
      // Pazar/resmi tatil bonusu maaşa EKLENMEZ — dinlenme bakiyesine birikir
      // 15.10.2026: maaşı ya da işe giriş tarihi girilmemiş personele otomatik hakediş yazılmaz (sıfır maaş gibi sunulmaz, "bilgi eksik")
      const bilgiEksik = !p.puantaj_haric && (!p.ise_giris_tarihi || netMaas <= 0);
      let hakedilenOto = bilgiEksik ? 0 : Math.max(0, Math.round(netMaas * girisFactor - gelmedi * dailyRate));
      // 20.10.2026: aynı ay içinde ayrılıp yeniden başlayan — ayın başındaki kapanmış dönem kendi maaşıyla eklenir;
      // giriş öncesi günler yukarıdaki girisFactor'de zaten düşülmüş, bu segment yalnız [eski giriş..eski çıkış] günlerini sayar
      let ekHakedis = 0, ekBilgiEksik = false, ekBanka = 0, ekElden = 0;
      if (p._ekDonem && !p.puantaj_haric) {
        const ek = p._ekDonem;
        const ekBasGun = (ek.giris && ek.giris.slice(0, 7) === `${yil}-${String(ay).padStart(2, "0")}`) ? Number(ek.giris.slice(8, 10)) : 1;
        const ekSonGun = Number(ek.ayrilma.slice(8, 10));
        const ekFactor = Math.min(1, Math.max(0, ekSonGun - ekBasGun + 1) / REFERANS_GUN);
        const ekGelmedi = pRows.filter(r => { const g = new Date(r.tarih).getDate(); return r.durum === "GELMEDI" && new Date(r.tarih).getDay() !== 0 && g >= ekBasGun && g <= ekSonGun; }).length;
        if (ek.net_maas == null || ek.net_maas <= 0) ekBilgiEksik = true;
        else {
          ekHakedis = Math.max(0, Math.round(ek.net_maas * ekFactor - ekGelmedi * (ek.net_maas / REFERANS_GUN)));
          ekBanka = Math.max(0, Math.round(ek.bankadan_gosterilen * ekFactor - ekGelmedi * (ek.bankadan_gosterilen / REFERANS_GUN)));
          ekElden = Math.max(0, Math.round(ek.elden_verilen * ekFactor - ekGelmedi * (ek.elden_verilen / REFERANS_GUN)));
        }
        hakedilenOto += ekHakedis;
      }
      const pazarBonus = 0; // Artık maaşa yansımıyor, dinlenme hakkı olarak birikiyor

      const bankaDailyRate = (Number(p.bankadan_gosterilen) || 0) / REFERANS_GUN;
      const eldenDailyRate = (Number(p.elden_verilen) || 0) / REFERANS_GUN;
      let bankadan = Math.max(0, Math.round((Number(p.bankadan_gosterilen) || 0) * girisFactor - gelmedi * bankaDailyRate)) + ekBanka;
      let elden = Math.max(0, Math.round((Number(p.elden_verilen) || 0) * girisFactor - gelmedi * eldenDailyRate)) + ekElden;

      // Manuel hakediş varsa sistem hesabını ezer; banka/elden ayrımı da
      // manuel tutarın net maaşa oranıyla ölçeklenir
      const manuelTutar = overrideMap[p.id];
      const hakedisManuel = manuelTutar != null;
      const hakedilen = hakedisManuel ? Math.max(0, Math.round(manuelTutar)) : hakedilenOto;
      if (hakedisManuel) {
        const oran = netMaas > 0 ? hakedilen / netMaas : 1;
        bankadan = Math.round((Number(p.bankadan_gosterilen) || 0) * oran);
        elden = Math.round((Number(p.elden_verilen) || 0) * oran);
      }

      const avansRow = avansList.rows.find(a => a.personel_id === p.id);
      const avans = Number(avansRow?.toplam || 0);

      // Cumulative DİNLENME balance
      const bakiye = bakiyeRows.rows.find(r => r.personel_id === p.id);
      const toplamPazarCalisdi = parseInt(bakiye?.pazar_calisdi_toplam || 0);
      const toplamDinlenme = parseInt(bakiye?.dinlenme_toplam || 0);
      const toplamResmiTatilCalisdi = tatilCalisdi[p.id] || 0;
      // dinlenme bakiye: (pazar + resmi tatil) - dinlenme alınanlar
      const toplamExtraGun = toplamPazarCalisdi + toplamResmiTatilCalisdi;
      const dinlenmeBakiye = Math.max(0, toplamExtraGun - toplamDinlenme);
      const extraHakedis = Math.round(dinlenmeBakiye * (netMaas / REFERANS_GUN) * 1.5);

      return {
        personel_id: p.id, ad_soyad: p.ad_soyad, unvan: p.unvan, aktif: p.aktif, istihdamda,
        net_maas: p.net_maas, bankadan_gosterilen: p.bankadan_gosterilen, elden_verilen: p.elden_verilen,
        calisilan_gun: calisilan, gelmedi_gun: gelmedi, pazar_calisdi: pazarCalisdi,
        pazar_bonus: pazarBonus, dinlenme_gun: dinlenme, toplam_gun: totalDays,
        hakedilen_maas: hakedilen, bankadan, elden, avans,
        hakedis_manuel: hakedisManuel, hakedis_otomatik: hakedilenOto, bilgi_eksik: bilgiEksik,
        ek_donem: p._ekDonem ? { giris: p._ekDonem.giris, ayrilma: p._ekDonem.ayrilma, hakedis: ekHakedis, bilgi_eksik: ekBilgiEksik } : null,
        kalan: hakedilen - avans,
        dinlenme_bakiye: dinlenmeBakiye,
        toplam_pazar_calisdi: toplamPazarCalisdi,
        toplam_resmi_tatil_calisdi: toplamResmiTatilCalisdi,
        toplam_dinlenme: toplamDinlenme,
        extra_hakedis: extraHakedis,
      };
    }).filter(p => p.istihdamda);

    const _ozetMarka = new Map(personelList.rows.map((x) => [x.id, x.marka]));
    res.json(ikMaskele(req, ozet, (x) => _ozetMarka.get(x.personel_id)));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ---- AVANS ----
app.get("/hr/avans", ikOkuma, async (req, res) => {
  try {
    const { personel_id, turu } = req.query;
    const conditions = [];
    const params = [];
    if (personel_id) { params.push(personel_id); conditions.push(`a.personel_id=$${params.length}`); }
    if (turu) { params.push(turu); conditions.push(`a.avans_turu=$${params.length}`); }
    const where = conditions.length ? "WHERE " + conditions.join(" AND ") : "";
    // 19.10.2026: DATE kolonları metin döner (YYYY-MM-DD) — JS Date'e çevrilince saat dilimi
    // bir gün geri kaydırıyordu (17.10 kaydı ekranda 16.10 görünüyor, düzenlemede geri kayıyordu).
    // kayit_zamani = sisteme kayıt anı (otomatik işlem bilgisi); donem = maaştan kesilecek ay.
    const r = await pool.query(
      `SELECT a.*, p.ad_soyad,
              to_char(a.tarih,'YYYY-MM-DD') AS tarih,
              to_char(a.odeme_tarihi,'YYYY-MM-DD') AS odeme_tarihi,
              to_char(a.created_at,'YYYY-MM-DD HH24:MI') AS kayit_zamani,
              ${avansOdeyenSql("a")} AS odeyen_marka, COALESCE(p.marka,'ERC') AS personel_marka
       FROM avans a JOIN personel p ON a.personel_id=p.id ${where} ORDER BY a.tarih DESC, a.id DESC`,
      params
    );
    res.json(ikKapsamSuz(req, r.rows));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

