app.put("/hr/is-avans/:id/reddet", avansOnayKapisi, async (req, res) => {
  try {
    const { id } = req.params;
    const { red_aciklama, reddeden_email } = req.body;
    const onceki = (await pool.query("SELECT id, durum, firma, tarih, personel_id FROM is_avans_talep WHERE id=$1", [id])).rows[0];
    if (!onceki) return res.status(404).json({ error: "Kayıt bulunamadı" });
    if (await avansOnayOnKontrol(req, res, onceki)) return;
    // 28.10.2026: ödenmiş / reddedilmiş talep reddedilemez (ödeme kaydı yetim kalmasın)
    if (["TAMAMLANDI", "REDDEDILDI"].includes(onceki.durum)) return res.status(409).json({ error: "Bu talep ödenmiş ya da zaten reddedilmiş; reddedilemez" });
    // 25.10.2026 (onay devri): devralan direktör yalnız kendi firmasının PM_ONAY'daki talebini reddeder; devredilmiş
    // firmanın direktör adımında eski listedeki direktör (RM/PM yetkisi de yoksa) red veremez
    if (["TALEP", "ROLLOUT_MUDUR_ONAY", "PM_ONAY"].includes(onceki.durum)) {
      const pd = await onayPanel.avansPdYetkisi(req, await onayPanel.talepFirmasiAvans(onceki));
      const devralan = pd.kaynak === "devir" && pd.izin;
      if (!avansOnayciMiEski(req.user) && !(devralan && onceki.durum === "PM_ONAY")) return res.status(403).json({ error: "Bu talep onay kapsamınızda değil" });
      if (pd.devir && onceki.durum === "PM_ONAY" && !devralan && !avansYetkiliEski(req, "RM") && !avansYetkiliEski(req, "PM") && _rol(req.user) !== "muhasebe")
        return res.status(403).json({ error: pd.hata || "Bu firmanın direktör adımı başka bir kullanıcıya devredildi" });
    }
    const r = await pool.query(
      "UPDATE is_avans_talep SET durum='REDDEDILDI', red_aciklama=$1, reddeden_email=$2 WHERE id=$3 AND durum=$4 RETURNING *",
      [red_aciklama, reddeden_email || _eposta(req.user), id, onceki.durum]
    );
    if (!r.rows[0]) return onayCakismasi(res);
    if (r.rows[0]) await islemGecmisiYaz(req, "avans", id, "RED", { durum: onceki?.durum || null }, { durum: "REDDEDILDI" }, red_aciklama || null);
    res.json(r.rows[0]);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// 11.09.2026 (Orhan): aynı kişinin farklı yazılışları (BEYAZIT/Beyazıt, Yokus/Yokuş,
// Mehmet bağcı/MEHMET BAĞCI) tek isimde birleşir. Anahtar = Türkçe karakter + büyük/küçük
// harf duyarsız; gösterim = en çok Türkçe karakter taşıyan yazılışın "Baş Harf Büyük" hali.
const _adAnahtar = (v) => String(v || "").toLocaleLowerCase("tr-TR")
  .replace(/ı/g, "i").replace(/ş/g, "s").replace(/ğ/g, "g").replace(/ü/g, "u").replace(/ö/g, "o").replace(/ç/g, "c")
  .normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/\s+/g, " ").trim();
const _adBaslik = (v) => String(v || "").trim().replace(/\s+/g, " ").toLocaleLowerCase("tr-TR").split(" ")
  .map(w => (w === "ve" || !w) ? w : w.charAt(0).toLocaleUpperCase("tr-TR") + w.slice(1)).join(" ");
function adlariTeklestir(rows, alanlar) {
  if (!Array.isArray(rows)) return rows;
  const skor = (a) => (String(a).match(/[^\x00-\x7F]/g) || []).length;
  const en = {};
  for (const r of rows) for (const f of alanlar) {
    const a = r && r[f]; if (!a) continue;
    const k = _adAnahtar(a);
    if (!en[k] || skor(a) > skor(en[k])) en[k] = a;
  }
  return rows.map(r => {
    if (!r) return r;
    const o = { ...r };
    for (const f of alanlar) if (o[f]) o[f] = _adBaslik(en[_adAnahtar(o[f])] || o[f]);
    return o;
  });
}
app.get("/hr/is-avans/excel", authMiddleware, async (req, res) => {
  try {
    const ExcelJS = require("exceljs");
    const wb = new ExcelJS.Workbook();
    wb.creator = "ERC Sistem";

    const ws = wb.addWorksheet("İş Avansı Talepleri");

    let { email, durum, gider_turu, bolge, proje, baslangic, bitis, firma, ara, ara_kapsam } = req.query;
    let personelKilidi = null; // personel: yalnız kendi kayıtları (talep eden VEYA adına açılan)
    if (!avansTamGorus(req)) { email = null; personelKilidi = String(req.user.email || "").toLowerCase(); }
    const conditions = [];
    const params = [];
    if (email) { conditions.push(`t.talep_eden_email = $${params.length+1}`); params.push(email); }
    if (personelKilidi) {
      conditions.push(`(LOWER(t.talep_eden_email) = $${params.length+1} OR t.personel_id = (SELECT id FROM personel WHERE LOWER(TRIM(email)) = $${params.length+1} AND aktif = true LIMIT 1))`);
      params.push(personelKilidi);
    }
    if (firma) { conditions.push(`UPPER(COALESCE(t.firma,'')) = $${params.length+1}`); params.push(String(firma).toUpperCase()); }
    const kapsamX = altMarkaKapsam(req);
    if (kapsamX) {
      conditions.push(`t.tarih >= DATE '${kapsamX.devir}'`);
      conditions.push(`(UPPER(COALESCE(t.firma,'')) = '${kapsamX.kod}' OR (COALESCE(t.firma,'') = '' AND UPPER(COALESCE(p.marka,'ERC')) = ANY('{${kapsamX.bordro.join(",")}}'::text[])))`);
    }
    if (!pmKisiselGorur(req)) conditions.push(`NOT ${pmAvansSahibiSql("t", "p")}`);
    if (durum) { conditions.push(`t.durum = $${params.length+1}`); params.push(durum); }
    if (gider_turu) { conditions.push(`t.gider_turu = $${params.length+1}`); params.push(gider_turu); }
    if (bolge) { conditions.push(`t.bolge = $${params.length+1}`); params.push(bolge); }
    if (proje) { conditions.push(`t.proje = $${params.length+1}`); params.push(proje); }
    if (baslangic) { conditions.push(`t.tarih >= $${params.length+1}`); params.push(baslangic); }
    if (bitis) { conditions.push(`t.tarih <= $${params.length+1}`); params.push(bitis); }
    const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
    const list = await pool.query(`
      SELECT t.*, p.ad_soyad as personel_ad
      FROM is_avans_talep t
      LEFT JOIN personel p ON t.personel_id = p.id
      ${where}
      ORDER BY t.tarih DESC, t.created_at DESC
    `, params);

    // 11.09.2026 (Orhan): paneldeki arama Excel'e de uygulanır. Varsayılan kapsam "KIME" =
    // avansın üzerinde olduğu kişi (personel seçilmemişse talep eden kendisi). Türkçe
    // karakter duyarsız: "beyazit" → "Beyazıt".
    const trNorm = (v) => String(v || "").toLocaleLowerCase("tr-TR")
      .replace(/ı/g, "i").replace(/ş/g, "s").replace(/ğ/g, "g").replace(/ü/g, "u").replace(/ö/g, "o").replace(/ç/g, "c")
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
    list.rows = adlariTeklestir(list.rows, ["personel_ad", "talep_eden_ad"]);
    const kimeAd = (t) => t.personel_ad || t.talep_eden_ad || "";
    const araN = trNorm(ara);
    if (araN) {
      const kap = String(ara_kapsam || "KIME").toUpperCase();
      list.rows = list.rows.filter((t) => {
        const kime = trNorm(kimeAd(t)), talep = trNorm(t.talep_eden_ad);
        if (kap === "KIME") return kime.includes(araN);
        if (kap === "TALEP_EDEN") return talep.includes(araN);
        return kime.includes(araN) || talep.includes(araN) || trNorm(t.aciklama).includes(araN);
      });
    }

    // Title row
    ws.mergeCells("A1:O1");
    const titleCell = ws.getCell("A1");
    const _baslikEk = [ara && String(ara).trim(), gider_turu, bolge, proje, baslangic || bitis ? `${baslangic || "…"} – ${bitis || "…"}` : ""].filter(Boolean).join(" · ");
    titleCell.value = "İŞ AVANSI TALEP RAPORU" + (_baslikEk ? " — " + _baslikEk : "");
    titleCell.font = { bold: true, size: 14, color: { argb: "FFFFFFFF" }, name: "Arial" };
    titleCell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF1E3A5F" } };
    titleCell.alignment = { horizontal: "center", vertical: "middle" };
    ws.getRow(1).height = 28;

    // Header row
    const colDefs = [
      { header: "Kayıt No",         key: "id",         width: 10 },
      { header: "Tarih",            key: "tarih",       width: 13 },
      { header: "Talep Eden",       key: "talep_eden",  width: 20 },
      { header: "Personel (Avans Sahibi)", key: "personel", width: 24 },
      { header: "Gider Türü",       key: "gider",       width: 16 },
      { header: "Bölge",            key: "bolge",       width: 13 },
      { header: "Proje",            key: "proje",       width: 18 },
      { header: "Firma",            key: "firma",       width: 11 },
      { header: "Plaka",            key: "plaka",       width: 12 },
      { header: "Tutar (₺)",        key: "tutar",       width: 13 },
      { header: "Açıklama",         key: "aciklama",    width: 28 },
      { header: "Not",              key: "not",         width: 22 },
      { header: "Durum",            key: "durum",       width: 18 },
      { header: "Onay Tarihi",      key: "onay",        width: 14 },
      { header: "Ödeme Tarihi",     key: "odeme",       width: 14 },
    ];

    const headerRow = ws.getRow(2);
    colDefs.forEach((col, i) => {
      const cell = headerRow.getCell(i + 1);
      cell.value = col.header;
      cell.font = { bold: true, color: { argb: "FFFFFFFF" }, name: "Arial", size: 10 };
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF2563EB" } };
      cell.alignment = { horizontal: "center", vertical: "middle", wrapText: true };
      cell.border = { bottom: { style: "thin", color: { argb: "FF1D4ED8" } } };
      ws.getColumn(i + 1).width = col.width;
    });
    headerRow.height = 22;

    const durumLabels = {
      TALEP: "Talep Edildi",
      ROLLOUT_MUDUR_ONAY: "Rollout Müdür Onayında",
      PM_ONAY: "PM Onayında",
      DIREKTOR_ONAY: "Direktör Onayında",
      TAMAMLANDI: "Tamamlandı ✓",
      REDDEDILDI: "Reddedildi ✗"
    };

    const fmtDate = v => v ? (v.toISOString?.().split("T")[0] || String(v).split("T")[0]) : "";

    list.rows.forEach((t, idx) => {
      const rowNum = idx + 3;
      const row = ws.getRow(rowNum);
      const isEven = idx % 2 === 0;

      const values = [
        t.id,
        fmtDate(t.tarih),
        t.talep_eden_ad || "",
        kimeAd(t), // personel kendisi için talep ettiyse talep eden = avans sahibi
        t.gider_turu || "",
        t.bolge || "",
        t.proje || "",
        altMarkaMi(t.firma) ? String(t.firma).toUpperCase() : t.firma ? "ŞİMŞEK" : "",
        t.plaka || "",
        Number(t.tutar),
        t.aciklama || "",
        t.not_aciklama || "",
        durumLabels[t.durum] || t.durum,
        fmtDate(t.direktor_onay_tarihi || t.pm_onay_tarihi),
        fmtDate(t.odeme_tarihi),
      ];

      values.forEach((val, ci) => {
        const cell = row.getCell(ci + 1);
        cell.value = val;
        cell.font = { name: "Arial", size: 10 };
        cell.alignment = { vertical: "middle", wrapText: ci === 10 || ci === 11 };

        // Row background
        let bg = isEven ? "FFFFFFFF" : "FFF0F4FF";
        if (t.durum === "TAMAMLANDI") bg = isEven ? "FFD1FAE5" : "FFBCF0DA";
        else if (t.durum === "REDDEDILDI") bg = isEven ? "FFFEE2E2" : "FFFECACA";
        else if (t.durum === "PM_ONAY" || t.durum === "DIREKTOR_ONAY") bg = isEven ? "FFFEF3C7" : "FFFDE68A";

        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: bg } };
        cell.border = { bottom: { style: "hair", color: { argb: "FFE2E8F0" } } };

        if (ci === 9) { // Tutar column
          cell.numFmt = '#,##0.00 ₺';
          cell.alignment = { horizontal: "right", vertical: "middle" };
          cell.font = { name: "Arial", size: 10, bold: true };
        }
        if (ci === 7 && altMarkaMi(val)) { // Firma: alt marka (AHY/TEKNO) vurgusu
          cell.font = { name: "Arial", size: 10, bold: true, color: { argb: "FF92400E" } };
          cell.alignment = { horizontal: "center", vertical: "middle" };
        }
        if (ci === 7 && val === "ŞİMŞEK") cell.alignment = { horizontal: "center", vertical: "middle" };
        if (ci === 8) cell.alignment = { horizontal: "center", vertical: "middle" };  // Plaka
        if (ci === 12) cell.alignment = { horizontal: "center", vertical: "middle" }; // Durum
        if (ci === 0) cell.alignment = { horizontal: "center", vertical: "middle" };  // ID
      });

      row.height = 18;
    });

    // Totals row
    const totRow = ws.getRow(list.rows.length + 3);
    totRow.getCell(9).value = "TOPLAM:";
    totRow.getCell(9).font = { bold: true, name: "Arial" };
    totRow.getCell(9).alignment = { horizontal: "right" };
    totRow.getCell(10).value = { formula: `SUM(J3:J${list.rows.length + 2})` };
    totRow.getCell(10).numFmt = '#,##0.00 ₺';
    totRow.getCell(10).font = { bold: true, name: "Arial", color: { argb: "FF166534" } };
    totRow.getCell(10).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFDCFCE7" } };
    totRow.height = 20;

    // Freeze panes: freeze title + header
    ws.views = [{ state: "frozen", xSplit: 0, ySplit: 2, topLeftCell: "A3", showGridLines: false }];
    // Excel içinde de sütun filtresi (Personel/Gider Türü seçerek süzmek için)
    ws.autoFilter = { from: { row: 2, column: 1 }, to: { row: Math.max(2, list.rows.length + 2), column: colDefs.length } };

    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename=is_avans_talepleri.xlsx`);
    await wb.xlsx.write(res);
    res.end();
  } catch (e) { res.status(500).json({ error: e.message }); }
});

