// GET all forms (with totals)
app.get("/hr/masraf-form", async (req, res) => {
  try {
    const u = optionalAuth(req);
    if (!u) return res.status(401).json({ error: "Oturum gerekli" });
    // Kişisel kapsam: onay zincirinde olmayan kullanıcı yalnız talep ettiği ya da adına açılan formları alır
    const kisisel = !masrafTamGorus(req);
    const kisiselSql = `(LOWER(TRIM(COALESCE(mf.talep_eden_email,''))) = LOWER(TRIM($1)) OR LOWER(TRIM(COALESCE(p.email,''))) = LOWER(TRIM($1)))`;
    const kParams = kisisel ? [String(u.email || "")] : [];
    const k = altMarkaKapsam(req);
    if (k) {
      // Alt marka: yalnız bordro kapsamındaki personelin formları ve devirden sonraki kalemler;
      // toplam ve kalem sayısı kapsam içi kalemlerden hesaplanır, eski kalemler sızmaz
      const { rows } = await pool.query(`
        SELECT mf.*, p.ad_soyad as personel_ad,
          COALESCE(SUM(mk.tutar) FILTER (WHERE ${kapsamKalemSql(k)}),0) as genel_toplam,
          COUNT(mk.id) FILTER (WHERE ${kapsamKalemSql(k)})::int AS kapsam_kalem,
          COUNT(mk.id) FILTER (WHERE NOT (${kapsamKalemSql(k)}))::int AS kapsam_disi_kalem
        FROM masraf_form mf
        LEFT JOIN personel p ON p.id = mf.personel_id
        LEFT JOIN masraf_kalem mk ON mk.form_id = mf.id
        WHERE ${kapsamPersonelSql(k)}${kisisel ? ` AND ${kisiselSql}` : ""}
        GROUP BY mf.id, p.ad_soyad
        HAVING COUNT(mk.id) FILTER (WHERE ${kapsamKalemSql(k)}) > 0
        ORDER BY mf.created_at DESC`, kParams);
      return res.json(rows);
    }
    const { rows } = await pool.query(`
      SELECT mf.*, p.ad_soyad as personel_ad,
        COALESCE(SUM(mk.tutar),0) as genel_toplam
      FROM masraf_form mf
      LEFT JOIN personel p ON p.id = mf.personel_id
      LEFT JOIN masraf_kalem mk ON mk.form_id = mf.id
      ${kisisel ? `WHERE ${kisiselSql}` : ""}
      GROUP BY mf.id, p.ad_soyad
      ORDER BY mf.created_at DESC
    `, kParams);
    res.json(rows);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET masraf forms filtered by email (mobile app)
// ── Mobil Dashboard: email ile tek seferde tüm kişisel veriler ──────────────
app.get("/hr/mobile-dashboard", async (req, res) => {
  try {
    // 21.10.2026: kişi oturumdan (JWT) alınır — sorgudaki ?email= ile başkasının panosu açılamaz.
    // Mobil zaten kendi user.email / user.name'ini gönderiyor; token'da e-posta yoksa eski davranış.
    const _u = optionalAuth(req) || {};
    const email = _u.email || req.query.email;
    const name = _u.email ? (_u.name || req.query.name) : req.query.name;
    if (!email) return res.status(400).json({ error: "email gerekli" });

    const now = new Date();
    const ay  = now.getMonth() + 1;
    const yil = now.getFullYear();

    // Türkçe karakter normalizasyonu (ı→i, İ→i, ğ→g, ü→u, ş→s, ö→o, ç→c)
    const normTr = s => (s||'').toLowerCase()
      .replace(/ı/g,'i').replace(/İ/g,'i').replace(/ğ/g,'g')
      .replace(/ü/g,'u').replace(/ş/g,'s').replace(/ö/g,'o').replace(/ç/g,'c');

    // 1. Personel bilgisi — önce email, sonra ad_soyad ile fallback
    let personelRes = await pool.query(
      "SELECT id, ad_soyad, unvan, bolge, email FROM personel WHERE LOWER(TRIM(email))=LOWER(TRIM($1)) AND aktif=true LIMIT 1",
      [email]
    );
    if (!personelRes.rows[0] && name) {
      // Türkçe normalize edilerek ad_soyad ile dene (ı/i, İ/i farkını aşar)
      const normName = normTr(name.trim());
      personelRes = await pool.query(
        `SELECT id, ad_soyad, unvan, bolge, email FROM personel
         WHERE aktif=true
           AND LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
             TRIM(ad_soyad),'İ','I'),'Ş','S'),'Ğ','G'),'Ü','U'),'Ö','O'),'Ç','C'))
             = REPLACE($1,'ı','i')
         LIMIT 1`,
        [normName]
      );
    }
    const personel = personelRes.rows[0] || null;
    const personelId = personel?.id || null;
    // Avans/masraf sorgularında gerçek email'i kullan (personel tablosundaki),
    // yoksa gönderilen email ile dene
    const queryEmail = personel?.email || email;

    // 2. Bu ay puantaj özeti
    let puantaj = { calisilan: 0, dinlenme: 0, gelmedi: 0, toplam_gun: 0, fazla_mesai_gun: 0 };
    if (personelId) {
      const pRes = await pool.query(
        `SELECT durum, COUNT(*)::int as sayi FROM puantaj
         WHERE personel_id=$1 AND EXTRACT(MONTH FROM tarih)=$2 AND EXTRACT(YEAR FROM tarih)=$3
         GROUP BY durum`,
        [personelId, ay, yil]
      );
      pRes.rows.forEach(r => {
        if (r.durum === 'CALISDI')   puantaj.calisilan  = r.sayi;
        if (r.durum === 'DINLENME')  puantaj.dinlenme   = r.sayi;
        if (r.durum === 'GELMEDI')   puantaj.gelmedi    = r.sayi;
      });
      puantaj.toplam_gun = puantaj.calisilan + puantaj.dinlenme + puantaj.gelmedi;
      // Hafta sonu (Cumartesi=6, Pazar=0) veya resmi tatilde CALISDI kayıtları = fazla mesai günleri
      // DOW: 0=Pazar, 6=Cumartesi — hafta sonu CALISDI kayıtları = fazla mesai
      const fmRes = await pool.query(
        `SELECT COUNT(*)::int as sayi FROM puantaj
         WHERE personel_id=$1
           AND EXTRACT(MONTH FROM tarih)=$2
           AND EXTRACT(YEAR FROM tarih)=$3
           AND durum = 'CALISDI'
           AND EXTRACT(DOW FROM tarih) IN (0, 6)`,
        [personelId, ay, yil]
      );
      // Ayrıca resmi tatil olarak işaretlenmiş çalışılan günler (RESMI_TATIL durumunda CALISDI olarak girilmiş)
      // Bunu DINLENME sayısıyla da destekliyoruz (her DINLENME = 1 fazla mesai günü karşılığı)
      const fazlaHaftaSonu = Number(fmRes.rows[0]?.sayi || 0);
      puantaj.fazla_mesai_gun = fazlaHaftaSonu + puantaj.dinlenme;
    }

    // 3. İş avansları (son 5) — kendi açtıkları + personel olarak adına açılanlar
    const avansRes = await pool.query(
      `SELECT t.id, t.tutar, t.aciklama, t.gider_turu, t.bolge, t.proje, t.durum, t.tarih, t.created_at,
              t.talep_eden_ad, p.ad_soyad as personel_ad
       FROM is_avans_talep t
       LEFT JOIN personel p ON p.id = t.personel_id
       WHERE LOWER(t.talep_eden_email)=LOWER($1)
          OR (t.personel_id IS NOT NULL AND t.personel_id = $2)
       ORDER BY t.created_at DESC LIMIT 5`,
      [queryEmail, personelId]
    );
    const avanslar = avansRes.rows;
    const bekleyenAvans = avanslar.filter(a => !['TAMAMLANDI','REDDEDILDI'].includes(a.durum)).length;

    // 4. Masraf formları (son 5)
    const masrafRes = await pool.query(
      `SELECT mf.id, mf.durum, mf.created_at, mf.donem, mf.form_no,
        COALESCE(SUM(mk.tutar),0) as toplam_tutar,
        COUNT(mk.id)::int as kalem_sayisi
       FROM masraf_form mf
       LEFT JOIN masraf_kalem mk ON mk.form_id = mf.id
       WHERE LOWER(mf.talep_eden_email)=LOWER($1)
       GROUP BY mf.id ORDER BY mf.created_at DESC LIMIT 5`,
      [queryEmail]
    );
    const masraflar = masrafRes.rows;
    const bekleyenMasraf = masraflar.filter(f => !['TAMAMLANDI','ODENDI','REDDEDILDI'].includes(f.durum)).length;

    // 5. Ödenmemiş trafik cezaları
    let cezalar = [];
    let toplamCeza = 0;
    if (personelId) {
      const cezaRes = await pool.query(
        `SELECT id, tutar, aciklama, tarih FROM avans
         WHERE personel_id=$1 AND avans_turu='TRAFIK_CEZA' AND odendi=false ORDER BY tarih DESC`,
        [personelId]
      );
      cezalar = cezaRes.rows;
      toplamCeza = cezalar.reduce((s, c) => s + Number(c.tutar || 0), 0);
    }

    // 5b. Masraf formundaki TRAFIK_CEZA kalemleri:
    //     - Bu kişinin oluşturduğu formlardan VEYA
    //     - ceza_personel_id ile bu kişiye atanmış olanlar
    const cezaKalemRes = await pool.query(
      `SELECT mk.id, mk.tutar, mk.aciklama, mk.tarih, mk.plaka, mk.ceza_belge_url, mk.odeme_belge_url,
              mf.id as form_id, mf.durum as form_durum
       FROM masraf_kalem mk
       JOIN masraf_form mf ON mf.id = mk.form_id
       WHERE mk.kategori='TRAFIK_CEZA'
         AND COALESCE(mk.maastan_kesildi, false) = false
         AND (LOWER(mf.talep_eden_email)=LOWER($1) OR ($2::int IS NOT NULL AND mk.ceza_personel_id=$2::int))
       ORDER BY mk.tarih DESC LIMIT 20`,
      [queryEmail, personelId]
    );
    const cezaKalemler = cezaKalemRes.rows;

    // 6. İş avansı bakiye — web paneli (/hr/is-avans/bakiye) ile AYNI kaynak:
    // is_avans_talep'te kişiye PERSONEL olarak atanan TAMAMLANDI avanslar +
    // personel bağlanmamış kendi talepleri. (Eski kod İK 'avans' tablosundan
    // okuyordu ve web'den 50.000 eksik gösteriyordu — 10.08.2026 vakası.)
    let avansToplamOnaylanan = 0;
    {
      const bakiyeAvansRes = await pool.query(
        `SELECT COALESCE(SUM(t.tutar),0) as toplam
         FROM is_avans_talep t
         JOIN personel p ON p.id = t.personel_id
         WHERE LOWER(p.email)=LOWER($1) AND t.durum='TAMAMLANDI' AND ${yemekHaricAvans("t")}`,
        [queryEmail]
      );
      const bakiyeFallbackRes = await pool.query(
        `SELECT COALESCE(SUM(t.tutar),0) as toplam FROM is_avans_talep t
         WHERE LOWER(t.talep_eden_email)=LOWER($1) AND t.durum='TAMAMLANDI'
         AND t.personel_id IS NULL AND ${yemekHaricAvans("t")}`,
        [queryEmail]
      );
      avansToplamOnaylanan = Number(bakiyeAvansRes.rows[0].toplam) + Number(bakiyeFallbackRes.rows[0].toplam);
    }
    const bakiyeMasrafRes = await pool.query(
      `SELECT COALESCE(SUM(mk.tutar),0) as toplam FROM masraf_kalem mk
       JOIN masraf_form mf ON mf.id = mk.form_id
       WHERE LOWER(mf.talep_eden_email)=LOWER($1) AND mf.durum='ARSIVLENDI'
       AND ${yemekHaricKalem("mk", "mf")}`,
      [queryEmail]
    );
    const masrafToplamArsiv    = Number(bakiyeMasrafRes.rows[0].toplam);
    // Personel ödemeleri (masraf alacağı ödemesi + / avans iadesi −) — web bakiyesiyle aynı kural
    let personelOdemeNet = 0;
    try {
      const po = await pool.query(
        `SELECT COALESCE(SUM(CASE WHEN tip='MASRAF_ODEME' THEN tutar ELSE -tutar END),0) AS net
         FROM personel_odeme o LEFT JOIN personel p ON p.id=o.personel_id
         WHERE LOWER(COALESCE(o.email,''))=LOWER($1) OR LOWER(COALESCE(p.email,''))=LOWER($1)`, [queryEmail]);
      personelOdemeNet = Number(po.rows[0].net || 0);
    } catch {}
    const avansKalan           = avansToplamOnaylanan + personelOdemeNet - masrafToplamArsiv;

    // 7. Bekleyen masraf toplam tutarı (sadece onaya gönderilmiş formlar — TASLAK hariç)
    const ONAY_DURUMLAR = ['ROLLOUT_BEKLE','MUHASEBE_BEKLE','PM_BEKLE','DIREKTOR_BEKLE'];
    const bekleyenMasrafTutar = masraflar
      .filter(f => ONAY_DURUMLAR.includes(f.durum))
      .reduce((s, f) => s + Number(f.toplam_tutar || 0), 0);

    // 8. Taslak masraf toplam tutarı (ayrıca gönder)
    const taslakMasrafTutar = masraflar
      .filter(f => f.durum === 'TASLAK')
      .reduce((s, f) => s + Number(f.toplam_tutar || 0), 0);
    const taslakMasrafCount = masraflar.filter(f => f.durum === 'TASLAK').length;

    // Bekleyen sayısını da sadece onaya gönderilmişlerle sınırla
    const bekleyenMasrafCount = masraflar.filter(f => ONAY_DURUMLAR.includes(f.durum)).length;

    // 9. Kullanıcının rolüne göre onay bekleyen iş avansları
    //    PM  → durum='TALEP' olanlar
    //    Direktör → TALEP + ROLLOUT_MUDUR_ONAY + PM_ONAY olanlar (direktor-onayla hepsini kabul eder)
    //    PM      → TALEP + ROLLOUT_MUDUR_ONAY olanlar (pm-onayla hepsini kabul eder)
    const PM_EMAIL_CONST       = 'orhan.bedir@simsektel.com';
    const DIREKTOR_EMAIL_CONST = 'duzgun.simsek@simsektel.com';
    const userEmailLower = (queryEmail || '').toLowerCase().trim();
    const isPM       = userEmailLower === PM_EMAIL_CONST.toLowerCase();
    // 25.10.2026: direktör bayrağı tarihli onay devriyle de açılır (devralan kullanıcı; req.devirler oturumdan)
    const isDirektor = userEmailLower === DIREKTOR_EMAIL_CONST.toLowerCase() || devirOnaycisi(req, "AVANS_PD");
    // Rollout Müdürü aşaması (03.09.2026, Orhan): Nurcan/Serdar/Murat İstek mobilde
    // TALEP durumundaki avansları görüp onaylar (web ile aynı; /onayla TALEP→ROLLOUT_MUDUR_ONAY)
    const isRM = !isPM && !isDirektor && (AVANS_YETKI.RM || []).includes(userEmailLower);
    // Başkası adına avans talebi (web'deki Personel seçimi) — RM/PM/PD/muhasebe
    const avansBaskasiIcin = isPM || isDirektor || isRM || (AVANS_YETKI.ODE || []).includes(userEmailLower);

    let onayBekleyenAvanslar = [];
    if (isPM || isDirektor || isRM) {
      const bekleyenDurumlar = isDirektor
        ? ['TALEP', 'ROLLOUT_MUDUR_ONAY', 'PM_ONAY']
        : isPM ? ['TALEP', 'ROLLOUT_MUDUR_ONAY'] : ['TALEP'];
      // 22.08.2026 (Orhan): onay ekranında "kim için / not / plaka / KM / firma"
      // görünmüyordu. Alanlar ayrı gönderilir (yeni mobil build satır satır
      // gösterir); mevcut build için aciklama metnine de özet eklenir
      // (aciklama_ham = kullanıcının yazdığı orijinal metin).
      // 25.10.2026: satırlar firmaya ve tarihli onay devrine göre süzülür (onayDevri.avansBekleyenler): devredilmiş firmanın
      // direktör adımı eski direktörün listesinden düşer, devralanın listesine girer. Eski alanlar korunur (+ adim / uc / talep_firma).
      const onayRes = { rows: (await onayPanel.avansBekleyenler({ user: { ..._u, email: userEmailLower }, devirler: req.devirler || [] })).rows
        .filter(r => bekleyenDurumlar.includes(r.durum)).slice(0, 20) };
      onayBekleyenAvanslar = onayRes.rows.map(r => {
        const parca = [];
        if (r.personel_ad) parca.push(`Kim için: ${r.personel_ad}${r.personel_unvan ? ` (${r.personel_unvan})` : ""}`);
        if (r.firma) parca.push(`Firma: ${r.firma}`);
        if (r.not_aciklama) parca.push(`Not: ${r.not_aciklama}`);
        if (r.plaka) parca.push(`Plaka: ${r.plaka}`);
        if (r.arac_km != null && r.arac_km !== "") parca.push(`Araç KM: ${Number(r.arac_km).toLocaleString("tr-TR")}`);
        const ham = r.aciklama || "";
        const ozet = parca.join("\n");
        return { ...r, aciklama_ham: ham, aciklama: [ham, ozet].filter(Boolean).join("\n— — —\n") };
      });
    }

    // 10. PM için onay bekleyen malzeme talepleri (durum='PM_ONAY')
    let onayBekleyenMalzemeler = [];
    if (isPM) {
      const malzRes = await pool.query(
        `SELECT t.id, t.talep_no, t.talep_eden_ad, t.talep_eden_email,
                t.durum, t.bolge, t.proje, t.site_id, t.notlar, t.created_at,
                COALESCE((SELECT COUNT(*) FROM malzeme_talep_kalemleri k WHERE k.talep_id=t.id),0)::int AS kalem_sayisi
         FROM malzeme_talepler t
         WHERE t.durum = 'PM_ONAY'
         ORDER BY t.created_at ASC
         LIMIT 20`
      );
      onayBekleyenMalzemeler = malzRes.rows;
    }

    res.json({
      personel, personelBulundu: !!personelId, ay, yil,
      puantaj,
      avanslar, bekleyenAvans,
      masraflar, bekleyenMasraf: bekleyenMasrafCount, bekleyenMasrafTutar,
      taslakMasrafTutar, taslakMasrafCount,
      cezalar, toplamCeza, cezaKalemler,
      avansKalan, avansToplamOnaylanan,
      onayBekleyenAvanslar, isPM, isDirektor, isRM, avansBaskasiIcin,
      onayBekleyenMalzemeler,
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.get("/hr/masraf-formlari", async (req, res) => {
  try {
    const u = optionalAuth(req);
    if (!u) return res.status(401).json({ error: "Oturum gerekli" });
    // 25.10.2026 (gizlilik): tam görüş değilse ?email= yok sayılır, yalnız kendi (talep ettiği / adına açılan) formlar
    const tam = masrafTamVeyaOnayci(u, req);
    const email = tam ? req.query.email : null;
    const k = altMarkaKapsam(req);
    const conds = []; const params = [];
    if (email) { conds.push(`mf.talep_eden_email = $1`); params.push(email); }
    if (!tam) {
      params.push(_eposta(u));
      conds.push(`$${params.length} <> '' AND (LOWER(TRIM(COALESCE(mf.talep_eden_email,''))) = $${params.length} OR LOWER(TRIM(COALESCE(p.email,''))) = $${params.length})`);
    }
    if (k) conds.push(kapsamPersonelSql(k));
    const whereClause = conds.length ? `WHERE ${conds.join(" AND ")}` : '';
    const kalemKosul = k ? ` FILTER (WHERE ${kapsamKalemSql(k)})` : "";
    const { rows } = await pool.query(`
      SELECT mf.id, mf.durum, mf.created_at, mf.donem, mf.form_no,
        mf.talep_eden_email, mf.talep_eden_ad, mf.red_aciklama, mf.reddeden_email,
        COALESCE(SUM(mk.tutar)${kalemKosul},0) as toplam_tutar,
        COUNT(mk.id)${kalemKosul}::int as kalem_sayisi
      FROM masraf_form mf
      LEFT JOIN personel p ON p.id = mf.personel_id
      LEFT JOIN masraf_kalem mk ON mk.form_id = mf.id
      ${whereClause}
      GROUP BY mf.id
      ${k ? `HAVING COUNT(mk.id)${kalemKosul} > 0` : ""}
      ORDER BY mf.created_at DESC
    `, params);
    res.json(rows);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET personel masraf bakiye — MUST be before /:id to avoid "bakiye" being matched as an id
app.get("/hr/masraf-form/bakiye/:personelId", async (req, res) => {
  try {
    // 11.08.2026: Bu uç eskiden İK'daki `avans` tablosunu (maaş avansı kalıntısı)
    // ve TAMAMLANDI masrafları okuyordu — panel/mobil ile farklı rakam veriyordu.
    // Artık tek kaynak: onaylanmış iş avansı talepleri − ARŞİVLENEN masraf.
    const pid = req.params.personelId;
    // 25.10.2026 (gizlilik): personel kimliği değiştirilerek başkasının bakiyesi okunuyordu
    const u = optionalAuth(req);
    if (!u) return res.status(401).json({ error: "Oturum gerekli" });
    if (_sayiId(pid) === null) return res.status(400).json({ error: "Geçersiz personel" });
    if (!masrafTamVeyaOnayci(u, req)) {
      const kp = await kendiPersonelKaydi(u);
      if (!kp || String(kp.id) !== String(pid)) return res.status(403).json({ error: "Yalnız kendi bakiyenizi görebilirsiniz" });
    }
    const per = await pool.query(`SELECT LOWER(TRIM(email)) AS email FROM personel WHERE id=$1`, [pid]);
    const email = per.rows[0]?.email || "";
    if (email === PM_KISISEL_EMAIL && !pmKisiselEmailGorur(u.email, u.role))
      return res.status(403).json({ error: "Bu bakiyeyi görme yetkiniz yok" });
    const avansRes = await pool.query(
      `SELECT COALESCE(SUM(tutar),0) AS toplam FROM is_avans_talep
       WHERE durum='TAMAMLANDI' AND personel_id=$1`, [pid]);
    // Personele bağlanmamış eski kayıtlar talep edenin e-postasından yakalanır
    const avansFallback = email ? await pool.query(
      `SELECT COALESCE(SUM(tutar),0) AS toplam FROM is_avans_talep
       WHERE durum='TAMAMLANDI' AND personel_id IS NULL AND LOWER(talep_eden_email)=$1`, [email])
      : { rows: [{ toplam: 0 }] };
    const masrafRes = email ? await pool.query(
      `SELECT COALESCE(SUM(mk.tutar),0) AS toplam FROM masraf_kalem mk
       JOIN masraf_form mf ON mf.id = mk.form_id
       WHERE mf.durum='ARSIVLENDI'
         AND (mf.personel_id=$1 OR (mf.personel_id IS NULL AND LOWER(mf.talep_eden_email)=$2))`,
      [pid, email])
      : { rows: [{ toplam: 0 }] };
    const avans = Number(avansRes.rows[0].toplam) + Number(avansFallback.rows[0].toplam);
    const masraf = Number(masrafRes.rows[0].toplam);
    res.json({ avans, masraf, bakiye: avans - masraf });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

