    const b = await pool.query(`SELECT DISTINCT project AS proje FROM master_works WHERE COALESCE(project,'') <> '' ORDER BY 1 LIMIT 200`).catch(() => ({ rows: [] }));
    const set = new Set([...a.rows, ...b.rows].map(r => r.proje).filter(Boolean));
