// 28.10.2026: ekip kayıtlarını yalnız organizasyon yönetim izni (org_yonet) olan değiştirir; alt marka yalnız kendi ekibini
app.post("/hr/ekipler", orgPanel.yonetKapisi, async (req, res) => {
  try {
    const no = Number(req.body.ekip_no || 0);
    if (!no || no < 1) return res.status(400).json({ error: "Geçerli ekip no gerekli" });
    const _once = (await pool.query(`SELECT * FROM ekipler WHERE ekip_no=$1`, [no])).rows[0] || null;
    if (_once && !orgPanel.ekipKapsamda(req, _once)) return res.status(403).json({ error: "Bu ekip firmanızın kapsamında değil" });
    if (!_once && orgPanel.orgYetki(req).marka) return res.status(403).json({ error: "Yeni ekip Organizasyon Şeması'ndaki \"+ Ekip Ekle\" ile açılır" });
    // aktif gönderilmediyse mevcut değer korunur; sablon_kodu bu uçtan değiştirilmez
    const aktif = typeof req.body.aktif === "boolean" ? req.body.aktif : null;
    // TEKNO ekibi: ad boşsa sıradaki numara verilir (TEKNO EkipN); TEKNO adları benzersiz
    let ad = String(req.body.ad || "").trim() || null;
    const mevcut = (await pool.query(`SELECT ekip_sira, ad FROM ekipler WHERE ekip_no=$1`, [no])).rows[0];
    let yeniSira = null;
    if (TEKNO_FIRMA_MI(req.body.taseron_adi) && !ad && !mevcut?.ekip_sira) {
      const nx = (await pool.query(`SELECT COALESCE(MAX(ekip_sira),0)+1 AS n FROM ekipler`)).rows[0].n;
      ad = `TEKNO Ekip${nx}`; yeniSira = nx;
    }
    if (ad && /^TEKNO\b/i.test(ad)) {
      const ayni = await pool.query(`SELECT ekip_no FROM ekipler WHERE ekip_no<>$1 AND LOWER(TRIM(ad))=LOWER($2)`, [no, ad]);
      if (ayni.rows.length) return res.status(409).json({ error: `"${ad}" adı Ekip ${ayni.rows[0].ekip_no} tarafından kullanılıyor — TEKNO ekip adları benzersizdir` });
    }
    if (yeniSira) await pool.query(`UPDATE ekipler SET ekip_sira=$2 WHERE ekip_no=$1`, [no, yeniSira]).catch(() => {});
    // Ekip türü / bağlı firma / iş etiketleri: alan gönderilmediyse mevcut değer korunur
    const turGeldi = Object.prototype.hasOwnProperty.call(req.body, "ekip_turu");
    const firmaGeldi = Object.prototype.hasOwnProperty.call(req.body, "bagli_firma");
    const etiketGeldi = Object.prototype.hasOwnProperty.call(req.body, "is_etiketleri");
    const eskiTur = (await pool.query(`SELECT ekip_turu, bagli_firma, is_etiketleri FROM ekipler WHERE ekip_no=$1`, [no])).rows[0] || {};
    let tur = turGeldi ? (["IC", "DIS"].includes(String(req.body.ekip_turu || "").toUpperCase()) ? String(req.body.ekip_turu).toUpperCase() : null) : (eskiTur.ekip_turu || null);
    let bagli = firmaGeldi ? (String(req.body.bagli_firma || "").trim().toUpperCase() || null) : (eskiTur.bagli_firma || null);
    let etiketler = etiketGeldi
      ? [...new Set((Array.isArray(req.body.is_etiketleri) ? req.body.is_etiketleri : String(req.body.is_etiketleri || "").split(/[,;\n]/))
          .map(x => String(x || "").trim().toUpperCase()).filter(Boolean))]
      : (eskiTur.is_etiketleri || []);
    if (tur === "IC" && !bagli) return res.status(400).json({ error: "Kendi ekibimiz seçildiğinde bağlı firma zorunlu" });
    if (bagli && !(bagli === "ERC" || ALT_MARKALAR.some(m => m.kod === bagli))) return res.status(400).json({ error: `Geçersiz bağlı firma: ${bagli}` });
    if (etiketler.length) {
      const cak = await pool.query(`SELECT ekip_no, ad, t FROM ekipler, unnest(COALESCE(is_etiketleri,'{}')) t WHERE ekip_no<>$1 AND UPPER(t) = ANY($2::text[]) LIMIT 1`, [no, etiketler]);
      if (cak.rows.length) return res.status(409).json({ error: `"${cak.rows[0].t}" iş etiketi ${cak.rows[0].ad || "Ekip " + cak.rows[0].ekip_no} ekibinde kayıtlı — bir etiket tek ekibe ait olabilir` });
    }
    const r = await pool.query(
      `INSERT INTO ekipler (ekip_no, plaka, bolge, aciklama, ad, taseron_adi, aktif)
       VALUES ($1,$2,$3,$4,$5,$6,COALESCE($7,true))
       ON CONFLICT (ekip_no) DO UPDATE SET plaka=$2, bolge=$3, aciklama=$4, ad=$5, taseron_adi=$6,
         aktif=COALESCE($7, ekipler.aktif), updated_at=NOW()
       RETURNING *`,
      [no, req.body.plaka || null, req.body.bolge || null, req.body.aciklama || null, ad,
       (req.body.taseron_adi || "").trim() || null, aktif]);
    if (yeniSira && !r.rows[0].ekip_sira) { await pool.query(`UPDATE ekipler SET ekip_sira=$2 WHERE ekip_no=$1`, [no, yeniSira]).catch(() => {}); r.rows[0].ekip_sira = yeniSira; }
    // 28.10.2026: ad / bölge / plaka / taşeron adı / durum değişiklikleri de geçmişe yazılır
    const _oz = (e) => e ? { ad: e.ad || null, bolge: e.bolge || null, plaka: e.plaka || null, taseron_adi: e.taseron_adi || null, durum: e.aktif === false ? "Pasif" : "Aktif" } : null;
    if (JSON.stringify(_oz(_once)) !== JSON.stringify(_oz(r.rows[0])))
      await islemGecmisiYaz(req, "ekip", no, _once ? "DUZENLEME" : "OLUSTURMA", _oz(_once), _oz(r.rows[0]), String(req.body.gerekce || "").trim() || null);
    const eskiOz = { ekip_turu: eskiTur.ekip_turu || null, bagli_firma: eskiTur.bagli_firma || null, is_etiketi: (eskiTur.is_etiketleri || []).join(", ") || null };
    const yeniOz = { ekip_turu: tur, bagli_firma: bagli, is_etiketi: etiketler.join(", ") || null };
    if (JSON.stringify(eskiOz) !== JSON.stringify(yeniOz)) {
      const u2 = await pool.query(`UPDATE ekipler SET ekip_turu=$2, bagli_firma=$3, is_etiketleri=$4, updated_at=NOW() WHERE ekip_no=$1 RETURNING ekip_turu, bagli_firma, is_etiketleri`, [no, tur, bagli, etiketler]);
      Object.assign(r.rows[0], u2.rows[0] || {});
      await islemGecmisiYaz(req, "ekip", no, "SINIFLANDIRMA", eskiOz, yeniOz, null);
    }
    res.json(r.rows[0]);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// 28.10.2026: silme ayrı izindir (org_sil) ve yalnız hiç kullanılmamış ekipte yapılır; kullanılmış ekip pasife alınır.
// Eskiden silinen ekibin personel bağları sessizce temizleniyordu — artık personel / geçmiş kaydına dokunulmaz.
app.delete("/hr/ekipler/:no", orgPanel.silKapisi, async (req, res) => {
  try {
    const no = Number(req.params.no);
    const e = (await pool.query(`SELECT * FROM ekipler WHERE ekip_no=$1`, [no])).rows[0];
    if (!e) return res.status(404).json({ error: "Ekip bulunamadı" });
    if (!orgPanel.ekipKapsamda(req, e)) return res.status(403).json({ error: "Bu ekip firmanızın kapsamında değil" });
    if (await orgPanel.ekipKullanimi(no)) return res.status(409).json({ error: "Ekip kullanılmış (personel, üyelik geçmişi ya da iş kaydı var) — silinemez, pasife alın" });
    await islemGecmisiYaz(req, "ekip", no, "SILME", { ad: e.ad, bolge: e.bolge }, null, "Hatalı kayıt");
    await pool.query(`DELETE FROM ekipler WHERE ekip_no=$1`, [no]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

/* Ekip şablonları (12.10.2026, Orhan): 9 personelsiz şablon — İzmir 4, Ankara 2, Bursa 3.
   sablon_kodu ile tekil: tekrar çalıştırmak mükerrer üretmez (var olan şablon ad/firma/bölge olarak güncellenir,
   personeli korunur). Eski ekipler SİLİNMEZ; eskileri_pasifle=true ise aktif=false yapılır — personel.ekip_bilgisi
   bağları ve geçmiş işler durur. Personel yeni şablonlara otomatik TAŞINMAZ (Ekip Yönetimi'nden elle atanır).
   TEK tek firmadır; her bölgedeki ekipleri ayrı kayıttır (ANK-TEK-RF-1 ≠ BUR-TEK-RF-1). */
const EKIP_SABLONLARI = [
  { kod: "IZM-FERRUMX-1",      ad: "Ekip 1",      taseron: "Ferrumx",      bolge: "İzmir"  },
  { kod: "IZM-FERRUMX-2",      ad: "Ekip 2",      taseron: "Ferrumx",      bolge: "İzmir"  },
  { kod: "IZM-TEK-RF-1",       ad: "TEKNO Ekip1", sira: 1, taseron: "TEK", bolge: "İzmir"  },
  { kod: "IZM-AKCAN-1",        ad: "Ekip 1",      taseron: "Akçan",        bolge: "İzmir"  },
  { kod: "ANK-TEK-RF-1",       ad: "TEKNO Ekip2", sira: 2, taseron: "TEK", bolge: "Ankara" },
  { kod: "ANK-TEK-RF-2",       ad: "TEKNO Ekip3", sira: 3, taseron: "TEK", bolge: "Ankara" },
  { kod: "BUR-TEK-RF-1",       ad: "TEKNO Ekip4", sira: 4, taseron: "TEK", bolge: "Bursa"  },
  { kod: "BUR-TEK-RF-2",       ad: "TEKNO Ekip5", sira: 5, taseron: "TEK", bolge: "Bursa"  },
  { kod: "BUR-NETWORKGROUP-1", ad: "Ekip 1",      taseron: "Networkgroup", bolge: "Bursa"  },
];
// 28.10.2026: yetki e-posta listesinden (ORG_DUZENLEYICI) org_yonet iznine taşındı (users.yetki_ayar / ERC admin rolü)
app.post("/hr/ekipler/sablon-kur", orgPanel.yonetKapisi, async (req, res) => {
  try {
    if (orgPanel.orgYetki(req).marka) return res.status(403).json({ ok: false, error: "Ekip şablonu kurma yetkiniz yok" });
    const eskileriPasifle = !!(req.body && req.body.eskileri_pasifle);
    let eklenen = 0, guncellenen = 0, pasiflenen = 0;
    for (const s of EKIP_SABLONLARI) {
      const mevcut = await pool.query(`SELECT ekip_no FROM ekipler WHERE sablon_kodu = $1`, [s.kod]);
      if (mevcut.rows.length) {
        // 16.10.2026: var olan ekibin ADI ve BÖLGESİ kullanıcıya aittir — kurulum ezmez.
        // 28.10.2026: DURUMU da kullanıcıya aittir — pasife alınmış şablon ekip kurulumla yeniden aktifleşmez.
        guncellenen++;
      } else {
        const nx = await pool.query(`SELECT COALESCE(MAX(ekip_no), 0) + 1 AS n FROM ekipler`);
        const siraBos = s.sira ? !(await pool.query(`SELECT 1 FROM ekipler WHERE ekip_sira=$1`, [s.sira])).rows.length : false;
        await pool.query(`INSERT INTO ekipler (ekip_no, ad, taseron_adi, bolge, aktif, sablon_kodu, ekip_sira) VALUES ($1,$2,$3,$4,true,$5,$6)`,
          [nx.rows[0].n, siraBos || !s.sira ? s.ad : null, s.taseron, s.bolge, s.kod, siraBos ? s.sira : null]);
        eklenen++;
      }
    }
    if (eskileriPasifle) {
      const r = await pool.query(
        `UPDATE ekipler SET aktif=false, updated_at=NOW()
          WHERE aktif IS DISTINCT FROM false AND (sablon_kodu IS NULL OR NOT (sablon_kodu = ANY($1::text[]))) RETURNING ekip_no`,
        [EKIP_SABLONLARI.map((s) => s.kod)]);
      pasiflenen = r.rowCount;
      for (const x of r.rows) await islemGecmisiYaz(req, "ekip", x.ekip_no, "DURUM", { durum: "Aktif" }, { durum: "Pasif" }, "Şablon kurulumu: şablon dışı ekip pasife alındı");
    }
    res.json({ ok: true, eklenen, guncellenen, pasiflenen, toplam_sablon: EKIP_SABLONLARI.length });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// Personel → ekip ataması (yalnız ekip_bilgisi alanını günceller)
app.put("/hr/personel/:id/ekip", authMiddleware, async (req, res) => {
  try {
    // 28.10.2026: ekip üyeliği değişikliği org_yonet ister (geçmişe yazılır); yalnız araç ataması İK yazma yetkilisine de açık
    const _org = orgPanel.orgYetki(req);
    if ("ekip_bilgisi" in req.body ? !_org.yonet : !(_org.yonet || ikYazmaYetkili(req.user || {})))
      return res.status(403).json({ ok: false, error: "Ekip ataması değiştirme yetkiniz yok" });
    if ("ekip_bilgisi" in req.body && String(req.body.ekip_bilgisi ?? "").trim()) {
      const _hedef = (await pool.query(`SELECT * FROM ekipler WHERE ekip_no::text=$1`, [String(req.body.ekip_bilgisi).trim()])).rows[0];
      if (!_hedef) return res.status(404).json({ error: "Ekip bulunamadı" });
      if (!orgPanel.ekipKapsamda(req, _hedef)) return res.status(403).json({ error: "Bu ekip firmanızın kapsamında değil" });
      if (_hedef.aktif === false) return res.status(409).json({ error: "Ekip pasif — pasif ekibe personel eklenemez" });
    }
    const _ekipOnce = (await pool.query(`SELECT ekip_bilgisi FROM personel WHERE id=$1`, [req.params.id])).rows[0]?.ekip_bilgisi || null;
    const sets = [], vals = [req.params.id];
    if ("ekip_bilgisi" in req.body) {
      const v = req.body.ekip_bilgisi;
      vals.push(v === null || v === undefined || v === "" ? null : String(v));
      sets.push(`ekip_bilgisi=$${vals.length}`);
      // Ekipten çıkarılınca araç ataması da temizlenir
      if (v === null || v === undefined || v === "") sets.push(`ekip_arac_plaka=NULL`);
    }
    if ("ekip_arac_plaka" in req.body) {
      const a = req.body.ekip_arac_plaka;
      const plk = a === null || a === undefined || a === "" ? null : String(a).trim().toUpperCase().replace(/\s+/g, "");
      // 16.10.2026: yeni araç ataması yalnız AKTİF araca yapılır (pasif/serviste/silinmiş reddedilir); alt marka
      // kullanıcısı yalnız kendi firma kapsamındaki aracı atayabilir. Mevcut atamanın aynısı tekrar gelirse dokunulmaz.
      if (plk) {
        const cur = (await pool.query(`SELECT ekip_arac_plaka FROM personel WHERE id=$1`, [req.params.id])).rows[0];
        if (String(cur?.ekip_arac_plaka || "").toUpperCase() !== plk) {
          const ar = (await pool.query(`SELECT plaka, durum, aktif, firma FROM araclar WHERE UPPER(REPLACE(plaka,' ',''))=$1`, [plk])).rows[0];
          if (!ar) return res.status(409).json({ error: `${plk} araç kaydı bulunamadı — listeyi yenileyin`, yenile: true });
          if (ar.durum !== "AKTİF" || ar.aktif === false)
            return res.status(409).json({ error: `${plk} artık aktif değil (${ar.durum || "pasif"}) — aktif bir araç seçin ya da "Araç yok" bırakın`, yenile: true });
          const k = altMarkaKapsam(req);
          if (k && !k.bordro.map((x) => String(x).toUpperCase()).includes(String(ar.firma || "AHY").toUpperCase()))
            return res.status(403).json({ error: `${plk} firmanızın kapsamında değil` });
        }
      }
      vals.push(plk);
      sets.push(`ekip_arac_plaka=$${vals.length}`);
    }
    if (!sets.length) return res.status(400).json({ error: "Güncellenecek alan yok" });
    const onceQ = await pool.query(`SELECT ad_soyad, ekip_arac_plaka FROM personel WHERE id=$1`, [req.params.id]);
    const once = onceQ.rows[0] || {};
    const r = await pool.query(
      `UPDATE personel SET ${sets.join(", ")} WHERE id=$1 RETURNING id, ad_soyad, ekip_bilgisi, ekip_arac_plaka`,
      vals);
    if (!r.rows.length) return res.status(404).json({ error: "Personel bulunamadı" });
    const yeni = r.rows[0];
    if ("ekip_bilgisi" in req.body) await orgPanel.uyelikSenkron(req, yeni.id, _ekipOnce, yeni.ekip_bilgisi, { gerekce: String(req.body.gerekce || "").trim() || "Ekip ataması" });
    // ── Araç Yönetimi senkronu: org şemasındaki atama araç kartına yansır ──
    // Atanan aracın sürücüsü = üye, bölgesi = ekibin bölgesi; atama
    // kaldırılınca/değişince eski aracın sürücüsü temizlenir.
    try {
      if (once.ekip_arac_plaka && once.ekip_arac_plaka !== yeni.ekip_arac_plaka) {
        await pool.query(`UPDATE araclar SET surucu=NULL WHERE plaka=$1 AND surucu=$2`,
          [once.ekip_arac_plaka, once.ad_soyad]);
      }
      if (yeni.ekip_arac_plaka) {
        const ek = await pool.query(`SELECT bolge FROM ekipler WHERE ekip_no::text = $1 LIMIT 1`,
          [String(yeni.ekip_bilgisi || "")]).catch(() => ({ rows: [] }));
        await pool.query(`UPDATE araclar SET surucu=$2, bolge=COALESCE(NULLIF($3,''), bolge) WHERE plaka=$1`,
          [yeni.ekip_arac_plaka, yeni.ad_soyad, ek.rows[0]?.bolge || ""]);
      }
    } catch (se) { console.error("ARAC SENKRON:", se.message); }
    res.json(yeni);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

