// GET dönem bazlı toplu Excel (Muhasebe için)
app.get("/hr/masraf-form/donem/:donem/excel", async (req, res) => {
  try {
    const u = optionalAuth(req);
    if (!u) return res.status(401).json({ error: "Oturum gerekli" });
    if (!masrafTamVeyaOnayci(u, req)) return res.status(403).json({ error: "Dönem masraf dökümünü görme yetkiniz yok" });
    const { donem } = req.params;
    const k = altMarkaKapsam(req);
    const formsRes = await pool.query(`
      SELECT mf.*, p.ad_soyad as personel_ad FROM masraf_form mf
      LEFT JOIN personel p ON p.id = mf.personel_id
      WHERE mf.donem=$1 AND mf.durum IN ('TAMAMLANDI','ARSIVLENDI')
      ${k ? `AND ${kapsamPersonelSql(k)} AND EXISTS (SELECT 1 FROM masraf_kalem mk WHERE mk.form_id = mf.id AND ${kapsamKalemSql(k)})` : ""}
      ORDER BY mf.talep_eden_ad, mf.id`, [donem]);
    const forms = formsRes.rows;

    const ExcelJS = require("exceljs");
    const wb = new ExcelJS.Workbook();

    if (forms.length === 0) {
      const ws = wb.addWorksheet("Boş");
      ws.getCell("A1").value = `${donem} döneminde onaylanmış masraf formu yok.`;
    }

    for (const form of forms) {
      const kalemler = await pool.query(
        `SELECT * FROM masraf_kalem mk WHERE form_id=$1 ${k ? `AND ${kapsamKalemSql(k)}` : ""} ORDER BY tarih,id`, [form.id]
      );
      const rows = kalemler.rows;
      const sheetName = `${form.talep_eden_ad.slice(0,15)}_${form.id}`.replace(/[\\/*?:\[\]]/g,"");
      const ws = wb.addWorksheet(sheetName);

      ws.columns = [
        { width: 3 }, { width: 13 }, { width: 12 }, { width: 30 }, { width: 38 }, { width: 5 }, { width: 16 }
      ];

      const navy = "FF1E3A5F", white = "FFFFFFFF", headerBlue = "FF2563EB";
      const boldWhite = { bold: true, color: { argb: white }, name: "Arial", size: 11 };
      const boldNavy = { bold: true, color: { argb: navy }, name: "Arial", size: 10 };
      const thinLine2 = { style: "thin", color: { argb: "FFB0B8C1" } };
      const cellBorder2 = { top: thinLine2, left: thinLine2, bottom: thinLine2, right: thinLine2 };

      const mergeAndStyle = (r, c1, c2, val, fill, font, align = "center") => {
        if (c1 !== c2) ws.mergeCells(r, c1, r, c2);
        const cell = ws.getCell(r, c1);
        cell.value = val;
        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: fill || white } };
        if (font) cell.font = font;
        cell.alignment = { horizontal: align, vertical: "middle", wrapText: true };
        cell.border = cellBorder2;
      };

      const applyBorder2 = (r, cols) => {
        cols.forEach(c => {
          ws.getCell(r, c).border = cellBorder2;
          ws.getCell(r, c).fill = { type: "pattern", pattern: "solid", fgColor: { argb: white } };
        });
      };

      ws.addRow([]); ws.getRow(1).height = 30;
      mergeAndStyle(1, 2, 5, "MASRAF FORMU", navy, { bold: true, color: { argb: white }, name: "Arial", size: 14 });
      mergeAndStyle(1, 7, 7, `Doküman Kodu: MF.${String(form.form_no || form.id).padStart(3,"0")}`, null, boldNavy, "right");
      ws.addRow([]); ws.getRow(2).height = 18;
      mergeAndStyle(2, 2, 5, `Dönem: ${form.donem}`, null, boldNavy, "left");
      mergeAndStyle(2, 7, 7, `Oluşturma: ${new Date(form.created_at).toLocaleDateString("tr-TR")}`, null, { name:"Arial", size:9, italic:true }, "right");
      ws.addRow([]); ws.getRow(3).height = 18;
      mergeAndStyle(3, 2, 5, `Personel: ${formatAd(form.personel_ad || form.talep_eden_ad)}`, null, boldNavy, "left");

      const KATS = [
        { key:"YEMEK", label:"YİYECEK VE İÇECEK GİDERLERİ", aciklamaLabel:"AÇIKLAMA (PROJE VEYA İŞ ADI)" },
        { key:"YAKIT", label:"ARAÇ YAKIT VE BAKIM GİDERLERİ", aciklamaLabel:"AÇIKLAMA (ARAÇ PLAKA NO)" },
        { key:"KONAKLAMA", label:"KONAKLAMA GİDERLERİ", aciklamaLabel:"AÇIKLAMA (KAÇ GECE, KİŞİ SAYISI)" },
        { key:"ULASIM", label:"ULAŞIM GİDERLERİ", aciklamaLabel:"AÇIKLAMA (BİNİŞ SAATİ, GÜZERGAH)" },
        { key:"KOPRU", label:"KÖPRÜ / OTOYOL GEÇİŞ GİDERLERİ", aciklamaLabel:"AÇIKLAMA (GEÇİŞ DETAYI)" },
        { key:"MALZEME", label:"MALZEME GİDERLERİ", aciklamaLabel:"AÇIKLAMA (MALZEME DETAYI)" },
        { key:"DIGER", label:"DİĞER GİDERLER", aciklamaLabel:"AÇIKLAMA (İŞİN DETAYI)" },
      ];

      let currentRow = 4;
      const totals = {};

      for (const kat of KATS) {
        const katRows = rows.filter(r => r.kategori === kat.key);
        totals[kat.key] = katRows.reduce((s, r) => s + Number(r.tutar), 0);

        ws.getRow(currentRow).height = 20;
        mergeAndStyle(currentRow, 2, 7, kat.label, headerBlue, boldWhite);
        currentRow++;

        ws.getRow(currentRow).height = 16;
        ["TARİH","BELGE NO","BELGE AÇIKLAMASI",kat.aciklamaLabel,"","MASRAF TUTARI"].forEach((h,i)=>{
          const col = [2,3,4,5,6,7][i];
          const cell = ws.getCell(currentRow, col);
          cell.value = h;
          cell.fill = { type:"pattern", pattern:"solid", fgColor:{ argb:"FFD1D5DB" } };
          cell.font = { bold:true, name:"Arial", size:9 };
          cell.alignment = { horizontal:"center", vertical:"middle" };
          cell.border = cellBorder2;
        });
        currentRow++;

        if (katRows.length === 0) {
          ws.mergeCells(currentRow, 2, currentRow, 6);
          ws.getCell(currentRow, 2).value = "—";
          ws.getCell(currentRow, 2).alignment = { horizontal:"center" };
          ws.getCell(currentRow, 7).value = 0;
          ws.getCell(currentRow, 7).numFmt = "#,##0.00 ₺";
          applyBorder2(currentRow, [2, 7]);
          currentRow++;
        } else {
          for (const kalem of katRows) {
            ws.getRow(currentRow).height = 16;
            ws.getCell(currentRow,2).value = kalem.tarih ? new Date(kalem.tarih).toLocaleDateString("tr-TR") : "";
            ws.getCell(currentRow,3).value = kalem.belge_no||"";
            ws.getCell(currentRow,4).value = kalem.belge_aciklama||"";
            ws.mergeCells(currentRow, 5, currentRow, 6);
            ws.getCell(currentRow,5).value = kalem.aciklama||"";
            ws.getCell(currentRow,5).alignment = { wrapText:true };
            ws.getCell(currentRow,7).value = Number(kalem.tutar);
            ws.getCell(currentRow,7).numFmt = "#,##0.00 ₺";
            ws.getCell(currentRow,7).alignment = { horizontal:"right" };
            if (!kalem.fis_var) ws.getCell(currentRow,2).font = { color:{ argb:"FFDC2626" }, italic:true, name:"Arial", size:9 };
            [2,3,4,5,7].forEach(c => {
              ws.getCell(currentRow,c).border = cellBorder2;
              ws.getCell(currentRow,c).fill = { type:"pattern", pattern:"solid", fgColor:{ argb:white } };
            });
            currentRow++;
          }
        }

        ws.getRow(currentRow).height = 18;
        mergeAndStyle(currentRow, 2, 6, `${kat.label.split(" GİDERLER")[0]} Toplamı`, "FFF3F4F6", boldNavy, "right");
        ws.getCell(currentRow,7).value = totals[kat.key];
        ws.getCell(currentRow,7).numFmt = "#,##0.00 ₺";
        ws.getCell(currentRow,7).font = { bold:true, name:"Arial", size:10 };
        ws.getCell(currentRow,7).alignment = { horizontal:"right" };
        ws.getCell(currentRow,7).fill = { type:"pattern", pattern:"solid", fgColor:{ argb:"FFF3F4F6" } };
        ws.getCell(currentRow,7).border = cellBorder2;
        currentRow++;
      }

      const genToplam = Object.values(totals).reduce((s,v)=>s+v,0);
      ws.getRow(currentRow).height = 22;
      mergeAndStyle(currentRow, 2, 7, "İCMAL / SONUÇ", navy, boldWhite);
      currentRow++;
      for (const kat of KATS) {
        mergeAndStyle(currentRow, 2, 6, kat.label, null, { name:"Arial", size:9 }, "left");
        ws.getCell(currentRow,7).value = totals[kat.key];
        ws.getCell(currentRow,7).numFmt = "#,##0.00 ₺";
        ws.getCell(currentRow,7).alignment = { horizontal:"right" };
        ws.getCell(currentRow,7).fill = { type:"pattern", pattern:"solid", fgColor:{ argb:white } };
        ws.getCell(currentRow,7).border = cellBorder2;
        currentRow++;
      }
      ws.getRow(currentRow).height = 20;
      mergeAndStyle(currentRow, 2, 6, "GENEL TOPLAM", navy, boldWhite, "right");
      ws.getCell(currentRow,7).value = genToplam;
      ws.getCell(currentRow,7).numFmt = "#,##0.00 ₺";
      ws.getCell(currentRow,7).font = { bold:true, color:{ argb:white }, name:"Arial", size:11 };
      ws.getCell(currentRow,7).fill = { type:"pattern", pattern:"solid", fgColor:{ argb:navy } };
      ws.getCell(currentRow,7).alignment = { horizontal:"right", vertical:"middle" };
      ws.getCell(currentRow,7).border = cellBorder2;
      currentRow += 2;

      ws.getRow(currentRow).height = 18;
      mergeAndStyle(currentRow, 2, 3, "HARCAMAYI YAPAN", "FFE0F2FE", { bold:true, name:"Arial", size:9 });
      mergeAndStyle(currentRow, 4, 5, "BİRİM YÖNETİCİSİ (PM)", "FFD1FAE5", { bold:true, name:"Arial", size:9 });
      mergeAndStyle(currentRow, 6, 7, "GENEL MÜDÜR", "FFFEF3C7", { bold:true, name:"Arial", size:9 });
      currentRow++;
      ws.getRow(currentRow).height = 30;
      mergeAndStyle(currentRow, 2, 3, form.talep_eden_ad, null, { name:"Arial", size:10 });
      const pmAd = form.pm_onay_tarihi ? `Orhan Bedir\n${new Date(form.pm_onay_tarihi).toLocaleDateString("tr-TR")}` : "—";
      const dirAd = form.direktor_onay_tarihi ? `Düzgün Şimşek\n${new Date(form.direktor_onay_tarihi).toLocaleDateString("tr-TR")}` : "—";
      mergeAndStyle(currentRow, 4, 5, pmAd, null, { name:"Arial", size:10 });
      mergeAndStyle(currentRow, 6, 7, dirAd, null, { name:"Arial", size:10 });
      currentRow++;
      ws.getRow(currentRow).height = 18;
      mergeAndStyle(currentRow, 2, 3, "Tarih / İmza", null, { italic:true, color:{ argb:"FF9CA3AF" }, name:"Arial", size:8 });
      mergeAndStyle(currentRow, 4, 5, form.pm_not||"", null, { italic:true, color:{ argb:"FF374151" }, name:"Arial", size:8 });
      mergeAndStyle(currentRow, 6, 7, form.direktor_not||"", null, { italic:true, color:{ argb:"FF374151" }, name:"Arial", size:8 });

      ws.views = [{ state:"frozen", xSplit:0, ySplit:3, topLeftCell:"A4", showGridLines: false }];
    }

    const donemSafe = donem.replace(/[^0-9\-]/g,"");
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename="masraf_formlar_${donemSafe}.xlsx"; filename*=UTF-8''masraf_formlar_${donemSafe}.xlsx`);
    await wb.xlsx.write(res);
    res.end();
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ─────────────────────────────────────────────────────────────────────────────
// MALZEME YÖNETİMİ API
// ─────────────────────────────────────────────────────────────────────────────

// ── MALZEME YETKİ KATMANI (25.10.2026, Orhan — gizlilik) ─────────────────────────────────────────
// Eskiden /malzeme uçlarının hiçbirinde rol kontrolü yoktu: giriş yapan herkes (taşeron dahil) tüm talepleri,
// başkasının zimmetini ve depo stokunu görebiliyor; fiyat listesini, depoyu, dağıtımı ve talep onay durumunu
// değiştirebiliyordu. Kurallar web MalzemeYonetimiPanel / PersonelMalzemePanel ve eski mobil uygulamanın bugünkü
// kullanımından çıkarıldı:
//   yönetici (tüm talepler/dağıtım, talep onayı): yönetim rolleri + rollout/bölge müdürü + adı geçen e-postalar
//   depo (stok, sarf, dağıtım çıkışı, iade onayı): web canSeeDepo — admin, PM, direktör, Nurcan, Murat/Emre
//   fiyat listesi değiştirme: web canEditFiyat — admin, PM (+ direktör)
//   malzeme_goruntule izni: tüm listeleri görür (yazma yetkisi vermez)
//   diğer personel: yalnız kendi talepleri (oluştur, taslağını düzenle/sil, rollout onayına gönder) ve kendi zimmeti
//   (iade, sahaya çıkış). Kimlik oturumdan alınır; sorgudaki e-posta / ad yok sayılır.
// Alt marka kullanıcısı (Teknocenter/AHY) Şimşek deposunu görmez, kişisel kurala düşer. Taşeron hiç giremez.
const MALZEME_YONETICI_ROLLER = ["admin", "platform_admin", "direktor", "genel_mudur", "pm", "rollout_mudur", "bolge_mudur"];
const MALZEME_DEPO_ROLLER = ["admin", "platform_admin", "direktor", "genel_mudur", "pm"];
const MALZEME_DEPO_EMAIL = ["orhan.bedir@simsektel.com", "orhan.bedir@gmail.com", "duzgun.simsek@simsektel.com",
  "nurcan.kus@simsektel.com", "murat.istek@simsektel.com", "emre.akdegirmen@simsektel.com"];
const MALZEME_YONETICI_EMAIL = [...MALZEME_DEPO_EMAIL, "serdar.altinova@simsektel.com"];
const MALZEME_FIYAT_EMAIL = ["orhan.bedir@simsektel.com", "orhan.bedir@gmail.com", "duzgun.simsek@simsektel.com"];
const MALZEME_KISISEL_DURUM = ["TASLAK", "ROLLOUT_BEKLE"]; // personel → rollout müdürü (web saveTalep)
const _malzemeIc = (u) => !taseronMu(u) && !altMarkaKullanicisi(u);
const malzemeYonetici = (u) => _malzemeIc(u) && (MALZEME_YONETICI_ROLLER.includes(_rol(u)) || MALZEME_YONETICI_EMAIL.includes(_eposta(u)));
const malzemeDepoYetkili = (u) => _malzemeIc(u) && (MALZEME_DEPO_ROLLER.includes(_rol(u)) || MALZEME_DEPO_EMAIL.includes(_eposta(u)));
const malzemeFiyatYetkili = (u) => _malzemeIc(u) && (["admin", "platform_admin", "direktor", "pm"].includes(_rol(u)) || MALZEME_FIYAT_EMAIL.includes(_eposta(u)));
const malzemeTamOkuma = (u, req) => malzemeYonetici(u) || (!taseronMu(u) && req.izinler?.malzeme_goruntule === true);
async function malzemeTalepSahipligi(u, id) {
  const r = await pool.query(`SELECT id, durum, LOWER(TRIM(COALESCE(talep_eden_email,''))) AS eden,
    COALESCE(talep_edilen_personel,'') AS edilen FROM malzeme_talepler WHERE id=$1`, [Number(id)]);
  const t = r.rows[0];
  if (!t) return { talep: null };
  const kp = t.edilen ? await kendiPersonelKaydi(u) : null;
  return { talep: t, acan: t.eden !== "" && t.eden === _eposta(u), adina: !!kp && String(kp.id) === String(t.edilen) };
}
// Zimmet alıcısı mı? (GET /malzeme/dagitim?personel_email= eşleştirmesiyle aynı kural)
async function malzemeAliciMi(email, id) {
  const r = await pool.query(`SELECT 1 FROM malzeme_dagitim d WHERE d.id = $1 AND $2 <> '' AND (
      LOWER(TRIM(COALESCE(d.alici_personel_email,''))) = $2
      OR (COALESCE(d.alici_personel_email,'') = '' AND d.alici_personel_id IN (SELECT id FROM personel WHERE LOWER(TRIM(email)) = $2))
      OR (COALESCE(d.alici_personel_email,'') = '' AND LOWER(TRIM(COALESCE(d.alici_personel_ad,''))) =
          (SELECT LOWER(TRIM(name)) FROM users WHERE LOWER(TRIM(email)) = $2 LIMIT 1)))`, [Number(id), email]);
  return r.rows.length > 0;
}
// ── MALZEME STOK DEFTERİ (29.10.2026): /malzeme/stok/* + eski stok uçlarının yönlendirmesi — eski yetki katmanından ÖNCE.
// Saha kapsamı personelin firmasına göre: alt marka (Teknocenter) personeli yalnız MARKA ROLLOUT KAPSAMI'ndaki ya da kendisine
// atanmış sahaya tüketim yazar; Şimşek personeli Rollout listesindeki her sahaya.
async function personelSahaKapsami(firma) {
  const kod = String(firma || "ERC").trim().toUpperCase();
  if (!altMarkaMi(kod)) return null;
  return markaRolloutKapsami({ user: { hw_yukleme: false, marka: kod, role: "user" }, izinler: {} });
}
malzemeStok.kur(app, { pool, authMiddleware, optionalAuth, kendiPersonelKaydi, tenantContext: pool.tenantContext, malzemeDepoYetkili,
  malzemeTamOkuma, malzemeFiyatYetkili, taseronMu, personelSahaKapsami });
app.use(async (req, res, next) => {
  if (req.method === "OPTIONS" || !/^\/malzeme(\/|$)/.test(req.path)) return next();
  const u = optionalAuth(req);
  if (!u) return next(); // uçtaki authMiddleware 401 döner
  const red = (msg) => res.status(403).json({ ok: false, error: msg || "Malzeme işlemi için yetkiniz yok" });
  if (taseronMu(u)) return red("Taşeron hesabı malzeme modülünü kullanamaz");
  const ben = _eposta(u);
  if (!ben) return red("Oturumda e-posta yok");
  const yol = req.path.replace(/\/+$/, "");
  const m = req.method === "HEAD" ? "GET" : req.method;
  let mm;
  try {
    if (m === "GET") {
      // Talep formu yardımcıları: saha kodu önerisi, onay sayacı; malzeme adı / fiyat önerisi (yalnız Şimşek içi)
      if (/^\/malzeme\/(site-codes|bekleyen-count)$/.test(yol)) return next();
      if (/^\/malzeme\/(ara|fiyat-listesi)$/.test(yol)) return (_malzemeIc(u) || malzemeTamOkuma(u, req)) ? next() : red();
      if (malzemeTamOkuma(u, req)) return next();
      if (yol === "/malzeme/talepler" || yol === "/malzeme/dagitim") { req.malzemeKisisel = ben; return next(); }
      if ((mm = yol.match(/^\/malzeme\/talepler\/(\d+)$/))) {
        const s = await malzemeTalepSahipligi(u, mm[1]);
        if (!s.talep) return res.status(404).json({ ok: false, error: "Talep bulunamadı" });
        return (s.acan || s.adina) ? next() : red("Bu malzeme talebi size ait değil");
      }
      return red("Bu malzeme listesini görme yetkiniz yok");
    }
    if (/^\/malzeme\/fiyat-listesi(\/\d+)?$/.test(yol))
      return malzemeFiyatYetkili(u) ? next() : red("Fiyat listesini yalnız admin / PM değiştirebilir");
    if (/^\/malzeme\/(depo-stok(\/\d+)?|depo-stok-ekle|sarf(\/\d+)?)$/.test(yol) || (m === "POST" && yol === "/malzeme/dagitim")
        || /^\/malzeme\/dagitim\/\d+\/(iade-onayla|iade-reddet)$/.test(yol) || /^\/malzeme\/talepler\/\d+\/kalem-dagitildi$/.test(yol))
      return malzemeDepoYetkili(u) ? next() : red("Depo işlemleri için yetkiniz yok");
    if (/^\/malzeme\/talepler\/\d+\/durum$/.test(yol))
      return malzemeYonetici(u) ? next() : red("Malzeme talebi onay yetkiniz yok");
    if ((mm = yol.match(/^\/malzeme\/dagitim\/(\d+)\/(iade|saha-cikis|tutanak)$/))) {
      if (malzemeDepoYetkili(u)) return next();
      return (await malzemeAliciMi(ben, mm[1])) ? next() : red("Bu zimmet kaydı size ait değil");
    }
    if (m === "POST" && yol === "/malzeme/talepler") {
      if (malzemeYonetici(u)) return next();
      if (!req.body || typeof req.body !== "object") req.body = {};
      // Eski ERC mobil (build ≤30) personel talebini "PM_ONAY" ile gönderiyordu; web akışında personel talebi önce Rollout
      // Müdürü onayına gider (29.10.2026) — eski sürüm kırılmasın diye aynı anlama çevrilir, onay adımı atlanmaz.
      if (req.body.durum === "PM_ONAY") req.body.durum = "ROLLOUT_BEKLE";
      if (!MALZEME_KISISEL_DURUM.includes(req.body.durum || "TASLAK"))
        return red("Talebi taslak olarak kaydedebilir ya da rollout onayına gönderebilirsiniz");
      req.body.talep_eden_email = ben; // kimlik oturumdan — başkası adına talep açılamaz
      if (!req.body.talep_eden_ad) req.body.talep_eden_ad = u.name || ben;
      req.malzemeKisisel = ben;
      return next();
    }
    if ((mm = yol.match(/^\/malzeme\/talepler\/(\d+)$/)) && (m === "PUT" || m === "DELETE")) {
      if (malzemeYonetici(u)) return next();
      const s = await malzemeTalepSahipligi(u, mm[1]);
      if (!s.talep) return res.status(404).json({ ok: false, error: "Talep bulunamadı" });
      if (!s.acan) return red("Bu malzeme talebi size ait değil");
      if (!["TASLAK", "REDDEDILDI"].includes(s.talep.durum)) return red("Onaya gönderilmiş talep değiştirilemez");
      if (m === "PUT" && req.body?.durum === "PM_ONAY") req.body.durum = "ROLLOUT_BEKLE";
      if (m === "PUT" && !MALZEME_KISISEL_DURUM.includes(req.body?.durum || "TASLAK"))
        return red("Talebi taslak olarak kaydedebilir ya da rollout onayına gönderebilirsiniz");
      req.malzemeKisisel = ben;
      return next();
    }
    return malzemeYonetici(u) ? next() : red();
  } catch (e) { return res.status(500).json({ ok: false, error: e.message }); }
});

